/* ==== S150 DECLARATIONS (placed above their first use, for the reason S147 states) =========== */
#define IWXAB_S150_DOMAIN_POS                 16   /* IWL_FW_DBG_DOMAIN_POS, iwl-trans.h:59   */
#define IWXAB_S150_INI_PRESET                 1    /* 'InitDefault'.  MEASURED; see receipt.  */
#define IWXAB_S150_TP_EARLY                   1    /* IWL_FW_INI_TIME_POINT_EARLY             */
#define IWXAB_S150_SET_DBGC_DRAM_ADDR         6    /* iwl-dbg-tlv.c:914                       */
#define IWXAB_S150_SET_PERIPH_SCRATCH_HWM     7    /* iwl-dbg-tlv.c:949                       */
#define IWXAB_S150_BUF_ALLOC_MAX_NUM_FRAGS    16   /* fw/api/debug.h:362                      */
#define IWXAB_S150_SMEM_RC_NOT_TRIED          0x7fffffff

/* struct iwl_fw_ini_conf_set_tlv (fw/api/dbg-tlv.h:305-311): hdr + 3 dwords + addr_val[] */
struct iwxab_s150_conf_hdr {
    struct iwx_fw_ini_header hdr;      /* __le32 version; __le32 domain; */
    uint32_t time_point;
    uint32_t set_type;
    uint32_t addr_offset;
} __packed;

/* The payload, as PARSED from the image and then as PROGRAMMED.  Every field is published, so a
 * value that never got set reads as "not set" instead of as a plausible zero (0io/0q20). */
struct iwxab_s150_ini {
    uint32_t scanned;          /* the walk ran                                  */
    uint32_t refused;          /* a sizeof gate failed -- nothing may be armed   */
    uint32_t truncated;        /* the chain overran the image                   */
    uint32_t n_tlv;            /* TLVs walked                                   */
    uint32_t preset;           /* IWXAB_S150_INI_PRESET                          */
    uint32_t domains;          /* BIT(16+preset) -- the reference's filter        */
    uint32_t have_alloc;       /* DBGC1 DRAM allocation TLV accepted (LAST wins) */
    uint32_t alloc_off;        /* its file offset                               */
    uint32_t req_size;         /* its req_size                                  */
    uint32_t max_frags;        /* its max_frags_num                              */
    uint32_t min_size;         /* its min_size                                   */
    uint32_t frag0_size;       /* Linux's frag[0].size -- WHAT GOES ON THE WIRE   */
    uint32_t have_token;       /* a PERIPH_SCRATCH_HWM CONF_SET was accepted      */
    uint32_t token;            /* debug_token_config = ucode_preset              */
    uint32_t token_off;
    uint32_t have_dram;        /* a DBGC_DRAM_ADDR CONF_SET was accepted         */
    uint32_t smem_addr;        /* address + addr_offset = the HW-SMEM target     */
    uint32_t smem_off;
    uint32_t n_smem;           /* addr_val[] entries Linux would write           */
    uint32_t armed;            /* control_flags was modified                     */
    int32_t  alloc_rc;         /* iwx_dma_contig_alloc's return code             */
    int32_t  smem_rc;          /* iwx_write_mem's return code (NOT_TRIED if -)   */
    uint32_t smem_tried;
    uint32_t smem_payload[4];  /* struct iwl_dbgc1_info, on the wire             */
    uint32_t cf_before;
    uint32_t cf_after;
    uint32_t paddr_lo;
    uint32_t paddr_hi;
    uint32_t buf_size;         /* sc->fw_mon.size after the allocation           */
    uint32_t pub_n;
    /* S152: the pre-kick sample of the buffer, taken immediately after the memset. */
    uint32_t nz_arm;           /* non-zero dwords in the first 64 KiB RIGHT AFTER the memset */
    uint32_t f8_arm[8];        /* the first 8 dwords RIGHT AFTER the memset                 */
    uint32_t f8_arm_valid;
};
static struct iwxab_s150_ini iwxab_s150;
static char iwxab_s150_str[768];
/* S152: the pre-kick sample and a per-tick sample, as hex strings. */
static char iwxab_s152_arms[80], iwxab_s152_nows[80];

/* ==== S156 DECLARATIONS -- THE INI TIME POINT (the image's own USER_TRIGGER) ================= */
#define IWXAB_S156_MAX_REGIONS   64
#define IWXAB_S156_MAX_TP9        4
#define IWXAB_S156_READ_CAP    4096      /* bytes read per region (a CAP, stated in the receipt)  */
#define IWXAB_S156_DUMP_CAP   (16*1024)  /* the host dump buffer                                 */
#define IWXAB_S156_MAX_RES       16
#define IWXAB_S156_REC_MAGIC 0x53494e49u /* 'INIS' */

struct iwxab_s156_region {
    uint32_t used;
    uint32_t index;        /* id & IWL_FW_INI_REGION_ID_MASK (0xffff)                     */
    uint32_t raw_id;
    uint32_t type;
    uint32_t sub_type;
    uint32_t base;         /* special_mem.base_addr | internal_buffer.base_addr | addrs[0] */
    uint32_t size;         /* the TLV's own size (dev_addr.size / special_mem.size / ...) */
    uint32_t offset;
    uint32_t alloc_id;
    uint32_t name_len;
    char     name[33];
};

struct iwxab_s156_trig {
    uint32_t used;
    uint32_t off;
    uint32_t tp;
    uint32_t reason;
    uint32_t policy;
    uint64_t mask;
    uint32_t n_regions;
};

struct iwxab_s156_res {
    uint32_t index;
    uint32_t type;
    int32_t  rc;
    uint32_t addr;
    uint32_t size;
    uint32_t bytes;
    uint32_t nz;
    uint32_t d0, d1, d2, d3;
    char     name[33];
};

struct iwxab_s156_state {
    uint32_t scanned;
    uint32_t n_regions;
    uint32_t n_trig;
    uint32_t fired;            /* how many times the time point was applied               */
    uint32_t n_res;
    uint32_t dump_bytes;
    uint32_t dump_recs;
    uint32_t dump_namehits;    /* image region names found in the dump (OUR OWN WRITES)   */
    uint32_t dump_valid;
    uint32_t arm_fired_before_trigger;  /* ordering guard: the arm must have run        */
    struct iwxab_s156_trig   trig[IWXAB_S156_MAX_TP9];
    struct iwxab_s156_region reg[IWXAB_S156_MAX_REGIONS];
    struct iwxab_s156_res    res[IWXAB_S156_MAX_RES];
};
static struct iwxab_s156_state iwxab_s156;
static uint8_t iwxab_s156_dump[IWXAB_S156_DUMP_CAP];
static uint8_t iwxab_s156_tmp[IWXAB_S156_READ_CAP];   /* BSS: a 4 KiB frame in the init path is avoidable */

/* ==== S157 DECLARATIONS -- THE PERIODIC RING (the channel, pointed at the defect) ============ */
#define IWXAB_S157_RING        8      /* snapshots kept; the ring holds the NEWEST               */
#define IWXAB_S157_PERIOD      3      /* fire on every 3rd 1 Hz watchdog tick  => ~3 s          */
#define IWXAB_S157_MAXREG      7      /* the most regions one time point selected in this image  */
#define IWXAB_S157_TAGS        8      /* distinct collector record-type values tracked           */

struct iwxab_s157_snap {
    uint32_t ord;          /* per-record ordinal, monotonic                              */
    uint32_t tick;         /* the watchdog tick it was taken on                          */
    uint32_t rc_mask;      /* bit i = the i-th collected region's rc == 0                */
    uint32_t nz2048;       /* the DBGC1 census at the same instant                       */
    uint32_t nz64k;
    uint32_t chg4k;        /* S159: dwords changed since the previous snapshot, first 4 KiB */
    uint32_t chg64k;       /* S159: ... in the 64 KiB window                                */
    uint32_t cnt_n;        /* occurrences of the constant 0xeea20782 in the 64 KiB window */
    uint32_t cnt_first;    /* the FIRST counter that rides with it                       */
    uint32_t cnt_last;     /* the LAST one                                              */
    uint32_t tag_val[IWXAB_S157_TAGS];   /* record-type values, with counts                */
    uint32_t tag_cnt[IWXAB_S157_TAGS];
    uint32_t n_tag;
    uint32_t n_reg;
    uint32_t reg_idx[IWXAB_S157_MAXREG];
    uint32_t reg_rc[IWXAB_S157_MAXREG];
    uint32_t reg_bytes[IWXAB_S157_MAXREG];
    uint32_t reg_d0[IWXAB_S157_MAXREG];
    uint32_t reg_d1[IWXAB_S157_MAXREG];
};

struct iwxab_s157_state {
    uint32_t pn;           /* publications -- advances every publish (0pd)               */
    uint32_t ord;          /* how many time points have fired                           */
    uint32_t lost;         /* PUBLISHED: snapshots that could not be kept               */
    uint32_t n;            /* snapshots taken                                           */
    uint32_t head;         /* next slot                                                 */
    uint32_t armed_seen;   /* the arm was armed when the ring started                   */
    uint32_t period;
    struct iwxab_s157_snap s[IWXAB_S157_RING];
};
static struct iwxab_s157_state iwxab_s157;
static char iwxab_s157_str[1024];

/* ==== S158 DECLARATIONS -- THE HE GATE + THE DERIVED FIELD =================================== */
struct iwxab_s158_state {
    uint32_t vi;            /* the mac-ctxt builder ran                                  */
    uint32_t n;             /* how many mac-ctxt commands carried the field              */
    uint32_t he;            /* THE GATE: ni_flags & IEEE80211_NODE_HE (HE negotiated)    */
    uint32_t ni_flags;
    uint32_t heon;          /* ic_flags & IEEE80211_F_HEON (HE enabled for the phymode)  */
    uint32_t modecaps;      /* ic_modecaps -- bit (1 << IEEE80211_MODE_11AX)             */
    uint32_t cap0;          /* ic_he_cap_elem.mac_cap_info[0] we advertise               */
    uint32_t wgen;          /* THE WIRE VALUE: cmd.wifi_gen.he_support                    */
    uint32_t wgen_last;
};
static struct iwxab_s158_state iwxab_s158;
static char iwxab_s158_str[320];

/* ==== S159 DECLARATIONS -- THE DISCRIMINATOR ((i) live writer vs (ii) unreadable window) ======== */
#define IWXAB_S159_WIN   16384      /* the 64 KiB window, in dwords -- the same one the census uses  */
static uint32_t iwxab_s159_prev[IWXAB_S159_WIN];   /* BSS: the previous read, for the change count   */
static uint32_t iwxab_s159_prev_valid;
struct iwxab_s159_disc {
    uint32_t chg4k;     /* dwords that CHANGED since the previous snapshot, first 4 KiB            */
    uint32_t chg64k;    /* ... in the whole 64 KiB window                                          */
    uint32_t c5;        /* occurrences of 0xc5c5c5c5 (a classic fill pattern) in the window        */
    uint32_t c45;       /* occurrences of 0x45c5c5c5                                               */
};
static struct iwxab_s159_disc iwxab_s159;
/* ==== END S159 DECLARATIONS ================================================================= */

/* ==== S162 DECLARATIONS -- THE FIRMWARE RESET HANDSHAKE'S READ-OUT ===========================
 * *** THE PROTOCOL IS NOT AN INSTRUMENT; THIS IS. ***  The sender and the receiver live where
 * the reference puts them -- next to `iwx_stop_device` and inside the MSI-X cause dispatch --
 * and are DECLARED in ItlIwx.hpp.  What is declared here is the read-out the round must
 * publish: attempts, completions, timeouts, and the ELAPSED MICROSECONDS of each handshake,
 * because "does the handshake complete" is the precondition of every pre-registered branch and
 * P3 (a timeout) is itself a finding.
 * TWO CHANNELS, for the two failure modes this project has already paid for:
 *   (1) ONE `XYLog` line per handshake, carrying its own elapsed us (a handshake is rare --
 *       once per stop_device -- so there is nothing to rate-limit);
 *   (2) the same numbers as the IOREG property `iwxctl_s162`, refreshed by the 1 Hz watchdog,
 *       because a log line can be wrapped out of the buffer and a property query cannot.
 * `0b` BY VALUE reads (2) on the RUNNING build before the install and again after.
 * `last_clear` is the STALE-CAUSE CONTROL: the cause register re-read immediately after the
 * sender ACKs bit 2.  If bit 2 is still set there, the cause is level-asserted by the
 * firmware, a "completion" could be that stale level rather than an answer to THIS request,
 * and `last_stale` says so in the receipt instead of letting the round over-read its own
 * number.
 * ============================================================================ */
#define IWXAB_S162_EVENTS 8
struct iwxab_s162_state {
    uint32_t attempts;      /* handshakes entered                                       */
    uint32_t ok;            /* completed: state was OK after the bounded wait           */
    uint32_t timeouts;      /* 200 ms elapsed with the state still REQUESTED            */
    uint32_t unsol;         /* bit 2 seen with the state NOT REQUESTED (not our ack)    */
    /* S216: THE GATE'S OWN RECEIPT.  A handshake that is NOT sent must not be
     * indistinguishable from an instrument that never ran, so every skip is
     * counted BY REASON (Linux's gates are the reasons). */
    uint32_t skipped;       /* handshakes not sent (all reasons)                          */
    uint32_t skip_dead;     /* ... state was NO_FW: a death was declared                 */
    uint32_t skip_capa;     /* ... image does not advertise capa 57                       */
    uint32_t skip_ver;      /* ... IWL_UCODE_MAJOR <= 77 (0eaa1f24)                      */
    uint32_t skip_nostart;  /* ... firmware never started (uc_ok == 0) or pre-Bz          */
    uint32_t last_result;   /* 1 = completed, 0 = timed out                             */
    uint32_t last_us;       /* elapsed microseconds of the last handshake               */
    uint32_t last_us_max;   /* maximum elapsed microseconds so far                      */
    uint32_t last_sleeps;   /* sleeps the last handshake took                           */
    uint32_t last_pre;      /* HW cause register BEFORE the window                      */
    uint32_t last_clear;    /* HW cause register AFTER the ACK, before the unmask       */
    uint32_t last_post;     /* HW cause register at the end of the window               */
    uint32_t last_stale;    /* 1 = bit 2 was still set after the ACK (control failed)   */
    uint32_t last_mask;     /* HW mask before the window                                */
    uint32_t last_winmask;  /* HW mask during the window                                */
    /* THE ELAPSED-US OF *EACH* HANDSHAKE, in a ring.  A single `last_us` cannot answer "how long
     * did the attempt that COMPLETED take" on a boot that also has a timeout, and this round's
     * brief asks for each.  The ring is indexed by the attempt number (1-based, so slot
     * (attempts-1) % IWXAB_S162_EVENTS); the publisher prints the newest events in order. */
    uint8_t  ev_result[IWXAB_S162_EVENTS];  /* 1 = completed, 0 = timed out per attempt      */
    uint32_t ev_us[IWXAB_S162_EVENTS];      /* elapsed microseconds per attempt              */
};
static struct iwxab_s162_state iwxab_s162;
static char iwxab_s162_str[832];
static void iwxabS162Publish(struct iwx_softc *sc, const char *why, int logit);
/* ==== END S162 DECLARATIONS ================================================================= */

/* ==== S164 DECLARATIONS -- THE LIVENESS WITNESS AND THE AT-HALT CAPTURE ======================
 * *** THE ONE THING NEVER DONE IS LOOKING AT THE DEVICE IN THE WINDOW BETWEEN "IT STOPS" AND
 * "WE RESET IT": 15 SECONDS WIDE, WITH THE PROVEN 100 ms TIMER ALREADY INSIDE IT. ***
 * THIS IS A WITNESS, NOT A FIX: it reads, it publishes, and it lets the 15 s fuse's `SW_RESET`
 * run exactly as before.  NOTHING HERE CHANGES DRIVER BEHAVIOUR.
 *
 * THE LIVENESS SIGNAL IS `intrFilter` -- the PRIMARY interrupt filter's own entry count, HOST
 * MEMORY, incremented in `intrFilter()` and derived from no register read.  §163's unambiguous
 * datum was that it FROZE at 2765 for ~80 s across the hold while 13 pings and 4 TX bursts
 * entered the filter ZERO times, and resumed at 3887 only after the SW_RESET + reload.  It is
 * read FIRST and it costs nothing.
 *
 * THE THRESHOLD, DECLARED AND JUSTIFIED BEFORE THE BOOT (not fitted to this boot):
 *   1000 ms without a filter entry, with the interface RUNNING (`IFF_RUNNING`), the firmware
 *   ALIVE (`uc_ok && uc_intr`), the witness ARMED (an advance was seen while up) and the
 *   station at `IEEE80211_S_RUN`.
 *   WHY 1 s: (a) an associated station is on-channel with a 100 ms beacon interval, so a healthy
 *   link offers the filter ~10 entries/s; (b) the measured pathological gap is ~80 s, 80x the
 *   threshold; (c) the ONLY automatic reset is the TX-armed 15 s fuse, so 1 s leaves a ~14 s
 *   margin to publish before it -- and the margin is MEASURED in the receipt (`dt_cap`).
 *   THE THRESHOLD IS ITSELF TESTED BY THIS BLOCK: the (filter delta, elapsed) ring publishes the
 *   healthy inter-advance gaps too, so if `gapmax` on a healthy stretch approaches 1 s, the
 *   receipt says the threshold is wrong instead of hiding it.
 *
 * THE CAPTURE, AND WHAT MAKES IT TRUSTWORTHY:
 *   (1) BAR0 reads ONLY in the first stage, ALL lock-free, so the state is published BEFORE any
 *       lock-taking read can perturb GP_CNTRL (the 0q21 table is on the implementation).
 *   (2) the firmware error tables SECOND, via `iwx_read_mem` -- which TAKES THE NIC LOCK, so it
 *       is BOUNDED (150 ms access poll + the sentinel EIO) and its elapsed time is published;
 *       EIO IS ACCEPTED AS A DATUM, published with the address and the errno.
 *   (3) PUBLISHED TWICE: the BAR0 stage publishes BEFORE the lock is taken and the complete
 *       receipt AFTER it, so a reset landing in between still leaves the BAR0 state.
 *   (4) THE ORDERING IS PROVED TWO WAYS: IN SOURCE ORDER (the capture is triggered from the
 *       100 ms timer, and `iwx_stop_device` is the only SW_RESET site on Bz) and by a RUNTIME
 *       ORDINAL: `iwxabS164ResetMark()` snapshots the published-capture counters IMMEDIATELY
 *       BEFORE the `SW_RESET`, and the receipt prints what the reset itself saw (`saw_bar`,
 *       `saw_cap`) plus the measured `dt_cap` milliseconds between publish and reset.  A capture
 *       published after the reset would read `saw_cap=0`.
 * ============================================================================ */
#define IWXAB_S164_THRESH_MS   1000    /* DECLARED threshold: 1 s with no filter entry        */
#define IWXAB_S164_RING        8       /* the (filter delta, elapsed) justification ring      */
#define IWXAB_S164_ET_DWORDS   16      /* bounded error-table read: 16 dwords                 */
#define IWXAB_S164_CAP_MAX     8       /* captures per boot; a stall re-arms only on advance  */
struct iwxab_s164_gap {
    uint32_t delta;   /* IWX_PROBE_INTR_COUNT advance                                      */
    uint32_t ms;      /* elapsed since the previous advance                                */
};
struct iwxab_s164_state {
    /* ---- the liveness witness (host memory only) ---- */
    uint32_t tick_n;           /* 100 ms timer entries  (NOT `ticks`: that is a macro)   */
    uint32_t up_ticks;         /* entries with the up gate satisfied                      */
    uint32_t primed;           /* 1 = the first advance has been seen (it is not a gap)    */
    uint32_t armed;            /* 1 = an advance was seen while up                        */
    uint32_t advances;         /* advances observed while up                              */
    uint32_t last_nf;          /* previous filter count                                   */
    uint64_t last_adv_t;       /* mach time of the last advance                           */
    uint32_t gap_max_ms;       /* MAX inter-advance gap                                   */
    uint32_t g250, g500, g1s;  /* gaps >= 250 / 500 / 1000 ms                             */
    uint32_t zmax_ms;          /* MAX zero-run seen while armed                           */
    uint32_t dlast;            /* delta of the last advance                               */
    uint32_t ring_n;
    struct iwxab_s164_gap ring[IWXAB_S164_RING];
    /* ---- the capture ---- */
    uint32_t cap_n;            /* captures taken (ordinal of the LAST)                    */
    uint32_t cap_pending;      /* 1 = captured; wait for a new advance before re-arming   */
    uint32_t cap_full;         /* 1 = CAP_MAX reached, no more captures                   */
    uint64_t cap_t;            /* mach time at capture entry                              */
    uint32_t cap_elapsed_ms;   /* the zero-run that triggered the LAST capture            */
    uint32_t cap_race;         /* 1 = a SW_RESET landed DURING this capture               */
    uint32_t cap_us;           /* entry -> published, microseconds                        */
    uint32_t cap_nf;           /* filter count at the capture                             */
    uint32_t r_hwc, r_hwm, r_fhc, r_fhm;   /* MSI-X causes / masks                        */
    uint32_t r_gp, r_ipc, r_rst, r_hif;    /* GP_CNTRL, IPC_STATE, RESET, HW_IF_CONFIG     */
    uint32_t r_int, r_intm, r_fhs;         /* INT, INT_MASK, FH_INT_STATUS                 */
    uint32_t r_rb, r_cur;                  /* rb_stts (host DMA) and rxq.cur               */
    uint32_t r_gp2;                        /* GP_CNTRL AGAIN, after the lock-taking reads  */
    uint32_t et_lmac, et_umac;             /* runtime bases                                */
    int32_t  et_lmac_rc, et_umac_rc;       /* 0 / EIO / EBUSY / -2 noaddr / -3 forbidden   */
    uint32_t et_lmac_us, et_umac_us;       /* elapsed of each read, microseconds           */
    uint32_t et_lmac_w0, et_lmac_w1;       /* first raw dwords (the sentinel lives here)   */
    uint32_t et_umac_w0, et_umac_w1;
    uint32_t et_skip;                      /* bit0/1 = that table was a FORBIDDEN address  */
    /* the FIRST capture in the boot, kept as a summary: if an early healthy-looking capture
     * happened before the halt, the receipt must be able to show it rather than let the last
     * capture silently stand for the halt. */
    uint32_t first_el_ms, first_hwc, first_gp, first_ipc, first_rst;
    /* ---- the reset ordinal (written by iwx_stop_device immediately before SW_RESET) ---- */
    volatile uint32_t rst_seq;
    volatile uint64_t rst_t;
    volatile uint32_t rst_saw_bar, rst_saw_cap;
    volatile uint32_t bar_pub_seq, cap_pub_seq;
    volatile uint64_t bar_pub_t, cap_pub_t;
};
static struct iwxab_s164_state iwxab_s164;
