/* ==== S103bj COUNTERS -- DECLARED HERE, ABOVE THEIR FIRST USE (`0ih`: C++ needs the declaration
 * ==== before the use at file scope, and the S103az round lost a build to exactly this).
 * ===== THE ARM THIS INSTRUMENTS (`0if`, ONE VARIABLE): *WHEN* THE POWER COMMAND IS SENT.
 * The port sends `iwx_power_mac_update_mode()` from exactly ONE place -- `iwx_run()` -- and never
 * again, while Linux calls `iwl_mld_update_mac_power(mld, vif, false)` from its `bss_info_changed`
 * handler (mld/mac80211.c:721) and from the `BSS_CHANGED_BEACON_INFO` branch (mld/mac80211.c:1353).
 * `iwx_mac_ctxt_task()` IS this port's bss_info_changed follower: its four schedulers are
 * `iwx_updateprot`, `iwx_updateslot`, `iwx_updateedca` and `iwx_updatedtim` -- every beacon-derived
 * state hook the port has -- so the arm re-sends the power command there.
 * THE BUILDERS ARE DELIBERATELY NOT TOUCHED: flags, both data timeouts and the keep-alive
 * expression are CLOSED by four refuted arms and re-opening them would bundle a second variable.
 * NOTE, RE-DERIVED BEFORE THE BUILD AND RECORDED SO A NULL CANNOT BE RE-READ (`0hu`): at realistic
 * AP parameters (intval ~100 TU, dtim_period in {1,2,3}) the payload is INVARIANT to the DTIM --
 * `keep_alive = MAX(3 * dtim_period * ni_intval, 25000) / 1000` saturates at 25 s either way, and
 * Linux's `max(..., 25)` saturates identically.  **So this arm changes WHEN, NOT WHAT** -- which is
 * the hypothesis: the FIRMWARE RE-ARMS ITS AWAKE SCHEDULE ON RECEIPT, as Linux relies on.
 * ZERO DEVICE ACCESS: increments and plain loads of host memory only.  DELETE BEFORE THE PR (`0dp`). */
static volatile unsigned iwxab_s103bj_dtim_n;    /* iwx_updatedtim() FIRED (the beacon-info event) */
static volatile unsigned iwxab_s103bj_ctxt_n;    /* iwx_mac_ctxt_task() reached the ARM            */
static volatile unsigned iwxab_s103bj_pw_n;      /* iwx_power_mac_update_mode() calls, ALL of them*/
static volatile unsigned iwxab_s103bj_pw_ctxt;   /* ... of which came FROM THE ARM                */
static volatile unsigned iwxab_s103bj_err;       /* last error returned by the ARM's send         */
static volatile unsigned iwxab_s103bj_dt_first;  /* ni_dtimperiod at the FIRST power call  <-- PREMISE */
static volatile unsigned iwxab_s103bj_iv_first;  /* ni_intval     at the FIRST power call         */
static volatile unsigned iwxab_s103bj_dt_last;   /* ni_dtimperiod at the LAST power call          */
static volatile unsigned iwxab_s103bj_iv_last;   /* ni_intval     at the LAST power call          */
static volatile unsigned iwxab_s103bj_ka_last;   /* keep_alive_seconds actually sent              */
static volatile unsigned iwxab_s103bj_fl_last;   /* flags actually sent                           */
static volatile unsigned iwxab_s103bj_sz_last;   /* bytes actually sent (the v2/v3 FORM)          */
static volatile unsigned iwxab_s103bj_ver_last;  /* TLV-48 cmd_ver for (0x01,0xa9)                */
static void iwxabS103bjPublish(struct iwx_softc *sc);

/* The ring distance between the device's write pointer and the driver's read pointer, in slots.
 * DEFINED HERE, ABOVE ITS FIRST USE (`ItlIwx::free()` is at ~line 470 and the counter block is at
 * ~line 10100), because C++ needs the definition before the use at file scope.
 * ⚠️ THE MODULUS IS *MEASURED*, NOT ASSUMED (`0kt`): `IWX_RX_MQ_RING_COUNT` = 8192 = 2^13 and the
 * hardware field is a 16-bit register carrying that same 13-bit index (`rawmax = 8191`, the SS32
 * receipt on this card), so `raw mod 8192` and `cur mod 8192` live in the same modulus and the
 * subtraction is well defined.  Returns -1 for UNKNOWN, which the callers must never read as 0
 * (`0io`: a zero needs a positive companion).  PURE HOST-MEMORY READ: no register, no lock. */
static inline int
iwxabS103azOcc(struct iwx_softc *sc, uint16_t *rawp)
{
    uint16_t raw;
    int d;

    if (sc->rxq.stat == NULL) {
        if (rawp != NULL)
            *rawp = 0xffff;
        return -1;
    }
    raw = *(volatile uint16_t *)sc->rxq.stat;
    if (rawp != NULL)
        *rawp = raw;
    d = (int)(raw & (IWX_RX_MQ_RING_COUNT - 1)) - (int)(sc->rxq.cur & (IWX_RX_MQ_RING_COUNT - 1));
    if (d < 0)
        d += IWX_RX_MQ_RING_COUNT;
    return d;
}

/*
 * ==== S72h: ONE definition of the device's "this address is unreadable" ====
 * Linux's iwl_trans_is_hw_error_value() (iwl-trans.h) defines ONE family of
 * values meaning "the device could not perform this access": 0xa5a5a5aX and
 * 0x5a5a5a5X.  Every test of that family in this file now calls this function,
 * because it used to be spelled out at five independent sites and the copies
 * had ALREADY drifted: iwx_read_mem() checked both halves of the family, the
 * KEY14 probe and the MSR/CSR path in iwx_intr() checked only 0xa5a5a5a0, and
 * the unlocked peek iwxabS60Peek() checked NOTHING at all -- which is how an
 * unreadable address came back impersonating a measurement (S72e/S72f).
 *
 * The sentinel is a RESULT, not noise and not a condition: the probe layer must
 * never report it as data, and a gate must never treat it as an event (see
 * iwxabS60Absent()).  A marker that is distinguishable from a value must also be
 * distinguishable from a CONDITION.
 *
 * SCOPE, stated so it is not over-read: this catches the documented sentinel
 * family only.  It does NOT validate arbitrary content -- a plausible-looking
 * wrong value still passes.
 *
 * THIS FUNCTION IS REAL DRIVER CODE AND MUST NOT BE DELETED WITH THE PROBES:
 * iwx_read_mem() and iwx_intr() call it on the production path.
 */
static inline bool iwx_hw_error_value(uint32_t v)
{
    return (v & ~0xf) == 0xa5a5a5a0 || (v & ~0xf) == 0x5a5a5a50;
}

/* ==== TEMPORARY PROBE (uncommitted, round 1): interrupt arrival counter ==== */
static volatile uint32_t IWX_PROBE_INTR_COUNT = 0;
/* ==== END TEMPORARY PROBE ==== */

/*
 * ==== S79: THE INIT-CYCLE COUNTER (temporary probe, but the counter is the point) ====
 *
 * WHY.  Round S78.3 read two S64 change-series inside one pulled unified-log file
 * as "two complete init cycles in one boot", and built a mechanism on it (a
 * re-initialisation zeroing the LMAC error record).  It is not: a pulled log
 * window is a SET OF BOOTS (rule 0bc).  `07-scripts/s79-cycles.py` segments all
 * 25 held port logs and finds `kmod_start` = `alive_wait` = `iwx_stop_device` = 1
 * in all 35 boot segments -- one init cycle per boot, no exceptions.
 *
 * That was established from the OUTSIDE (log segmentation).  This counter
 * establishes it from the INSIDE and makes the rule-0bc class of error
 * impossible on the port side from now on: every S79 line prints `cyc=`, the
 * counter increments on each ALIVE notification, and a boot that ever ran two
 * cycles would say so in its own log (`cyc=2`).  A boot that never came alive
 * prints `cyc=0`, which is itself the measurement.
 *
 * It is deliberately NOT reset anywhere: it counts ALIVE notifications since the
 * kext loaded, which is exactly one driver lifetime, which is one boot.
 */
static volatile int IWX_PROBE_S79_CYCLES = 0;
static int iwxabS79GetCycle(void) { return IWX_PROBE_S79_CYCLES; }
/* ==== END S79 CYCLE COUNTER ==== */

/* Round S43: how many INIT_COMPLETE_NOTIF notifications this boot has seen.
 * The wait for it is a bare tsleep with a 2 s timeout, and the notification's
 * handler had no log line, so "the firmware never sent it" and "it arrived
 * before the sleep and the wakeup was lost" were indistinguishable.  With S43
 * the second case cannot happen (the PHY config is sent first and the firmware
 * answers in ~20 ms), but the counter is what proves which one occurred. */
static volatile uint32_t IWX_PROBE_INIT_COMPLETE_NOTIFS = 0;

/*
 * Round S47: cumulative evidence about interrupts, so that "the firmware sent
 * nothing" is a measurement and not an inference from a rate-limited log.  The
 * per-interrupt probes are rate-limited (S41, because of the S40a storm), so an
 * interrupt between n=13 and n=999 leaves no trace in the log at all.
 */
static volatile uint32_t IWX_PROBE_MSIX_NONZERO = 0;
static volatile uint32_t IWX_PROBE_MSIX_LAST_FH = 0;
static volatile uint32_t IWX_PROBE_MSIX_LAST_HW = 0;

/*
 * Round S48: trace the next N RX packets, turned ON immediately before the PHY
 * configuration command is sent.  "The firmware answered nothing" has to be a
 * measurement of the packet stream, not an inference: this prints, for every
 * packet that arrives in that window, the RX header's qid/idx/group/cmd and the
 * payload length -- enough to see a command response (bit 0x80 clear,
 * qid = command queue), a notification (bit 0x80 set) or nothing at all.
 */
static volatile uint32_t IWX_PROBE_RXTRACE = 0;

/* ==== TEMPORARY PROBE (uncommitted, round S29, hypothesis R1) ==============
 * Kick-relative TIME SERIES.  One sample per ~20 ms from just BEFORE the kick
 * (index 0) through ~2 s after it.  The whole investigation has owned only four
 * instants, the earliest already 0.755 s after the kick, so a failure that
 * happens between samples has been invisible to every method used so far; this
 * series exists to be compared with the Linux instrument BY THE ORDER OF FIRST
 * CHANGES AND THE INTERVALS, not by values.
 *
 * READS ONLY -- no register writes anywhere in this block.  Every prph read uses
 * the UNLOCKED accessor, so the instrument does not perturb the state it
 * measures; UREG_CHICK is deliberately NOT part of the cadence (it is read once,
 * after the series, and that reading is flagged), and GP_CNTRL is read before
 * anything that could clear BZ_MAC_ACCESS_REQ (rule 0l).
 */
void ItlIwx::
iwxabSerSample(struct iwx_softc *sc, int i)
{
    uint32_t rb = 0xffffffff;
    
    if (sc->rxq.stat != NULL)
        rb = (*(volatile uint16_t *)sc->rxq.stat) & 0xfff;
    
    XYLog("PROBE SER %s i=%03d FUNC_SCRATCH=%08x CTXT_BOOT_CTRL=%08x IML_SIZE=%08x CSR_IML_RESP=%08x UCODE_LOAD_STATUS=%08x CPU_INIT_RUN=%08x MSIX_HW_CAUSES=%08x CSR_INT=%08x GP_CNTRL=%08x RB_STTS=%08x uc_ok=%d\n",
          (i == 0) ? "PRE" : "POST", i,
          IWX_READ(sc, IWX_CSR_FUNC_SCRATCH),
          IWX_READ(sc, IWX_CSR_CTXT_INFO_BOOT_CTRL),
          IWX_READ(sc, IWX_CSR_IML_SIZE_ADDR),
          IWX_READ(sc, 0x12c),      /* CSR_IML_RESP_ADDR */
          iwx_read_prph_unlocked(sc, GEN3_UMAC_PRPH_OFFSET + IWX_UREG_UCODE_LOAD_STATUS),
          iwx_read_prph_unlocked(sc, GEN3_UMAC_PRPH_OFFSET + IWX_UREG_CPU_INIT_RUN),
          IWX_READ(sc, IWX_CSR_MSIX_HW_INT_CAUSES_AD),
          IWX_READ(sc, IWX_CSR_INT),
          IWX_READ(sc, IWX_CSR_GP_CNTRL),
          rb,
          (int)sc->sc_uc.uc_ok);
}

void ItlIwx::
iwxabSerChickPost(struct iwx_softc *sc)
{
    XYLog("PROBE SER CHICK_POST=%08x (read ONCE after the series, out of cadence: this side reads it UNLOCKED so it perturbs nothing; Linux's CHICK read takes NIC access and does perturb, so CHICK_POST is NOT strictly comparable across sides -- the comparable CHICK datum stays the S25 t0/t1 pair)\n",
          iwx_read_prph_unlocked(sc, GEN3_UMAC_PRPH_OFFSET + IWX_UREG_CHICK));
}
/* ==== END TEMPORARY PROBE ==== */

/* ==== S204 BLOCK START ========================================================================
 * S204 -- THE RX/ISR EVENT CLOCK: WHEN THE DEVICE SERVES A DOORBELLED FRAME, WHICH HOST-VISIBLE
 * EVENT DID IT FOLLOW?
 *
 * S203 measured that a doorbelled frame is held until the next host event (the next ping request
 * under a periodic host ping) and that the doorbell itself is prompt (6 us).  It could NOT tell
 * WHICH event the completion followed, because the instrument carried no RX/ISR event time.
 *
 * WHAT IS RECORDED, ALL ON mach_absolute_time (x86_64: nanoseconds), ALL HOST MEMORY:
 *   ISR        every entry of `iwx_intr_msix` and `iwx_intr`, with the causes the dispatch acts
 *              on; the previous ISR entry is kept so a completion can be measured against it.
 *   FILTER     every entry of `intrFilter` (the primary interrupt filter).
 *   WALK       every entry/exit of `iwx_notif_intr` (the ONLY consumer of the RX ring), the
 *              device's closed_rb_num read at entry, and the number of ring entries walked --
 *              i.e. the wake-to-consumption distance.
 *   RXWR       every RX write-pointer push (`iwx_rx_wrptr`, HBUS_TARG_WRPTR RX-Q0).
 *   IFINPUT    the moment the ring walk hands its packets to the network stack (`if_input`),
 *              i.e. the point INSIDE the walk at which the reply is generated and doorbelled.
 *   DB         every TX doorbell: the value written, qid/idx/cur/len/type/subtype/802.11 seq, and
 *              its distance to the last ISR, walk, RX-wrptr push and filter entry; also whether
 *              the doorbell was written from INSIDE a notification walk (`db_inwalk`) and how many
 *              ring entries that walk had consumed at that instant.
 *   DONE       every TX completion, matched to its doorbell by (qid, TFD slot idx), with the same
 *              distances measured from the completion.  A completion matched to no doorbell in the
 *              ring is COUNTED (`nomatch`) and published, never dropped.
 *   The completion is also matched from the BA/flush retire path (`iwx_ampdu_txq_advance`), so a
 *   completion that arrives as a BlockAck is not invisible.
 *
 * THE PER-FRAME DELTAS THE ANALYSIS NEEDS ARE COMPUTED AT THE EVENT, not reconstructed later:
 *     d_isr      = done - the ISR entry that is running this walk
 *     d_walk     = done - this walk's entry
 *     d_isrprev  = done - the ISR entry BEFORE the running one
 *     d_walkprev = done - the walk entry BEFORE this one
 *     d_rxwr     = done - the last RX write-pointer push
 *   and, at the doorbell: db_isr/db_walk/db_walkprev/db_rxwr, db_inwalk, db_walkn.
 * A completion that lands in a walk whose entry is ~0 before it is a completion CONSUMED by that
 * walk; d_isrprev/d_walkprev bound when the completion could have been WRITTEN (after the previous
 * walk's closed_rb_num read).  The two together separate "written by this RX" from "written earlier
 * and only read now" WITHOUT the wire.
 *
 * ZERO DEVICE ACCESS IS ADDED (`0bq`): no register read, no prph access, no command, no lock.  The
 * only stores are to host memory.  The publisher rides the proven 100 ms timer, like every census
 * in this tree.  DELETE THIS WHOLE BLOCK BEFORE THE PR (`0dp`). ================================= */
#define IWXAB_S204_EVN      256u
#define IWXAB_S204_EVNM     (IWXAB_S204_EVN - 1u)
#define IWXAB_S204_TXN      64u
#define IWXAB_S204_TXNM     (IWXAB_S204_TXN - 1u)
#define IWXAB_S204_TXPUB    20u
#define IWXAB_S204_EVPUB    32u
#define IWXAB_S204_UNK      0xffffffffu

#define IWXAB_S204_K_ISR_MSIX 1u
#define IWXAB_S204_K_ISR_LEG  2u
#define IWXAB_S204_K_FILTER   3u
#define IWXAB_S204_K_NOTIF    4u
#define IWXAB_S204_K_NOTIF_HW 5u
#define IWXAB_S204_K_NOTIF_X  6u
#define IWXAB_S204_K_IFINPUT  7u
#define IWXAB_S204_K_RXWR     8u
#define IWXAB_S204_K_DB       9u
#define IWXAB_S204_K_DONE     10u
#define IWXAB_S204_K_DONE_ADV 11u

/* BUILD A = 0 (instrument only).  BUILD B = 1 (one functional change: a TX doorbell written from
 * inside an RX notification walk is deferred until AFTER the RX write-pointer push).  One constant,
 * one code path -- the two builds differ by this number and by the flush call site. */
#define IWXAB_S204_DEFER    0

struct iwxab_s204_pend {
    struct iwx_tx_ring *ring;
    uint32_t cur;
    uint32_t txi;
};

struct iwxab_s204_ev {
    uint64_t t;
    uint32_t kind, a, b, c;
};

struct iwxab_s204_tx {
    uint64_t t_db, t_wr, t_done;
    uint32_t gen;
    uint32_t qid, idx, cur, len, ftype, subtype, wseq;
    uint32_t db_isr_us, db_isrprev_us, db_walk_us, db_walkprev_us, db_rxwr_us, db_filt_us,
             db_ifin_us;
    uint32_t db_walkid, db_walkn, db_inwalk;
    uint32_t done_seq, done_ssn, done_adv;
    uint32_t d_isr_us, d_isrprev_us, d_walk_us, d_walkprev_us, d_rxwr_us, d_filt_us, d_ifin_us;
    uint32_t done_walkid, done_walkn, done_inwalk, done_fh, done_hw;
};

static struct iwxab_s204_ev iwxab_s204_ev[IWXAB_S204_EVN];
static struct iwxab_s204_tx iwxab_s204_tx[IWXAB_S204_TXN];
static volatile uint32_t iwxab_s204_evhead, iwxab_s204_txhead, iwxab_s204_pub_n;
static volatile uint64_t iwxab_s204_t_isr, iwxab_s204_t_isr_prev,
                        iwxab_s204_t_walk, iwxab_s204_t_walk_prev,
                        iwxab_s204_t_rxwr, iwxab_s204_t_filt, iwxab_s204_t_ifin;
static volatile uint32_t iwxab_s204_walk_id, iwxab_s204_walk_n, iwxab_s204_inwalk;
static volatile uint32_t iwxab_s204_walk_hw, iwxab_s204_walk_prev_hw;
static volatile uint32_t iwxab_s204_n_isr, iwxab_s204_n_isr_q01, iwxab_s204_n_isr_oth,
                        iwxab_s204_n_filter, iwxab_s204_n_notif, iwxab_s204_n_pkt,
                        iwxab_s204_n_rxwr, iwxab_s204_n_ifin, iwxab_s204_n_db,
                        iwxab_s204_n_done, iwxab_s204_n_match, iwxab_s204_n_nomatch,
                        iwxab_s204_n_adv;
static volatile uint32_t iwxab_s204_isr_fh, iwxab_s204_isr_hw;
static char iwxab_s204_line[8192];

/* ---- the event log ------------------------------------------------------------------------- */
static void
iwxabS204Ev(uint32_t kind, uint32_t a, uint32_t b, uint32_t c)
{
    uint32_t i = iwxab_s204_evhead++;
    struct iwxab_s204_ev *e = &iwxab_s204_ev[i & IWXAB_S204_EVNM];

    e->t = mach_absolute_time();
    e->kind = kind;
    e->a = a;
    e->b = b;
    e->c = c;
}

static uint32_t
iwxabS204AgeUs(uint64_t now, uint64_t then)
{
    if (then == 0 || now < then)
        return IWXAB_S204_UNK;
    return (uint32_t)((now - then) / 1000ull);
}

/* ---- the interrupt side -------------------------------------------------------------------- */
static void
iwxabS204Isr(uint32_t kind, uint32_t fh, uint32_t hw)
{
    uint64_t now = mach_absolute_time();

    iwxab_s204_t_isr_prev = iwxab_s204_t_isr;
    iwxab_s204_t_isr = now;
    iwxab_s204_isr_fh = fh;
    iwxab_s204_isr_hw = hw;
    iwxab_s204_n_isr++;
    if (kind == IWXAB_S204_K_ISR_MSIX &&
        (fh & (IWX_MSIX_FH_INT_CAUSES_Q0 | IWX_MSIX_FH_INT_CAUSES_Q1)))
        iwxab_s204_n_isr_q01++;
    else
        iwxab_s204_n_isr_oth++;
    iwxabS204Ev(kind, fh, hw, iwxab_s204_n_isr);
}

static void
iwxabS204Filter(void)
{
    iwxab_s204_t_filt = mach_absolute_time();
    iwxab_s204_n_filter++;
    iwxabS204Ev(IWXAB_S204_K_FILTER, iwxab_s204_n_filter, 0, 0);
}

static void
iwxabS204NotifEntry(void)
{
    iwxab_s204_t_walk_prev = iwxab_s204_t_walk;
    iwxab_s204_walk_prev_hw = iwxab_s204_walk_hw;
    iwxab_s204_t_walk = mach_absolute_time();
    iwxab_s204_walk_id++;
    iwxab_s204_walk_n = 0;
    iwxab_s204_inwalk = 1;
    iwxab_s204_n_notif++;
    iwxabS204Ev(IWXAB_S204_K_NOTIF, iwxab_s204_walk_id, iwxab_s204_walk_prev_hw, 0);
}

static void
iwxabS204NotifHw(uint32_t hw)
{
    iwxab_s204_walk_hw = hw;
    iwxabS204Ev(IWXAB_S204_K_NOTIF_HW, hw, 0, 0);
}

static void
iwxabS204WalkPkt(void)
{
    iwxab_s204_walk_n++;
    iwxab_s204_n_pkt++;
}

static void
iwxabS204IfInput(void)
{
    iwxab_s204_t_ifin = mach_absolute_time();
    iwxab_s204_n_ifin++;
    iwxabS204Ev(IWXAB_S204_K_IFINPUT, iwxab_s204_walk_id, iwxab_s204_walk_n, 0);
}

static void
iwxabS204NotifExit(uint32_t n)
{
    iwxab_s204_inwalk = 0;
    iwxabS204Ev(IWXAB_S204_K_NOTIF_X, n, iwxab_s204_walk_hw, iwxab_s204_walk_id);
}

static void
iwxabS204RxWrptr(uint32_t val)
{
    iwxab_s204_t_rxwr = mach_absolute_time();
    iwxab_s204_n_rxwr++;
    iwxabS204Ev(IWXAB_S204_K_RXWR, val, 0, 0);
}

/* ---- the TX side --------------------------------------------------------------------------- */
static uint32_t
iwxabS204TxDb(struct iwx_softc *sc, struct iwx_tx_ring *ring, int idx, unsigned cur,
              unsigned len, unsigned type, unsigned subtype,
              const struct ieee80211_frame *wh)
{
    uint64_t now = mach_absolute_time();
    uint32_t i = iwxab_s204_txhead++;
    struct iwxab_s204_tx *t = &iwxab_s204_tx[i & IWXAB_S204_TXNM];

    (void)sc;
    memset(t, 0, sizeof(*t));
    t->gen = i;
    t->t_db = now;
    t->t_wr = now;
    t->qid = (uint32_t)ring->qid;
    t->idx = (uint32_t)idx;
    t->cur = (uint32_t)cur;
    t->len = (uint32_t)len;
    t->ftype = (uint32_t)type;
    t->subtype = (uint32_t)subtype;
    t->wseq = (wh != NULL) ?
        ((uint32_t)((const uint8_t *)wh)[22] | ((uint32_t)((const uint8_t *)wh)[23] << 8)) : 0xffffu;
    t->db_isr_us     = iwxabS204AgeUs(now, iwxab_s204_t_isr);
    t->db_isrprev_us = iwxabS204AgeUs(now, iwxab_s204_t_isr_prev);
    t->db_walk_us    = iwxabS204AgeUs(now, iwxab_s204_t_walk);
    t->db_walkprev_us = iwxabS204AgeUs(now, iwxab_s204_t_walk_prev);
    t->db_rxwr_us    = iwxabS204AgeUs(now, iwxab_s204_t_rxwr);
    t->db_filt_us    = iwxabS204AgeUs(now, iwxab_s204_t_filt);
    t->db_ifin_us    = iwxabS204AgeUs(now, iwxab_s204_t_ifin);
    t->db_walkid = iwxab_s204_walk_id;
    t->db_walkn = iwxab_s204_walk_n;
    t->db_inwalk = iwxab_s204_inwalk;
    iwxab_s204_n_db++;
    iwxabS204Ev(IWXAB_S204_K_DB, ((uint32_t)ring->qid << 16) | (cur & 0xffffu),
                len, (type << 8) | subtype);
    return i;
}

/* the actual doorbell write, in one place, so a deferred arm is the same write */
static struct iwxab_s204_pend iwxab_s204_pend[8];
static volatile uint32_t iwxab_s204_pend_n;
static volatile uint32_t iwxab_s204_n_defer;

static void
iwxabS204RingDoorbell(struct iwx_softc *sc, struct iwx_tx_ring *ring, uint32_t val,
                      uint32_t txi)
{
#if IWXAB_S204_DEFER
    if (iwxab_s204_inwalk) {
        uint32_t i = iwxab_s204_pend_n;
        if (i < 8u) {
            iwxab_s204_pend[i].ring = ring;
            iwxab_s204_pend[i].cur = val & 0xffffu;
            iwxab_s204_pend[i].txi = txi;
            iwxab_s204_pend_n = i + 1u;
            iwxab_s204_n_defer++;
            return;
        }
    }
#endif
    (void)txi;
    IWX_WRITE(sc, IWX_HBUS_TARG_WRPTR, val);
}

/* called AFTER the RX write-pointer push: the deferred doorbell is written here, and only if the
 * ring's index has not moved on (a newer doorbell from another thread already advanced it). */
static void
iwxabS204Flush(struct iwx_softc *sc)
{
#if IWXAB_S204_DEFER
    uint32_t i, n = iwxab_s204_pend_n;

    iwxab_s204_pend_n = 0;
    for (i = 0; i < n; i++) {
        struct iwx_tx_ring *ring = iwxab_s204_pend[i].ring;
        uint32_t txi = iwxab_s204_pend[i].txi;
        if (txi != 0xffffffffu) {
            struct iwxab_s204_tx *t = &iwxab_s204_tx[txi & IWXAB_S204_TXNM];
            if (t->gen == txi && t->t_done == 0)
                t->t_wr = mach_absolute_time();
        }
        if (ring != NULL && (ring->cur & 0xffffu) == iwxab_s204_pend[i].cur)
            IWX_WRITE(sc, IWX_HBUS_TARG_WRPTR, ring->qid << 16 | ring->cur);
    }
#else
    (void)sc;
#endif
}

/* match the completion to its doorbell by (qid, TFD slot) and stamp it. */
static void
iwxabS204TxDone(struct iwx_tx_ring *ring, int idx, uint32_t ssn, uint32_t adv)
{
    uint64_t now = mach_absolute_time();
    uint32_t i, start;
    struct iwxab_s204_tx *t, *hit = NULL;

    iwxab_s204_n_done++;
    if (adv)
        iwxab_s204_n_adv++;
    start = (iwxab_s204_txhead > IWXAB_S204_TXN) ? (iwxab_s204_txhead - IWXAB_S204_TXN) : 0u;
    for (i = iwxab_s204_txhead; i > start; i--) {
        t = &iwxab_s204_tx[(i - 1u) & IWXAB_S204_TXNM];
        if (t->gen != (i - 1u))
            continue;
        if (t->qid != (uint32_t)ring->qid || t->idx != (uint32_t)idx)
            continue;
        if (t->t_done != 0) {
            /* the single path's own slot is retired again by iwx_ampdu_txq_advance: not a miss */
            if (now >= t->t_done && (now - t->t_done) < 50000000ull)
                return;
            continue;
        }
        hit = t;
        break;
    }
    if (hit == NULL) {
        iwxab_s204_n_nomatch++;
        iwxabS204Ev(adv ? IWXAB_S204_K_DONE_ADV : IWXAB_S204_K_DONE,
                    0x80000000u | (uint32_t)ring->qid, (uint32_t)idx, ssn);
        return;
    }
    iwxab_s204_n_match++;
    hit->t_done = now;
    hit->done_seq = ssn;
    hit->done_ssn = ssn;
    hit->done_adv = adv;
    hit->d_isr_us     = iwxabS204AgeUs(now, iwxab_s204_t_isr);
    hit->d_isrprev_us = iwxabS204AgeUs(now, iwxab_s204_t_isr_prev);
    hit->d_walk_us    = iwxabS204AgeUs(now, iwxab_s204_t_walk);
    hit->d_walkprev_us = iwxabS204AgeUs(now, iwxab_s204_t_walk_prev);
    hit->d_rxwr_us    = iwxabS204AgeUs(now, iwxab_s204_t_rxwr);
    hit->d_filt_us    = iwxabS204AgeUs(now, iwxab_s204_t_filt);
    hit->d_ifin_us    = iwxabS204AgeUs(now, iwxab_s204_t_ifin);
    hit->done_walkid = iwxab_s204_walk_id;
    hit->done_walkn = iwxab_s204_walk_n;
    hit->done_inwalk = iwxab_s204_inwalk;
    hit->done_fh = iwxab_s204_isr_fh;
    hit->done_hw = iwxab_s204_isr_hw;
    iwxabS204Ev(adv ? IWXAB_S204_K_DONE_ADV : IWXAB_S204_K_DONE,
                ((uint32_t)ring->qid << 16) | ((uint32_t)idx & 0xffffu), ssn, 1);
}

static void
iwxabS204TxAdvance(struct iwx_tx_ring *ring, int idx)
{
    iwxabS204TxDone(ring, idx, 0xffffffffu, 1u);
}

/* ---- the publisher (rides the proven 100 ms timer) ------------------------------------------ */
static void
iwxabS204Publish(struct iwx_softc *sc)
{
    char *s = iwxab_s204_line;
    uint64_t now;
    uint32_t fh, i, start, eh;
    int o = 0, n;

    if (sc == NULL || sc->sc_pcitag == NULL)
        return;
    iwxab_s204_pub_n++;
    now = mach_absolute_time();
    fh = iwxab_s204_txhead;
    start = (fh > IWXAB_S204_TXPUB) ? (fh - IWXAB_S204_TXPUB) : 0u;
    n = snprintf(s, sizeof(iwxab_s204_line),
                 "S204 pub=%u isr=%u q01=%u oth=%u filt=%u notif=%u pkt=%u rxwr=%u ifin=%u "
                 "db=%u done=%u match=%u nomatch=%u adv=%u defer=%u walkid=%u now=%llu |",
                 iwxab_s204_pub_n, iwxab_s204_n_isr, iwxab_s204_n_isr_q01,
                 iwxab_s204_n_isr_oth, iwxab_s204_n_filter, iwxab_s204_n_notif,
                 iwxab_s204_n_pkt, iwxab_s204_n_rxwr, iwxab_s204_n_ifin,
                 iwxab_s204_n_db, iwxab_s204_n_done, iwxab_s204_n_match,
                 iwxab_s204_n_nomatch, iwxab_s204_n_adv, iwxab_s204_n_defer,
                 iwxab_s204_walk_id, (unsigned long long)now);
    o = (n < 0) ? 0 : n;
    for (i = start; i < fh; i++) {
        struct iwxab_s204_tx *t = &iwxab_s204_tx[i & IWXAB_S204_TXNM];
        unsigned long long du;
        if (t->gen != i)
            continue;
        if (o > (int)sizeof(iwxab_s204_line) - 320)
            break;
        du = (t->t_done != 0 && now >= t->t_done) ?
             (unsigned long long)((now - t->t_done) / 1000ull) : 0xffffffffull;
        n = snprintf(s + o, sizeof(iwxab_s204_line) - (size_t)o,
                     " %u,%llu,%llu,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u|",
                     i, (unsigned long long)((now >= t->t_wr) ? ((now - t->t_wr) / 1000ull) : 0ull),
                     du, t->qid, t->idx, t->cur, t->len, t->wseq,
                     (t->ftype << 8) | t->subtype,
                     t->db_isr_us, t->db_isrprev_us, t->db_walk_us, t->db_walkprev_us,
                     t->db_rxwr_us, t->db_ifin_us, t->db_walkid, t->db_walkn, t->db_inwalk,
                     t->d_isr_us, t->d_isrprev_us, t->d_walk_us, t->d_walkprev_us,
                     t->d_rxwr_us, t->d_ifin_us,
                     t->done_walkid, t->done_walkn, t->done_adv,
                     t->done_fh, t->done_hw, t->done_seq);
        if (n < 0)
            break;
        o += n;
    }
    if (o > (int)sizeof(iwxab_s204_line) - 120)
        o = (int)sizeof(iwxab_s204_line) - 120;
    n = snprintf(s + o, sizeof(iwxab_s204_line) - (size_t)o, " |");
    if (n > 0)
        o += n;
    eh = iwxab_s204_evhead;
    start = (eh > IWXAB_S204_EVPUB) ? (eh - IWXAB_S204_EVPUB) : 0u;
    for (i = start; i < eh; i++) {
        struct iwxab_s204_ev *e = &iwxab_s204_ev[i & IWXAB_S204_EVNM];
        if (o > (int)sizeof(iwxab_s204_line) - 100)
            break;
        n = snprintf(s + o, sizeof(iwxab_s204_line) - (size_t)o,
                     " %u,%u,%u,%u,%u", e->kind, iwxabS204AgeUs(now, e->t), e->a, e->b, e->c);
        if (n < 0)
            break;
        o += n;
    }
    s[sizeof(iwxab_s204_line) - 1u] = 0;
    {
        OSString *os = OSString::withCString(s);
        if (os != NULL) {
            sc->sc_pcitag->setProperty("iwxctl_s204", os);
            os->release();
        }
    }
}
/* ==== S204 BLOCK END ========================================================================== */

/* ==== S207 BLOCK START ========================================================================
 * S207 -- S206 proved the TX AGGREGATION PATH is what holds a lone frame.  This round asked the
 * next question by BODY: does the port or Linux program a BOUNDED aggregation/fetch wait?
 *
 * THE BY-BODY ANSWER (S207, Linux 7.2.8 `drivers/net/wireless/intel/iwlwifi`):
 *   - the only "TX queue timeout" is `wd_timeout` (IWL_LONG_WD_TIMEOUT = 10000 ms).  It arms a
 *     STUCK-QUEUE watchdog when a queue goes from empty to non-empty (`iwl_txq_gen2_tx`), i.e. a
 *     10 s hang detector -- it does not bound a 3-120 ms hold and it is not an aggregation wait.
 *     THIS PORT HAS NO SUCH TIMER AT ALL (the port's own S56 note says the queue-stuck diagnostic
 *     "does not exist on this device family").
 *   - the SCD queue configuration on gen2 is a firmware command, `SCD_QUEUE_CONFIG_CMD` v3.  This
 *     port sends it with the same operation/sta_mask/tid/flags(=0)/cb_size form and the same
 *     address fields as `iwl_txq_dyn_alloc`; the only difference is the REQUESTED ring size
 *     (256 here; Linux asks 256/1024/2048 by HT/HE/EHT and 4096 only for Bz SILICON_A_STEP --
 *     this part reports CNVI prod 0x930 (BZ_U) with step promoted A->B, so Linux's 4096 arm does
 *     NOT apply).
 *   - the SCD PRPH aggregation registers (`SCD_AGGR_SEL`, `SCD_QUEUECHAIN_SEL`) are programmed only
 *     by the GEN1 transport; Linux's gen2/Bz path never writes them and this port only READS SCD
 *     state in a probe.  The TX command carries no aggregation flag (`iwl_tx_flags` has none; this
 *     port sets none), and S204 already established the TFD/byte-count/doorbell write is Linux's,
 *     byte for byte.  The MLD TLC config (the only rate config this firmware takes) has no
 *     aggregation-time field; `max_tx_op` is 0 in Linux and 0 here.
 *   => NO BOUNDED-WAIT REGISTER EXISTS.  The wait is FIRMWARE-INTERNAL.  (P2.)
 *
 * THE FALLBACK THE PRE-REGISTRATION NAMES FOR P2 IS CANDIDATE 3, THIS BLOCK.
 *
 * THE POLICY, NAMED: a QoS data frame that would take its TID's TX-BA (aggregation) queue is sent
 * on the NON-AGGREGATED `first_data_qid` instead IFF the last submission on that same TID was more
 * than IWXAB_S207_LONE_GAP_US microseconds ago (or there was none this boot).  Every other frame
 * keeps the aggregation queue.  There is no frame-type test: the driver cannot see "ping reply";
 * what it can see is "this TID has been idle", which is exactly what makes a frame lone.
 *
 * WHY THE GAP AND NOT `ring->queued == 0`: at a bulk push the aggregation ring is empty between
 * many pairs of frames too, so an emptiness test would move most of the stream to the
 * non-aggregated queue -- the S206 trade (4.4-9.9 vs 53.8 Mbit/s).  The gap separates the 1 s reply
 * cadence from the sub-millisecond frame cadence of a 53 Mbit/s stream by four orders of magnitude.
 *
 * THE COST, COUNTED AT THE POINT OF EFFECT (`0se`): `lone` = frames bypassed, `agg` = frames kept
 * on the BA queue.  The bulk push's cost is lone/(lone+agg) during T; the ping's benefit is the qid
 * of each reply in the S204 per-frame record (qid is already recorded there).
 * ============================================================================================== */
#define IWXAB_S207_LONE_BYPASS   1
#define IWXAB_S207_LONE_GAP_US   20000

static volatile uint32_t iwxab_s207_lone;
static volatile uint32_t iwxab_s207_agg;
static volatile uint32_t iwxab_s207_pub_n;
static volatile uint32_t iwxab_s207_last_us[16];
static char iwxab_s207_line[192];

/* The timebase on this x86_64 guest is 1/1: mach_absolute_time() is nanoseconds, the same source
 * the S204 record's clock uses.  Host memory only: no register read, no lock, no command. */
static inline uint32_t
iwxabS207NowUs(void)
{
    return (uint32_t)(mach_absolute_time() / 1000);
}

static void
iwxabS207Publish(struct iwx_softc *sc)
{
    char *s = iwxab_s207_line;
    int n;

    if (sc == NULL || sc->sc_pcitag == NULL)
        return;
    iwxab_s207_pub_n++;
    n = snprintf(s, sizeof(iwxab_s207_line),
                 "S207 bypass=%d gap_us=%d lone=%u agg=%u pub=%u",
                 IWXAB_S207_LONE_BYPASS, IWXAB_S207_LONE_GAP_US,
                 iwxab_s207_lone, iwxab_s207_agg, iwxab_s207_pub_n);
    if (n < 0)
        return;
    {
        OSString *os = OSString::withCString(s);
        if (os != NULL) {
            sc->sc_pcitag->setProperty("iwxctl_s207", os);
            os->release();
        }
    }
}
/* ==== S207 BLOCK END ========================================================================== */

/* ==== S208 FORWARD DECLARATIONS (the hooks that run before the block's definition) ============ */
static void iwxabS208BaStart(struct iwx_softc *sc, uint8_t tid);
static void iwxabS208BaAccept(struct iwx_softc *sc, struct ieee80211_node *ni, uint8_t tid,
                              int qid);
static void iwxabS208BaRxAccept(struct iwx_softc *sc, struct ieee80211_node *ni, uint8_t tid);
static void iwxabS208RxMgmt(const struct ieee80211_frame *wh, uint32_t len);
/* ==== S208 FORWARD DECLARATIONS END ========================================================== */

/* ==== S209 FORWARD DECLARATION =============================================================== */
/* Written by iwx_tx immediately before the doorbell and read by the S208 per-frame record, so
 * every TX row says by value whether THIS frame was handed to the device as plain data. */
static volatile uint32_t iwxab_s209_cur_strip;
static void iwxabS209Publish(struct iwx_softc *sc);


/* ==== FIX (round S34, R3): THE RX FREE-BUFFER WRITE POINTER, THE Bz WAY ====
 * On Bz the write pointer of the RX free-RBD ring is pushed through
 * HBUS_TARG_WRPTR with the queue encoded in the upper half:
 *
 *   Linux: iwl_write32(trans, HBUS_TARG_WRPTR,
 *                      rxq->write_actual | HBUS_TARG_WRPTR_RX_Q(rxq->id));
 *          HBUS_TARG_WRPTR_RX_Q(q) = ((q) + 512) << 16
 *          (pcie/gen1_2/rx.c:195-198, iwl-csr.h:555-558)
 *
 * The AX210-and-earlier RFH_Q0_FRBDCB_WIDX_TRG register is NOT used for Bz by
 * the working driver -- the port wrote it in two places, i.e. it pushed
 * free-buffer updates into a register this device does not consult.  The value
 * is unchanged (the caller's index, aligned down to 8, exactly as the port's
 * existing code computed it); only the register and the encoding change.
 */
void ItlIwx::
iwx_rx_wrptr(struct iwx_softc *sc, uint32_t idx, const char *where)
{
    uint32_t val = idx & ~7u;
    
    if (sc->sc_device_family >= IWX_DEVICE_FAMILY_BZ) {
        IWX_WRITE(sc, IWX_HBUS_TARG_WRPTR, val | ((0 + 512) << 16));
        iwxabS204RxWrptr(val);
        XYLog("PROBE S34 wrptr %s: HBUS_TARG_WRPTR=0x%08x (idx=%u enc=RX_Q0)\n",
              where, val | ((0 + 512) << 16), idx);
    } else {
        IWX_WRITE(sc, IWX_RFH_Q0_FRBDCB_WIDX_TRG, val);
        iwxabS204RxWrptr(val);
        XYLog("PROBE S34 wrptr %s: RFH_Q0_FRBDCB_WIDX_TRG=0x%08x (idx=%u, pre-Bz path)\n",
              where, val, idx);
    }
}
/* ==== END FIX ==== */

/* ==== TEMPORARY PROBE (uncommitted, round S30, R2: stall or halt?) =========
 * The S29 series showed the port's device doing NOTHING for 2 s after +43 ms.
 * Question: is the firmware STALLED (waiting, will act later) or HALTED (stopped
 * executing)?  Method: poll at ~2 ms for ~10 s and log ONLY when a sampled field
 * changes, plus a heartbeat every ~500 ms, plus a final total.  A run that ends
 * with changes == the number seen in the first 43 ms is a *proof* that nothing
 * moved for the remaining ten seconds, not an absence of evidence.
 *
 * READS ONLY; same unlocked accessors as the S29 series (rule 0l).  UREG_CHICK
 * stays out of the cadence.  The error table is read three times, OUT of the
 * cadence and flagged, because iwx_read_mem() takes the NIC lock.
 */
void ItlIwx::
iwxabSerLongRun(struct iwx_softc *sc)
{
    uint32_t v[13], prev[13];
    int i, have = 0, changes = 0;
    uint32_t rb;
    
    /*
     * S31 correction to this instrument (rule 0l, disclosed in S30): the error
     * table is read ONCE, AFTER the series, and never before or during it.  The
     * S30 run read it before its first sample, and iwx_read_mem() takes the NIC
     * lock, which clears GP_CNTRL BIT(21) -- invalidating EVERY GP_CNTRL sample
     * of that run.  Since this round's whole point is BIT(21), the cadence must
     * contain no lock-taking read at all, exactly like the S29 series.
     */
    /*
     * Round S50: 5000 -> 250 samples (~0.6 s) so that the driver's post-kick
     * sequence runs at LINUX-LIKE TIMING.  With 5000 samples the series blocks
     * the boot thread for ~11.7 s between the kick and iwx_load_pnvm(), i.e. the
     * firmware sat in its post-ALIVE state for ~11.7 s before the driver sent
     * INIT_EXTENDED_CFG_CMD and PHY_CONFIGURATION_CMD, where Linux sends them
     * ~20 ms after ALIVE.  The question this boot answers: is the firmware's
     * silence towards PHY_CONFIGURATION_CMD caused by that delay (i.e. by this
     * instrument -- rule 0l) or is it independent of timing?  250 samples still
     * spans the +37 ms burst and the +262 ms ALIVE, so the instrument keeps its
     * subject.  DISCLOSED INSTRUMENT CHANGE: this is not a driver change.
     */
    for (i = 0; i < 250; i++) {
        rb = (sc->rxq.stat != NULL) ? ((*(volatile uint16_t *)sc->rxq.stat) & 0xfff) : 0xffffffff;
        v[0] = IWX_READ(sc, IWX_CSR_FUNC_SCRATCH);
        v[1] = IWX_READ(sc, IWX_CSR_CTXT_INFO_BOOT_CTRL);
        v[2] = IWX_READ(sc, IWX_CSR_IML_SIZE_ADDR);
        v[3] = IWX_READ(sc, 0x12c);   /* CSR_IML_RESP_ADDR */
        v[4] = iwx_read_prph_unlocked(sc, GEN3_UMAC_PRPH_OFFSET + IWX_UREG_UCODE_LOAD_STATUS);
        v[5] = iwx_read_prph_unlocked(sc, GEN3_UMAC_PRPH_OFFSET + IWX_UREG_CPU_INIT_RUN);
        v[6] = IWX_READ(sc, IWX_CSR_MSIX_HW_INT_CAUSES_AD);
        v[7] = IWX_READ(sc, IWX_CSR_INT);
        v[8] = IWX_READ(sc, IWX_CSR_GP_CNTRL);
        v[9] = rb;
        /*
         * Round S35 step 1 (diagnose from bytes, change nothing): the MSI-X mask
         * planes.  If the automask bit for the vector is left set, the device
         * masks the vector after the first message and every later cause latches
         * in MSIX_HW_CAUSES without ever being delivered -- which is exactly
         * intr=1 while the ALIVE cause sits set at 0x01.
         */
        v[10] = IWX_READ(sc, IWX_CSR_MSIX_HW_INT_MASK_AD);
        v[11] = IWX_READ(sc, IWX_CSR_MSIX_AUTOMASK_ST_AD);
        v[12] = IWX_READ(sc, IWX_CSR_MSIX_FH_INT_MASK_AD);
        
        if (!have || memcmp(v, prev, sizeof(v)) != 0) {
            changes++;
            XYLog("PROBE LONG CHANGE n=%d i=%d FUNC_SCRATCH=%08x CTXT_BOOT_CTRL=%08x IML_SIZE=%08x CSR_IML_RESP=%08x UCODE_LOAD_STATUS=%08x CPU_INIT_RUN=%08x MSIX_HW_CAUSES=%08x CSR_INT=%08x GP_CNTRL=%08x RB_STTS=%08x HW_MASK=%08x AUTOMASK=%08x FH_MASK=%08x uc_ok=%d intr=%u\n",
                  changes, i, v[0], v[1], v[2], v[3], v[4], v[5], v[6], v[7], v[8], v[9],
                  v[10], v[11], v[12],
                  (int)sc->sc_uc.uc_ok, (unsigned)IWX_PROBE_INTR_COUNT);
            memcpy(prev, v, sizeof(v));
            have = 1;
        } else if ((i % 250) == 0) {
            XYLog("PROBE LONG HEARTBEAT i=%d t_ms~%d changes_so_far=%d (field set unchanged)\n",
                  i, i * 2, changes);
        }
        
        tsleep_nsec(&sc->sc_uc, 0, "iwxuc", MSEC_TO_NSEC(2));
    }
    
    if (sc->sc_uc.uc_lmac_error_event_table[0] != 0) {
        uint32_t et[4];
        int erc;
        memset(et, 0xde, sizeof(et));
        erc = iwx_read_mem(sc, sc->sc_uc.uc_lmac_error_event_table[0], et, 4);
        XYLog("PROBE LONG ERRTBL tag=end rc=%d valid=0x%08x error_id=0x%08x (LOCK-TAKING, out of cadence)\n",
              erc, et[0], et[1]);
    }
    
    XYLog("PROBE LONG DONE samples=250 changes=%d uc_ok=%d intr=%u (S50: SHORT series, linux-like timing; changes>3 means the device moved after the +43 ms burst)\n",
          changes, (int)sc->sc_uc.uc_ok, (unsigned)IWX_PROBE_INTR_COUNT);
}
/* ==== END TEMPORARY PROBE ==== */

