bool ItlIwx::attach(IOPCIDevice *device)
{
    pci.pa_tag = device;
    pci.workloop = getMainWorkLoop();
    if (!iwx_attach(&com, &pci)) {
        detach(device);
        releaseAll();
        return false;
    }
    return true;
}

void ItlIwx::
detach(IOPCIDevice *device)
{
    struct _ifnet *ifp = &com.sc_ic.ic_ac.ac_if;
    struct iwx_softc *sc = &com;
    
    for (int txq_i = 0; txq_i < nitems(sc->txq); txq_i++)
        iwx_free_tx_ring(sc, &sc->txq[txq_i]);
    iwx_free_rx_ring(sc, &sc->rxq);
    iwx_dma_contig_free(&sc->ict_dma);
    iwx_dma_contig_free(&com.ctxt_info_dma);
    ieee80211_ifdetach(ifp);
    taskq_destroy(systq);
    taskq_destroy(com.sc_nswq);
    releaseAll();
}

void ItlIwx::
releaseAll()
{
    iwxabS202Teardown();
    pci_intr_handle *intrHandler = com.ih;
    
    if (intrHandler) {
        if (intrHandler->intr && intrHandler->workloop) {
//            intrHandler->intr->disable();
            intrHandler->workloop->removeEventSource(intrHandler->intr);
            intrHandler->intr->release();
        }
        intrHandler->intr = NULL;
        intrHandler->workloop = NULL;
        intrHandler->arg = NULL;
        intrHandler->dev = NULL;
        intrHandler->func = NULL;
        intrHandler->release();
        com.ih = NULL;
    }
    pci.pa_tag = NULL;
    pci.workloop = NULL;
}

void ItlIwx::free()
{
    XYLog("%s\n", __FUNCTION__);
    iwxabS202Teardown();
    /* ==== S103az teardown: the sampler timer is an event source on the HAL's workloop and MUST be
     * cancelled before that workloop goes away, or a later fire lands in freed memory.  Cancel and
     * release here, then drop the pointer so a re-attach creates a fresh one. */
    if (iwxab_s103az_timer != NULL) {
        iwxab_s103az_timer->cancelTimeout();
        iwxab_s103az_timer->disable();
        iwxab_s103az_timer->release();
        iwxab_s103az_timer = NULL;
    }
    super::free();
}

