        size_t n9 = sc->prph_scratch_dma.size / 4;
        for (k = 0; k + 8 <= n9 && k < 16; k += 8)
            XYLog("PROBE ZERO9 raw prph_scratch[%02llu] PRE-MEMSET: %08x %08x %08x %08x %08x %08x %08x %08x\n",
                  (unsigned long long)k, zero9[k], zero9[k+1], zero9[k+2], zero9[k+3],
                  zero9[k+4], zero9[k+5], zero9[k+6], zero9[k+7]);
        for (k = 0; k < n9; k++)
            zero9[k] = 0x00000000;
