int ItlIwx::
iwx_match(IOPCIDevice *device)
{
    int devId = device->configRead16(kIOPCIConfigDeviceID);
    int r = pci_matchbyid(PCI_VENDOR_INTEL, devId, iwx_devices,
                          nitems(iwx_devices));
    /*
     * Log the table size and the result. A table that is unexpectedly empty or
     * short here would explain a match failure that the source does not.
     */
    XYLog("%s: iwx_match devId=0x%04x table=%zu -> %d\n", __FUNCTION__,
          devId, (size_t)nitems(iwx_devices), r);
    return r;
}

int ItlIwx::
iwx_preinit(struct iwx_softc *sc)
{
    struct ieee80211com *ic = &sc->sc_ic;
    struct _ifnet *ifp = IC2IFP(ic);
    int err;
    static int attached;
    
    err = iwx_prepare_card_hw(sc);
    if (err) {
        XYLog("%s: could not initialize hardware\n", DEVNAME(sc));
        return err;
    }
    
    if (attached) {
        /* Update MAC in case the upper layers changed it. */
        IEEE80211_ADDR_COPY(sc->sc_ic.ic_myaddr,
                            ((struct arpcom *)ifp)->ac_enaddr);
        return 0;
    }
    
    err = iwx_start_hw(sc);
    if (err) {
        XYLog("%s: could not initialize hardware\n", DEVNAME(sc));
        return err;
    }
    
    err = iwx_run_init_mvm_ucode(sc, 1);
    iwx_stop_device(sc);
    if (err)
        return err;
    
    /* Print version info and MAC address on first successful fw load. */
    attached = 1;
    XYLog("%s: hw rev 0x%x, fw ver %s, address %s\n",
          DEVNAME(sc), sc->sc_hw_rev & IWX_CSR_HW_REV_TYPE_MSK,
          sc->sc_fwver, ether_sprintf(sc->sc_nvm.hw_addr));
    
    if (sc->sc_nvm.sku_cap_11n_enable)
        iwx_setup_ht_rates(sc);
    
    if (sc->sc_nvm.sku_cap_11ac_enable)
        iwx_setup_vht_rates(sc);
    
    if (sc->sc_nvm.sku_cap_11ax_enable)
        iwx_setup_he_rates(sc);
    
    /* not all hardware can do 5GHz band */
    if (!sc->sc_nvm.sku_cap_band_52GHz_enable)
        memset(&ic->ic_sup_rates[IEEE80211_MODE_11A], 0,
               sizeof(ic->ic_sup_rates[IEEE80211_MODE_11A]));
    
    /* Configure channel information obtained from firmware. */
    ieee80211_channel_init(ifp);
    
    /* Configure MAC address. */
    err = if_setlladdr(ifp, ic->ic_myaddr);
    if (err)
        XYLog("%s: could not set MAC address (error %d)\n",
                DEVNAME(sc), err);
    
    ieee80211_media_init(ifp);
    
    return 0;
}

void ItlIwx::
iwx_attach_hook(struct device *self)
{
    struct iwx_softc *sc = (struct iwx_softc *)self;
    
    iwx_preinit(sc);
}

/* ==== END TEMPORARY PROBE ==== */

bool ItlIwx::
intrFilter(OSObject *object, IOFilterInterruptEventSource *src)
{
    ItlIwx *that = (ItlIwx*)object;
    iwxabS204Filter();
    /* ==== TEMPORARY PROBE (uncommitted, round 1) ==== */
    {
        uint32_t n = ++IWX_PROBE_INTR_COUNT;
        if (n <= 12 || (n % 200) == 0)
            XYLog("PROBE intrFilter entry n=%u CSR_INT=0x%08x CSR_INT_MASK=0x%08x MSIX_HW_CAUSES=0x%08x MSIX_FH_CAUSES=0x%08x\n",
                  n, IWX_READ(&that->com, IWX_CSR_INT),
                  IWX_READ(&that->com, IWX_CSR_INT_MASK),
                  IWX_READ(&that->com, IWX_CSR_MSIX_HW_INT_CAUSES_AD),
                  IWX_READ(&that->com, IWX_CSR_MSIX_FH_INT_CAUSES_AD));
    }
    /* ==== END TEMPORARY PROBE ==== */
    IWX_WRITE(&that->com, IWX_CSR_INT_MASK, 0);
    return true;
}

bool ItlIwx::
iwx_attach(struct iwx_softc *sc, struct pci_attach_args *pa)
{
    /* DIAGNOSTIC (non-fatal): setProperty on the provider. Safe here because
     * probe() returned this, so the service persists and the property survives.
     * MUST be removed before release. */
    pcireg_t reg, memtype;
    struct ieee80211com *ic = &sc->sc_ic;
    struct _ifnet *ifp = &ic->ic_if;
    int err;
    int txq_i, i, j;
    
    sc->sc_pct = pa->pa_pc;
    sc->sc_pcitag = pa->pa_tag;
    sc->sc_dmat = pa->pa_dmat;
    /* S162: the reset-handshake state has a NONZERO meaning (REQUESTED) and the driver does not
     * memset the softc, so its initial value is SET here rather than assumed to be zero.  This is
     * the earliest point in attach, and it is before the interrupt source is created (the first
     * thing that can read the field), so no reader can observe it uninitialised. */
    sc->sc_fw_reset_state = IWX_FW_RESET_IDLE;
    sc->sc_fw_reset_wait = 0;
    
    //    rw_init(&sc->ioctl_rwl, "iwxioctl");
    
    err = pci_get_capability(sc->sc_pct, sc->sc_pcitag,
                             PCI_CAP_PCIEXPRESS, &sc->sc_cap_off, NULL);
    if (err == 0) {
        XYLog("%s: PCIe capability structure not found!\n",
              DEVNAME(sc));
        return false;
    }
    
    /* Clear device-specific "PCI retry timeout" register (41h). */
    reg = pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0x40);
    pci_conf_write(sc->sc_pct, sc->sc_pcitag, 0x40, reg & ~0xff00);

    /* Enable bus-mastering and hardware bug workaround. */
    reg = pci_conf_read(sc->sc_pct, sc->sc_pcitag, PCI_COMMAND_STATUS_REG);
    reg |= PCI_COMMAND_MASTER_ENABLE;
    /* if !MSI */
    if (reg & PCI_COMMAND_INTERRUPT_DISABLE) {
        reg &= ~PCI_COMMAND_INTERRUPT_DISABLE;
    }
    pci_conf_write(sc->sc_pct, sc->sc_pcitag, PCI_COMMAND_STATUS_REG, reg);
    
    memtype = pci_mapreg_type(pa->pa_pc, pa->pa_tag, PCI_MAPREG_START);
    err = pci_mapreg_map(pa, PCI_MAPREG_START, memtype, 0,
                         &sc->sc_st, &sc->sc_sh, NULL, &sc->sc_sz, 0);
    if (err) {
        XYLog("%s: can't map mem space\n", DEVNAME(sc));
        return false;
    }
    /*
     * Prefer MSI-X.  This device resets with the whole MSI-X cause mask set
     * (FH 0xffffffff / HW 0x3d0000ff) and Linux drives Bz exclusively through
     * MSI-X: iwl_pcie_init_msix() -> iwl_pcie_conf_msix_hw() programs the
     * IVARs and enables REG_ALIVE.  The port previously hard-wired
     * sc_msix = 0 and left that path dead, so nothing ever unmasked a cause
     * and no interrupt was ever delivered (intrFilter entries stayed 0).
     * Fall back to plain MSI if no MSI-X vector can be established.
     */
    sc->sc_msix = 0;
    int msiIntrIndex = -1;
    int have_msix = 0, msix_index = -1, msi_index = -1;
    {
        for (int index = 0; index < 32; index++) {
            int interruptType = 0;
            if (pa->pa_tag->getInterruptType(index, &interruptType)
                != kIOReturnSuccess)
                break;
            XYLog("%s: interrupt index %d type 0x%x\n",
                  DEVNAME(sc), index, interruptType);
            if ((interruptType & kIOInterruptTypePCIMessaged) == 0)
                continue;
            /*
             * IOPCIFamilyDefinitions.h defines kIOInterruptTypePCIMessagedX
             * (0x00020000) but the CLT SDK's kext-visible copy does not
             * export it, so use the literal with the same value.
             */
            if (interruptType & 0x00020000) {   /* kIOInterruptTypePCIMessagedX */
                have_msix = 1;
                if (msix_index < 0)
                    msix_index = index;
            } else if (msi_index < 0) {
                msi_index = index;
            }
        }
        XYLog("%s: interrupt setup: msix_index=%d msi_index=%d\n",
              DEVNAME(sc), msix_index, msi_index);
    }
    if (have_msix) {
        sc->sc_msix = 1;
        msiIntrIndex = msix_index;
    } else if (msi_index >= 0) {
        msiIntrIndex = msi_index;
    }
    
    /*
     * ==== TEMPORARY PROBE (uncommitted, round 1) TRACK C ==================
     * Linux provably uses MSI-X on this device in this VM (stage 1: TWO live
     * vectors, irq/24 + irq/26; pci_enable_msix_range needs >= 2, a single
     * MSI vector cannot produce two).  So the hypervisor provides MSI-X and
     * sc_msix=0 may be the defect.  Before believing any result, capture the
     * three things that distinguish the failure modes:
     *   (a) is the MSI-X capability actually ENABLED in PCI config space?
     *   (b) what does macOS's IOPCIDevice expose (already logged above)?
     *   (c) which vector numbers does the port program into the IVARs?
     * A mismatch between (c) and what macOS allocated is the expected failure
     * mode and MUST NOT be read as "MSI-X does not work here".
     */
    {
        /* Walk the PCI capability list for MSI-X (ID 0x11) and MSI (ID 0x05). */
        int cap = pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0x34) & 0xfc;
        int guard = 0, msix_cap = -1, msi_cap = -1;
        while (cap != 0 && guard++ < 48) {
            uint32_t hdr = pci_conf_read(sc->sc_pct, sc->sc_pcitag, cap);
            uint8_t id = hdr & 0xff;
            if (id == 0x11)
                msix_cap = cap;
            else if (id == 0x05)
                msi_cap = cap;
            cap = (hdr >> 8) & 0xfc;
        }
        if (msix_cap >= 0) {
            uint32_t mc = pci_conf_read(sc->sc_pct, sc->sc_pcitag, msix_cap);
            uint32_t tbl = pci_conf_read(sc->sc_pct, sc->sc_pcitag, msix_cap + 4);
            uint32_t pba = pci_conf_read(sc->sc_pct, sc->sc_pcitag, msix_cap + 8);
            XYLog("PROBE msix KEY30 MSIX_CAP@0x%02x msgctrl=0x%04x (ENABLE=%d FN_MASK=%d TSIZE=%d) "
                  "table_off=0x%08x pba_off=0x%08x msi_cap=%d\n",
                  msix_cap, mc & 0xffff, !!(mc & 0x8000), !!(mc & 0x4000),
                  ((mc >> 16) & 0x7ff) + 1, tbl & 0xfffffff8, pba & 0xfffffff8, msi_cap);
            XYLog("PROBE msix KEY30 IVAR RX0=0x%08x RX1=0x%08x ALIVE_IVAR=0x%08x\n",
                  IWX_READ(sc, IWX_CSR_MSIX_RX_IVAR(0)),
                  IWX_READ(sc, IWX_CSR_MSIX_RX_IVAR(1)),
                  IWX_READ(sc, IWX_CSR_MSIX_IVAR(IWX_MSIX_IVAR_CAUSE_REG_ALIVE)));
        } else {
            XYLog("PROBE msix KEY30 NO MSI-X CAPABILITY in config space (msi_cap=%d)\n", msi_cap);
        }
        XYLog("PROBE msix KEY30 decision: have_msix=%d sc_msix=%d chosen_index=%d\n",
              have_msix, sc->sc_msix, msiIntrIndex);
    }
    /* ==== END TEMPORARY PROBE ==== */
    /*
     * Populate sc->ih as the original code did, but do NOT fail attach if it
     * does not map.  The driver's real interrupt source is sc->sc_ih (the
     * IOFilterInterruptEventSource created below); sc->ih is a legacy cookie
     * that costs nothing to keep populated and is exactly the kind of unset
     * field that bites later in an unrelated path.
     */
    if (pci_intr_map_msi(pa, &sc->ih)) {
        XYLog("%s: pci_intr_map_msi did not map (sc->ih left NULL); continuing, "
              "sc->sc_ih is what is used\n", DEVNAME(sc));
        sc->ih = NULL;
    }
    if (msiIntrIndex < 0) {
        XYLog("%s: can't find MSI interrupt controller\n", DEVNAME(sc));
        return false;
    }

    /*
     * ==== FIX (round S38, one variable): DISPATCH BY THE PLANE THE DEVICE
     * SIGNALS ON, NOT BY WHAT macOS ENUMERATED ================================
     * Measured on boot S37a: `msix KEY30 decision: have_msix=0 sc_msix=0
     * chosen_index=1` -- macOS allocated a plain MSI vector, so the legacy
     * action was bound.  But the DEVICE is in MSI-X mode: this part's interrupt
     * generator is MSI-X-only (S7b: CHICK BIT(24) MSI_ENABLE does not latch,
     * BIT(25) MSIX_ENABLE does) and the port enables MSI-X itself, reusing the
     * vector macOS programmed.  The legacy action reads CSR_INT /
     * CSR_FH_INT_STATUS, which on this part never have bits, and exits on
     * `r1 == 0 && r2 == 0` BEFORE the Q0/Q1 notification dispatch and before
     * the ALIVE branch.  S37 measured the consequence exactly: three interrupts
     * delivered, every action entry probe all-zero, no ALIVE branch, RB_STTS
     * frozen, uc_ok = 0.
     * The correct dispatch (iwx_intr_msix) exists and is complete; it reads and
     * acks the MSI-X cause plane.  The predicate was simply asking the wrong
     * question -- vector allocation instead of device signalling.
     */
    /*
     * ==== FIX (round S41): SELECT THE ACTION ON AN INPUT THAT EXISTS AT THIS
     * INSTANT -- THE PCI DEVICE ID ==========================================
     * The two earlier attempts at this condition were SILENT NO-OPS: the action
     * is bound here, but both values that identify the part are assigned LATER
     * in this same function -- sc->sc_cfg at :15128 (`Found device: ...` is
     * logged at +.220 s) and sc->sc_device_family at :15181.  Boot S38a
     * (`sc->sc_msix || sc->sc_device_family >= BZ`) and boot S39a
     * (`sc->sc_cfg->device_family >= BZ` with a NULL guard) therefore both
     * bound the legacy action: both logs show `PROBE iwx_intr entry` and no
     * `iwx_intr_msix` line.
     * The PCI device id is known at probe time and needs no hoisting.  0x7740 is
     * the BE201 -- the Bz part whose interrupt generator is MSI-X-only (S7b:
     * CHICK BIT(24) MSI_ENABLE does not latch, BIT(25) MSIX_ENABLE does) and it
     * is the id that selects iwl_bz_trans_cfg in iwx_devices (:13682).
     * WHY THIS IS NOW REQUIRED RATHER THAN MERELY CORRECT: boot S40a programmed
     * the IVAR table (S40, BIT(7) NON_AUTO_CLEAR) and the causes became visible
     * -- the ALIVE cause latched as CSR_INT/MSIX_HW_CAUSES = 0x1 at ~+262 ms and
     * the legacy ALIVE branch ran for the first time (`alive_legacy RAN`,
     * `HBUS_TARG_WRPTR=0x02000008`, RB_STTS 0 -> 3).  But the RX/notification
     * cause is the FH one, and the legacy action dispatches RX on the LEGACY
     * CSR_INT bits, which this part does not set for FH causes -- so the FH
     * cause was never acked and the device re-signalled it forever:
     * `intrFilter=839411` interrupts in one boot, `MSIX_FH_CAUSES=0x00000001`
     * still latched in the final blob.  iwx_intr_msix reads and acks that plane
     * (CSR_MSIX_FH_INT_CAUSES_AD / CSR_MSIX_HW_INT_CAUSES_AD, exactly as Linux
     * does at pcie/gen1_2/rx.c:2289-2294) and dispatches Q0/Q1 to
     * iwx_notif_intr(), which is what consumes the ALIVE notification the
     * firmware deposited in the ring.
     * iwx_intr is KEPT for the genuine legacy/MSI parts -- it is the else
     * branch, untouched.
     */
    {
        uint16_t intr_devid = sc->sc_pcitag->configRead16(kIOPCIConfigDeviceID);
        bool msix_plane = (sc->sc_msix != 0) || (intr_devid == 0x7740);
        
        XYLog("PROBE S41 dispatch_select RAN: devid=0x%04x sc_msix=%d msix_plane=%d action=%s\n",
              intr_devid, sc->sc_msix, (int)msix_plane,
              msix_plane ? "iwx_intr_msix" : "iwx_intr");
        
        if (msix_plane)
            sc->sc_ih =
            IOFilterInterruptEventSource::filterInterruptEventSource(this,
                                                                     (IOInterruptEventSource::Action)&ItlIwx::iwx_intr_msix,
                                                                     &ItlIwx::intrFilter
                                                                     ,pa->pa_tag, msiIntrIndex);
        else
            sc->sc_ih = IOFilterInterruptEventSource::filterInterruptEventSource(this,
                                                                                 (IOInterruptEventSource::Action)&ItlIwx::iwx_intr, &ItlIwx::intrFilter
                                                                                 ,pa->pa_tag, msiIntrIndex);
    }
    if (sc->sc_ih == NULL || pa->workloop->addEventSource(sc->sc_ih) != kIOReturnSuccess) {
        XYLog("%s: can't establish interrupt\n", DEVNAME(sc));
        return false;
    }
    sc->sc_ih->enable();

    /* ==== S103az: THE SAMPLER TIMER -- created HERE, on the HAL's own workloop, after the
     * interrupt source exists.  It is re-armed by its own callback and gated on NOTHING (see
     * `iwxabS103azTimerCB`'s banner).  Failure to create it is reported by `iwxctl_status_alive`'s
     * absence and by `tmr` staying 0 -- it is never silently assumed to be running. */
    if (iwxab_s103az_timer == NULL) {
        iwxab_s103az_timer = IOTimerEventSource::timerEventSource(
            (OSObject *)this, (IOTimerEventSource::Action)&iwxabS103azTimerCB);
        if (iwxab_s103az_timer != NULL) {
            if (pa->workloop->addEventSource(iwxab_s103az_timer) == kIOReturnSuccess)
                iwxab_s103az_timer->setTimeoutMS(IWXAB_S103AZ_PERIOD_MS);
        }
        /* S103bd: the census publisher's target.  NOT `(OSObject *)this` and not NULL -- see the
         * banner on `iwxab_s103bd_sc` for the measured reason the existing sampler publishes
         * nothing.  Set here because `sc` is this function's argument and the timer is created
         * here, so the pointer cannot be stale or uninitialised. */
        iwxab_s103bd_sc = sc;
    }

    /* ==== S202: THE KICK EVENT SOURCE ====================================================
     * Providerless by design (IOInterruptEventSource.h: "When no provider is defined the event
     * source assumes that the client will in some manner call the interruptOccured method
     * explicitly").  iwx_start() calls interruptOccurred() ONLY when the in-action witness says
     * the start action did not run; the workloop then calls iwxabS202KickCB under the gate.
     * Created here, on the same workloop as the interrupt and the sampler timer, and removed in
     * releaseAll() with iwxabS202Teardown().  addEventSource failure is counted (kick_ok=0). */
    if (iwxab_s202_kick == NULL) {
        iwxab_s202_kick = IOInterruptEventSource::interruptEventSource(
            (OSObject *)this, (IOInterruptEventSource::Action)&iwxabS202KickCB);
        if (iwxab_s202_kick != NULL) {
            if (pa->workloop->addEventSource(iwxab_s202_kick) == kIOReturnSuccess)
                iwxab_s202_kick_ok = 1u;
            else {
                iwxab_s202_kick->release();
                iwxab_s202_kick = NULL;
            }
        }
    }

    
    /* ==== TEMPORARY PROBE (uncommitted, round S7) MSI before/after reset ====
     * Sample point 0: the earliest instant the interrupt source exists, i.e.
     * straight after IOPCIFamily registered and enabled the MSI vector and
     * before any device touch of ours.  QEMU emulates the whole MSI/MSI-X
     * capability for a vfio device (hw/vfio/pci.c: "QEMU emulates all of MSI
     * & MSIX", vfio_pci_interrupt_setup()), so these reads show QEMU's
     * emulated config, not the hardware -- the hardware state is sampled
     * host-side by 07-scripts/msi-watch.py.  This series answers a narrower,
     * still-useful question: does *anything the port does* rewrite the MSI
     * registers macOS set up?
     */
    XYLog("PROBE msirw KEY33 ATTACH_AFTER_ENABLE: CMD=0x%08x MSI=0x%08x LO=0x%08x HI=0x%08x DATA=0x%08x MSIX=0x%08x\n",
          pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0x04),
          pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0xD0),
          pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0xD4),
          pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0xD8),
          pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0xDC),
          pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0x80));
    /* ==== END TEMPORARY PROBE ==== */
    
    /* ==== TEMPORARY PROBE (uncommitted, round S7b) MSI-X FALLBACK ========
     * Round S7 measured, on the host, that the device emits NOTHING while the
     * PCI function is in plain-MSI mode (physical MSI Enable=1 with a valid
     * interrupt-remapped target and host vector 165 allocated; device asserted
     * MSIX_HW_CAUSES=0x22 with SW_ERR_BZ unmasked; host IRQ count stayed 0).
     * Linux never runs this part in MSI mode: it takes pci_enable_msix_range()
     * (MSIX_MIN_INTERRUPT_VECTORS = 2, pcie/trans.c:1672) and falls back to
     * pci_enable_msi() only if that fails.  So MSI-X is the untested path.
     *
     * This needs NO new vector from macOS: the guest MSI target that
     * IOPCIFamily already programmed (Message Address/Data in the MSI
     * capability) is a valid guest vector, and the MSI-X table simply reuses
     * it.  QEMU emulates both the MSI-X capability and the MSI-X table for a
     * vfio device (hw/vfio/pci.c: "QEMU emulates all of MSI & MSIX" plus the
     * emulated table region), so:
     *   - writing the table here is seen by QEMU's MSI-X core;
     *   - setting MSI-X Enable makes QEMU call vfio_msix_enable(), which
     *     allocates real host MSI-X vectors and programs the PHYSICAL table
     *     with interrupt-remapped addresses;
     *   - unmasking a vector makes QEMU's vector-use notifier set the KVM
     *     route to the guest vector taken from this table entry.
     *
     * ORDER IS LOAD-BEARING and was verified in QEMU's source:
     * msix_set_vector_notifiers() only fires the per-vector use callback for
     * vectors that are already UNMASKED at the moment Enable is set
     * (hw/pci/msix.c: msix_set_notifier_for_vector), and vfio_msix_enable()
     * falls back to vfio_enable_msix_no_vec() - i.e. MSI-X enabled with no
     * vectors at all - when every vector is still masked.  So: programme the
     * entries first, clear their mask bits, then set Enable last.  Step 4
     * repeats the programming after Enable and forces a mask transition, so
     * the notifier also fires if the pre-Enable table write happened to land
     * on the physical table instead of QEMU's emulation.
     */
    {
        const uint32_t msix_cap = 0x80;   /* measured in iwx_attach KEY30 */
        uint32_t msix_mc = pci_conf_read(sc->sc_pct, sc->sc_pcitag, msix_cap);
        uint32_t tgt_lo   = pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0xD4);
        uint32_t tgt_hi   = pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0xD8);
        uint32_t tgt_data = pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0xDC) & 0xffff;
        uint32_t mc16;
        int e;
        /* ==== round S7c DISCRIMINATOR ====
         * S7b delivered exactly one interrupt while the four host MSI-X IRQ
         * counters stayed 0 and the action read every cause register as 0.
         * That is either (i) a real device MSI-X message delivered via VT-d
         * posted interrupts (no host IRQ taken), or (ii) a spurious
         * vector-0x73 delivery from QEMU's MSI-X emulation during the
         * MSI->MSI-X transition.  Every cause is routed to MSI-X table
         * index 0 (IVARs zeroed below), so leaving ONLY entry 0 masked
         * isolates exactly that path while keeping entries 1..3 unmasked,
         * which keeps QEMU's vector allocation and the MSI->MSI-X transition
         * byte-identical to S7b.  ONE variable changed.
         *   1 = entry 0 MASKED  -> if an interrupt still arrives it is spurious
         *   0 = entry 0 unmasked -> S7b behaviour
         */
        uint32_t e0_ctrl = 0;
        
        XYLog("PROBE msixfb KEY40 target from MSI cap: LO=0x%08x HI=0x%08x DATA=0x%04x MSIX_MC_before=0x%04x\n",
              tgt_lo, tgt_hi, tgt_data, (msix_mc >> 16) & 0xffff);
        
        /* 1. Table entries 0..3, 16 bytes each at BAR0+0x2000.
         *    Vector Control bit 0 = MASK, so 0 = unmasked. */
        for (e = 0; e < 4; e++) {
            uint32_t b = 0x2000 + 16 * e;
            IWX_WRITE(sc, b + 0, tgt_lo);
            IWX_WRITE(sc, b + 4, tgt_hi);
            IWX_WRITE(sc, b + 8, tgt_data);
            IWX_WRITE(sc, b + 12, (e == 0) ? e0_ctrl : 0);
        }
        
        /* 2. Route EVERY cause at MSI-X table index 0.  The IVAR byte's low
         *    nibble is the bound vector index.  RX IVARs are at
         *    0x2880 + cause; non-RX (HW/FH) IVARs at 0x2890 + (bit +/- 16),
         *    so HW cause bit n lives at 0x28A0 + n (e.g. ALIVE bit 0 at
         *    0x28A0, SW_ERR_BZ bit 5 at 0x28A5, HW_ERR bit 29 at 0x28BD).
         *    Measured defaults were RX0=0, ALIVE=0 but RX1=0xffffffff, so
         *    zero the whole window rather than trusting the defaults.
         *    32-bit aligned writes of 0 only ever set neighbours to the same
         *    value we want for them. */
        for (e = 0; e < 4; e++)
            IWX_WRITE(sc, 0x2880 + 4 * e, 0);      /* RX IVARs 0..15   */
        for (e = 0; e < 8; e++)
            IWX_WRITE(sc, 0x28A0 + 4 * e, 0);      /* HW causes 0..31  */
        
        /* 3. Enable MSI-X, Function Mask clear. */
        mc16 = (msix_mc >> 16) & 0xffff;
        mc16 &= ~0x4000;
        mc16 |= 0x8000;
        pci_conf_write(sc->sc_pct, sc->sc_pcitag, msix_cap,
                       (msix_mc & 0xffff) | (mc16 << 16));
        XYLog("PROBE msixfb KEY40 MSIX_MC_after=0x%04x\n",
              (pci_conf_read(sc->sc_pct, sc->sc_pcitag, msix_cap) >> 16) & 0xffff);
        
        /* 4. Re-programme and force a mask transition per entry. */
        for (e = 0; e < 4; e++) {
            uint32_t b = 0x2000 + 16 * e;
            IWX_WRITE(sc, b + 0, tgt_lo);
            IWX_WRITE(sc, b + 4, tgt_hi);
            IWX_WRITE(sc, b + 8, tgt_data);
            IWX_WRITE(sc, b + 12, 1);
            IWX_WRITE(sc, b + 12, (e == 0) ? e0_ctrl : 0);
        }
        XYLog("PROBE msixfb KEY40 e0_ctrl=%u (1 = entry0 MASKED, S7c discriminator)\n",
              e0_ctrl);
        for (e = 0; e < 4; e++) {
            uint32_t b = 0x2000 + 16 * e;
            XYLog("PROBE msixfb KEY40 tbl[%d]: lo=0x%08x hi=0x%08x data=0x%08x ctrl=0x%08x\n",
                  e, IWX_READ(sc, b), IWX_READ(sc, b + 4),
                  IWX_READ(sc, b + 8), IWX_READ(sc, b + 12));
        }
        XYLog("PROBE msixfb KEY40 IVAR RX0=0x%08x RX1=0x%08x ALIVE=0x%08x SWERRBZ=0x%02x HWERR=0x%02x\n",
              IWX_READ(sc, IWX_CSR_MSIX_RX_IVAR(0)),
              IWX_READ(sc, IWX_CSR_MSIX_RX_IVAR(1)),
              IWX_READ(sc, IWX_CSR_MSIX_IVAR(IWX_MSIX_IVAR_CAUSE_REG_ALIVE)),
              (IWX_READ(sc, 0x28A4) >> 8) & 0xff,
              (IWX_READ(sc, 0x28BC) >> 8) & 0xff);
    }
    /* ==== END TEMPORARY PROBE ==== */
    
    /* Clear pending interrupts. */
    IWX_WRITE(sc, IWX_CSR_INT_MASK, 0);
    IWX_WRITE(sc, IWX_CSR_INT, ~0);
    IWX_WRITE(sc, IWX_CSR_FH_INT_STATUS, ~0);
    
    sc->sc_hw_rev = IWX_READ(sc, IWX_CSR_HW_REV);
    /*
     * In the 8000 HW family the format of the 4 bytes of CSR_HW_REV have
     * changed, and now the revision step also includes bit 0-1 (no more
     * "dash" value). To keep hw_rev backwards compatible - we'll store it
     * in the old format.
     */
    sc->sc_hw_rev = (sc->sc_hw_rev & 0xfff0) |
    (IWX_CSR_HW_REV_STEP(sc->sc_hw_rev << 2) << 2);
    sc->sc_hw_rf_id = IWX_READ(sc, IWX_CSR_HW_RF_ID);
    uint16_t device = sc->sc_pcitag->configRead16(kIOPCIConfigDeviceID);
    uint16_t subsystem_device = sc->sc_pcitag->configRead16(kIOPCIConfigSubSystemID);
    uint16_t subsystem_vendor = sc->sc_pcitag->configRead16(kIOPCIConfigSubSystemVendorID);
    sc->sc_hw_id = (device << 16) + subsystem_device;
    pci_match(PCI_VENDOR_INTEL, device, subsystem_vendor, subsystem_device, iwx_devices,
              nitems(iwx_devices), (void **)&com.sc_cfg_params);
    if (!com.sc_cfg_params) {
        XYLog("%s: Why??? unknown adapter type\n", DEVNAME(sc));
        return false;
    }
    for (i = 0; i < ARRAY_SIZE(iwl_dev_info_table); i++) {
        const struct iwl_dev_info *dev_info = &iwl_dev_info_table[i];
        if ((dev_info->device == (u16)IWL_CFG_ANY ||
             dev_info->device == device) &&
            (dev_info->subdevice == (u16)IWL_CFG_ANY ||
             dev_info->subdevice == subsystem_device) &&
            (dev_info->mac_type == (u16)IWL_CFG_ANY ||
             dev_info->mac_type ==
             CSR_HW_REV_TYPE(sc->sc_hw_rev)) &&
            (dev_info->mac_step == (u8)IWL_CFG_ANY ||
             dev_info->mac_step ==
             IWX_CSR_HW_REV_STEP(sc->sc_hw_rev)) &&
            (dev_info->rf_type == (u16)IWL_CFG_ANY ||
             dev_info->rf_type ==
             CSR_HW_RFID_TYPE(sc->sc_hw_rf_id)) &&
            (dev_info->cdb == IWL_CFG_NO_CDB ||
             CSR_HW_RFID_IS_CDB(sc->sc_hw_rf_id)) &&
            (dev_info->rf_id == (u8)IWL_CFG_ANY ||
             dev_info->rf_id ==
             IWL_SUBDEVICE_RF_ID(subsystem_device)) &&
            (dev_info->no_160 == (u8)IWL_CFG_ANY ||
             dev_info->no_160 ==
             IWL_SUBDEVICE_NO_160(subsystem_device)) &&
            (dev_info->cores == (u8)IWL_CFG_ANY ||
             dev_info->cores ==
             IWL_SUBDEVICE_CORES(subsystem_device))) {
            sc->sc_cfg = dev_info->cfg;
            if (dev_info->name)
                XYLog("Found device: %s fw: %s index: %d:%zu\n", dev_info->name, dev_info->cfg->fwname, i, ARRAY_SIZE(iwl_dev_info_table));
            else if (dev_info->cfg->name)
                XYLog("Found device cfg: %s fw: %s index: %d:%zu\n", dev_info->cfg->name, dev_info->cfg->fwname, i, ARRAY_SIZE(iwl_dev_info_table));
            else
                XYLog("Found device: No Name fw: %s index: %d:%zu\n", dev_info->cfg->fwname, i, ARRAY_SIZE(iwl_dev_info_table));
        }
    }
    /*
     * Workaround for problematic SnJ device: sometimes when
     * certain RF modules are connected to SnJ, the device ID
     * changes to QnJ's ID.  So we are using QnJ's trans_cfg until
     * here.  But if we detect that the MAC type is actually SnJ,
     * we should switch to it here to avoid problems later.
     */
    if (CSR_HW_REV_TYPE(sc->sc_hw_rev) == IWL_CFG_MAC_TYPE_SNJ)
        sc->sc_cfg_params = &iwl_so_trans_cfg;
    
    /*
     * This is a hack to switch from Qu B0 to Qu C0.  We need to
     * do this for all cfgs that use Qu B0, except for those using
     * Jf, which have already been moved to the new table.  The
     * rest must be removed once we convert Qu with Hr as well.
     */
    if (sc->sc_hw_rev == CSR_HW_REV_TYPE_QU_C0) {
        if (sc->sc_cfg == &iwl_ax201_cfg_qu_hr)
            sc->sc_cfg = &iwl_ax201_cfg_qu_c0_hr_b0;
        else if (sc->sc_cfg == &killer1650s_2ax_cfg_qu_b0_hr_b0)
            sc->sc_cfg = &killer1650s_2ax_cfg_qu_c0_hr_b0;
        else if (sc->sc_cfg == &killer1650i_2ax_cfg_qu_b0_hr_b0)
            sc->sc_cfg = &killer1650i_2ax_cfg_qu_c0_hr_b0;
    }

    /* same thing for QuZ... */
    if (sc->sc_hw_rev == CSR_HW_REV_TYPE_QUZ) {
        if (sc->sc_cfg == &iwl_ax201_cfg_qu_hr)
            sc->sc_cfg = &iwl_ax201_cfg_quz_hr;
        else if (sc->sc_cfg == &killer1650s_2ax_cfg_qu_b0_hr_b0)
            sc->sc_cfg = &iwl_ax1650s_cfg_quz_hr;
        else if (sc->sc_cfg == &killer1650i_2ax_cfg_qu_b0_hr_b0)
            sc->sc_cfg = &iwl_ax1650i_cfg_quz_hr;
    }
    if (sc->sc_cfg == NULL) {
        XYLog("No config found for PCI dev %04x/%04x, rev=0x%x, rfid=0x%x\n",
              device, subsystem_device,
              sc->sc_hw_rev, sc->sc_hw_rf_id);
        return false;
    }
    XYLog("Found PCI dev %04x/%04x, rev=0x%x, rfid=0x%x fw: %s\n",
          device, subsystem_device,
          sc->sc_hw_rev, sc->sc_hw_rf_id, sc->sc_cfg->fwname);
    sc->sc_fwname = sc->sc_cfg->fwname;
    sc->sc_device_family = sc->sc_cfg->device_family;
    sc->sc_integrated = sc->sc_cfg_params->integrated;
    sc->sc_ltr_delay = sc->sc_cfg_params->ltr_delay;
    sc->sc_low_latency_xtal = sc->sc_cfg_params->low_latency_xtal;
    sc->sc_xtal_latency = sc->sc_cfg_params->xtal_latency;
    sc->sc_tx_with_siso_diversity = sc->sc_cfg->tx_with_siso_diversity;
    sc->sc_uhb_supported = sc->sc_cfg->uhb_supported;
    
    /* Allocate DMA memory for loading firmware. */
    if (sc->sc_device_family >= IWX_DEVICE_FAMILY_AX210)
        err = iwx_dma_contig_alloc(sc->sc_dmat, &sc->ctxt_info_dma,
                                   sizeof(struct iwx_context_info_gen3), 0);
    else
        err = iwx_dma_contig_alloc(sc->sc_dmat, &sc->ctxt_info_dma,
                                   sizeof(struct iwx_context_info), 0);
    if (err) {
        XYLog("%s: could not allocate memory for loading firmware\n",
              DEVNAME(sc));
        return false;
    }
    
    /* Allocate interrupt cause table (ICT).*/
    err = iwx_dma_contig_alloc(sc->sc_dmat, &sc->ict_dma,
                               IWX_ICT_SIZE, 1<<IWX_ICT_PADDR_SHIFT);
    if (err) {
        XYLog("%s: could not allocate ICT table\n", DEVNAME(sc));
        goto fail0;
    }
    
    for (txq_i = 0; txq_i < nitems(sc->txq); txq_i++) {
        err = iwx_alloc_tx_ring(sc, &sc->txq[txq_i], txq_i);
        if (err) {
            XYLog("%s: could not allocate TX ring %d\n",
                  DEVNAME(sc), txq_i);
            goto fail4;
        }
    }
    
    err = iwx_alloc_rx_ring(sc, &sc->rxq);
    if (err) {
        XYLog("%s: could not allocate RX ring\n", DEVNAME(sc));
        goto fail4;
    }
    
    taskq_init();
    sc->sc_nswq = taskq_create("iwxns", 1, IPL_NET, 0);
    if (sc->sc_nswq == NULL)
        goto fail4;
    
    ic->ic_phytype = IEEE80211_T_OFDM;    /* not only, but not used */
    ic->ic_opmode = IEEE80211_M_STA;    /* default to BSS mode */
    ic->ic_state = IEEE80211_S_INIT;
    
    /* Set device capabilities. */
    ic->ic_caps =
    IEEE80211_C_WEP |        /* WEP */
    IEEE80211_C_RSN |        /* WPA/RSN */
    IEEE80211_C_SCANALL |    /* device scans all channels at once */
    IEEE80211_C_SCANALLBAND |    /* device scans all bands at once */
    IEEE80211_C_MONITOR |    /* monitor mode supported */
    IEEE80211_C_SHSLOT |    /* short slot time supported */
    IEEE80211_C_SHPREAMBLE;    /* short preamble supported */
    
    ic->ic_htcaps = IEEE80211_HTCAP_SGI20;
    ic->ic_htcaps |=
    (IEEE80211_HTCAP_SMPS_DIS << IEEE80211_HTCAP_SMPS_SHIFT);
    ic->ic_htcaps |= (IEEE80211_HTCAP_CBW20_40 | IEEE80211_HTCAP_SGI40);
    ic->ic_htcaps |= IEEE80211_HTCAP_LDPC;  /* all of the gen2/gen3 cards support LDPC */
    ic->ic_htxcaps = 0;
    ic->ic_txbfcaps = 0;
    ic->ic_aselcaps = 0;
    ic->ic_ampdu_params = (IEEE80211_AMPDU_PARAM_SS_4 | 0x3 /* 64k */);
    ic->ic_caps |= (IEEE80211_C_QOS | IEEE80211_C_TX_AMPDU_SETUP_IN_HW | IEEE80211_C_TX_AMPDU | IEEE80211_C_AMSDU_IN_AMPDU);
    ic->ic_caps |= IEEE80211_C_SUPPORTS_VHT_EXT_NSS_BW;
    
    ic->ic_sup_rates[IEEE80211_MODE_11A] = ieee80211_std_rateset_11a;
    ic->ic_sup_rates[IEEE80211_MODE_11B] = ieee80211_std_rateset_11b;
    ic->ic_sup_rates[IEEE80211_MODE_11G] = ieee80211_std_rateset_11g;
    
    for (i = 0; i < nitems(sc->sc_phyctxt); i++) {
        sc->sc_phyctxt[i].id = i;
    }
    
    /* IBSS channel undefined for now. */
    ic->ic_ibss_chan = &ic->ic_channels[1];
    
    ic->ic_max_rssi = IWX_MAX_DBM - IWX_MIN_DBM;
    
    ifp->if_softc = sc;
    ifp->if_flags = IFF_BROADCAST | IFF_SIMPLEX | IFF_MULTICAST | IFF_DEBUG;
    ifp->if_ioctl = iwx_ioctl;
    ifp->if_start = iwx_start;
    ifp->if_watchdog = iwx_watchdog;
    memcpy(ifp->if_xname, DEVNAME(sc), IFNAMSIZ);
    
    if_attach(ifp);
    ieee80211_ifattach(ifp, getController());
    ieee80211_media_init(ifp);
    
#if NBPFILTER > 0
    iwx_radiotap_attach(sc);
#endif
    for (i = 0; i < nitems(sc->sc_rxba_data); i++) {
        struct iwx_rxba_data *rxba = &sc->sc_rxba_data[i];
        rxba->baid = IWX_RX_REORDER_DATA_INVALID_BAID;
        rxba->sc = sc;
        timeout_set(&rxba->session_timer, iwx_rx_ba_session_expired,
                    rxba);
        timeout_set(&rxba->reorder_buf.reorder_timer,
                    iwx_reorder_timer_expired, &rxba->reorder_buf);
        for (j = 0; j < nitems(rxba->entries); j++)
        ml_init(&rxba->entries[j].frames);
    }
    task_set(&sc->init_task, iwx_init_task, sc, "iwx_init_task");
    task_set(&sc->newstate_task, iwx_newstate_task, sc, "iwx_newstate_task");
    task_set(&sc->ba_task, iwx_ba_task, sc, "iwx_ba_task");
    task_set(&sc->setkey_task, iwx_setkey_task, sc, "iwx_setkey_task");
    task_set(&sc->mac_ctxt_task, iwx_mac_ctxt_task, sc, "iwx_mac_ctxt_task");
    task_set(&sc->chan_ctxt_task, iwx_chan_ctxt_task, sc, "iwx_chan_ctxt_task");
    
    ic->ic_node_alloc = iwx_node_alloc;
    ic->ic_bgscan_start = iwx_bgscan;
    ic->ic_set_key = iwx_set_key;
    ic->ic_delete_key = iwx_delete_key;
    
    /* Override 802.11 state transition machine. */
    sc->sc_newstate = ic->ic_newstate;
    ic->ic_newstate = iwx_newstate;
    ic->ic_updateprot = iwx_updateprot;
    ic->ic_updateslot = iwx_updateslot;
    ic->ic_updateedca = iwx_updateedca;
    ic->ic_updatedtim = iwx_updatedtim;
    ic->ic_ampdu_rx_start = iwx_ampdu_rx_start;
    ic->ic_ampdu_rx_stop = iwx_ampdu_rx_stop;
    ic->ic_ampdu_tx_start = iwx_ampdu_tx_start;
    ic->ic_ampdu_tx_stop = iwx_ampdu_tx_stop;
    ic->ic_update_chw = iwx_update_chw;
    /*
     * We cannot read the MAC address without loading the
     * firmware from disk. Postpone until mountroot is done.
     */
    //    config_mountroot(self, iwx_attach_hook);
    if (iwx_preinit(sc)) {
        goto fail5;
    }
    
    return true;
    
fail5:
    for (i = 0; i < nitems(sc->sc_rxba_data); i++) {
        struct iwx_rxba_data *rxba = &sc->sc_rxba_data[i];
        iwx_clear_reorder_buffer(sc, rxba);
    }
fail4:    while (--txq_i >= 0)
    iwx_free_tx_ring(sc, &sc->txq[txq_i]);
    iwx_free_rx_ring(sc, &sc->rxq);
fail3:    if (sc->ict_dma.vaddr != NULL)
    iwx_dma_contig_free(&sc->ict_dma);

fail0:    iwx_dma_contig_free(&sc->ctxt_info_dma);
    return false;
}

#if NBPFILTER > 0
void ItlIwx::
iwx_radiotap_attach(struct iwx_softc *sc)
{
    bpfattach(&sc->sc_drvbpf, &sc->sc_ic.ic_if, DLT_IEEE802_11_RADIO,
              sizeof (struct ieee80211_frame) + IEEE80211_RADIOTAP_HDRLEN);
    
    sc->sc_rxtap_len = sizeof sc->sc_rxtapu;
    sc->sc_rxtap.wr_ihdr.it_len = htole16(sc->sc_rxtap_len);
    sc->sc_rxtap.wr_ihdr.it_present = htole32(IWX_RX_RADIOTAP_PRESENT);
    
    sc->sc_txtap_len = sizeof sc->sc_txtapu;
    sc->sc_txtap.wt_ihdr.it_len = htole16(sc->sc_txtap_len);
    sc->sc_txtap.wt_ihdr.it_present = htole32(IWX_TX_RADIOTAP_PRESENT);
}
#endif

void ItlIwx::
iwx_init_task(void *arg1)
{
    XYLog("%s\n", __FUNCTION__);
    struct iwx_softc *sc = (struct iwx_softc *)arg1;
    struct _ifnet *ifp = &sc->sc_ic.ic_if;
    ItlIwx *that = container_of(sc, ItlIwx, com);
    int s = splnet();
    int generation = sc->sc_generation;
    int fatal = (sc->sc_flags & (IWX_FLAG_HW_ERR | IWX_FLAG_RFKILL));

    iwxabS217Step(sc, IWXAB_S217_TASK, 0);
    iwxabS217WindowStart(sc);
    
    //    rw_enter_write(&sc->ioctl_rwl);
    if (generation != sc->sc_generation) {
        /* ==== S103av PROBE C: THE SECOND SILENT EXIT -- AND THE ONE THAT ENDS THE RECOVERY ======
         * `iwx_init_task` returns here WITHOUT LOGGING ANYTHING when `sc_generation` moved under
         * it.  `iwx_stop()` bumps `sc_generation`, and `iwx_init()` bumps it again, so ANY
         * concurrent stop/init between this task being QUEUED and it being RUN makes it a no-op.
         * That is the mechanism by which "the driver does not re-run the 802.11 join": the task
         * that exists to do exactly that can be silently disarmed.  Printed with both generations
         * and the flags it would have decided on, so a disarmed recovery is attributable. */
        XYLog("PROBE S103av init_task EXIT=generation_lost gen=%d sc_gen=%d if_flags=0x%x "
              "ic_state=%d fatal=%d\n",
              generation, (int)sc->sc_generation, (unsigned)ifp->if_flags,
              (int)sc->sc_ic.ic_state, fatal);
        sc->sc_s195_reload = 0;   /* S195: a reload marker cannot survive its task */
        sc->sc_s199_direct = 0;   /* S199: neither can a retained-scan arm */
        //        rw_exit(&sc->ioctl_rwl);
        splx(s);
        return;
    }

    XYLog("PROBE S103av init_task ENTER gen=%d if_flags=0x%x ic_state=%d fatal=%d "
          "shutdown=%d hw_err=%d running=%d up=%d\n",
          generation, (unsigned)ifp->if_flags, (int)sc->sc_ic.ic_state, fatal,
          (sc->sc_flags & IWX_FLAG_SHUTDOWN) ? 1 : 0,
          (sc->sc_flags & IWX_FLAG_HW_ERR) ? 1 : 0,
          (ifp->if_flags & IFF_RUNNING) ? 1 : 0, (ifp->if_flags & IFF_UP) ? 1 : 0);

    if (ifp->if_flags & IFF_RUNNING)
        that->iwx_stop(ifp);   /* S195: iwx_stop() consumes sc_s195_reload here */
    else {
        sc->sc_s195_reload = 0;   /* S195: no stop, no capture */
        sc->sc_s199_direct = 0;   /* S199: no stop, no retained-scan arm */
        sc->sc_flags &= ~IWX_FLAG_HW_ERR;
    }
    
#ifdef AIRPORT_WCL
    {
        /* ==== S189 FIX 2 / S103av FIX 1 ARE DELIBERATELY NOT CARRIED ON THIS PATH ==========
         * The itlwm path below gains two things: a re-snapshot of `sc_generation` AFTER
         * `iwx_init()` returns, and a BOUNDED RE-ARM of this task when the reload did not
         * reach IFF_RUNNING.  Neither is ported here, and the reason is measured, not
         * stylistic.
         *
         * THIS BLOCK *IS* THE AIRPORT-NATIVE RECOVERY.  It captures `iwx_init()`'s return,
         * clears `ic_wcl_mac_reconfig`, drops IFF_UP and fires
         * IEEE80211_EVT_DRIVER_STOPPED so WCL re-drives the interface itself.
         *
         * AND THE RE-ARM'S GUARD WOULD BE FALSE IN EXACTLY THE CASE THE RE-ARM EXISTS FOR:
         * in the branch `error != 0 && error != ENXIO && !IFF_RUNNING`, the line above has
         * ALREADY cleared IFF_UP, so
         *     (ifp->if_flags & (IFF_UP | IFF_RUNNING)) == IFF_UP
         * is `0 == IFF_UP`, i.e. false, and the re-arm could never run.  Shipping it here
         * would be shipping code that cannot run.
         *
         * WHERE THE GUARD *COULD* BE TRUE -- `error == ENXIO`, which leaves IFF_UP set -- a
         * second re-arm would make this task a SECOND recovery driver racing WCL's re-drive.
         * That is the same "two mechanisms, one death" mistake the per-queue fuse forbids; it
         * is not made here.  WCL owns recovery on this path; the itlwm path has nobody else,
         * which is exactly why it gets the re-arm.
         * `05-artifacts/s103bn/NOT-CARRIED.md` #10 reached the same decision for this block. */
        int error = that->iwx_init(ifp);
        if (error && error != ENXIO && !(ifp->if_flags & IFF_RUNNING)) {
            sc->sc_ic.ic_wcl_mac_reconfig = false;
            ifp->if_flags &= ~IFF_UP;
            if (sc->sc_ic.ic_event_handler)
                sc->sc_ic.ic_event_handler(&sc->sc_ic, IEEE80211_EVT_DRIVER_STOPPED, NULL);
        }
    }
#else
    if (!fatal && (ifp->if_flags & (IFF_UP | IFF_RUNNING)) == IFF_UP) {
        that->iwx_init(ifp);
        /* ==== S189 FIX 2: RE-SNAPSHOT THE GENERATION AFTER `iwx_init` RETURNS (`0qw`) ===========
         * THE MEASURED DEFECT: `iwx_init()` bumps the generation ITSELF on entry --
         * `generation = ++sc->sc_generation;` (`:19615`) -- so the value captured at this task's
         * entry (`:25202`) is stale the instant the call returns.  The retry that exists to give a
         * failed reload a second chance then compared
         *     if (generation == sc->sc_generation && ...)        (`:25303`)
         * i.e. `g == g+1`: ALWAYS FALSE, always "re-arm DECLINED", budget 5 and effective attempts
         * 1.  Measured receipt (S188): `rst=3` -- one reset for the boot and two for exactly one
         * recovery -- still 3 after 671 further watchdog entries and 682 s.
         *
         * THE FIX, AND WHAT IT PRESERVES: the baseline becomes the value AFTER our own init, so the
         * guard still refuses when ANOTHER actor moved the generation while we slept (a concurrent
         * `iwx_stop`, a userspace ioctl -- `:17816`, `:19985`), and accepts when the only mover was
         * the init we just called.  The guard's own condition is UNCHANGED, and so is the entry
         * guard at `:25206`; a duplicate init_task is still refused structurally by `task_add`
         * (`_task.cpp:280`: `if (ISSET(w->t_flags, TASK_ONQUEUE)) return (0);`), which never queues
         * the same task twice.  `0ja`/`0ik`: the guard is re-asserted at the point of use and now
         * compares a pair that can actually be equal. */
        generation = sc->sc_generation;
        /* ==== S103av FIX 1: THE RELOAD MUST NOT BE ABLE TO END IN SILENCE ====================
         * THE MEASURED DEFECT (`05-artifacts/s103au/STREAM2.txt`, boot 2):
         *   05:53:11.743  iwx_init_task      (the RUN->ASSOC flush timed out at :11.734)
         *   05:53:11.771  : RUN -> INIT
         *   05:53:11.772  iwx_init / iwx_init_hw
         *   05:53:12.128  iwx_rx_pkt: firmware alive, size=152      <-- the reload DID come alive
         *   05:53:12.149  iwx_send_cmd: Sending command (02.03)     <-- then the firmware went quiet
         *                 *** 1002 ms of silence ***
         *   05:53:13.151  iwx_stop_device                            <-- iwx_init_hw() gave up
         *   ...and then ZERO state transitions for 3.5 minutes, until a MANUAL `ifconfig en1 down/up`.
         *
         * WHY IT ENDS THERE, IN ONE LINE: the body above is `if (IFF_RUNNING) iwx_stop(); if (!fatal
         * && UP) iwx_init();` and NOTHING follows it.  `iwx_init()` has ONE early return that prints
         * NOTHING -- `generation != sc->sc_generation -> return ENXIO` -- and it also returns the
         * error from `iwx_init_hw()` after `iwx_stop_device()`.  In BOTH cases this task RETURNS and
         * the task queue is empty: the firmware is loaded, `ic_state` is INIT, `IFF_RUNNING` is
         * clear, the interface is still UP, and no task will ever be queued again.  Only a userspace
         * `down`/`up` (-> `iwx_ioctl` -> `iwx_init`) can restart it.  THAT is the asymmetry the
         * brief asks for: the manual path re-enters `iwx_init` from a DIFFERENT caller; the
         * automatic path has exactly ONE attempt and no retry.
         *
         * THE FIX: make the automatic path RETRY, with a bounded budget.  This does not weaken any
         * error handling -- the failure is still detected, still logged by `iwx_init`'s own strings,
         * and still counted here.  It adds the thing the manual path has and this one lacked: a
         * second attempt.
         *
         * WHY THE RESULT IS READ THIS WAY: `iwx_init()` sets IFF_RUNNING only on its SUCCESS path
         * (ItlIwx.cpp:16406 in the uninstrumented file, immediately before `ieee80211_begin_scan`).
         * So `IFF_RUNNING == 0` after the call is the driver's own statement that the reload did not
         * complete -- a value the enclosing function already owns, not an inference from a log line.
         *
         * WHY THE DELAY IS 2 s: the two reloads that DID work in boot 2 both had a quiet link in
         * front of them; the one that wedged was started 1002 ms after the previous stop.  A 2 s
         * settle before re-arming is therefore the conservative reading of the measured difference,
         * and it is measured from OUR OWN stop (rule 0je concerns delays whose meaning is a PEER's
         * event; this one is a self-pacing delay and is declared as such).
         *
         * WHY BOUNDED: after IWX_S103AV_MAX_RELOAD_TRIES attempts the link is declared unrecoverable
         * and the driver stops re-arming -- a firmware that cannot come up after five tries will not
         * come up on the sixth, and an unbounded loop would be a worse defect than the one being
         * fixed (it would also burn the boot's CPU in a stop/init spin).  The give-up is LOGGED, so
         * "the driver stopped trying" is never silent again.
         *
         * THE COUNTER RESETS ON SUCCESS, and also whenever the interface goes down (`iwx_stop` clears
         * IFF_RUNNING), so a long-lived interface that reloads once an hour does not accumulate a
         * budget across unrelated events.  PURE BOOKKEEPING + task_add: no register, no lock, no
         * allocation, no change to the wire. */
        if ((ifp->if_flags & IFF_RUNNING) == 0) {
            iwxab_s103av_reload_try++;
            XYLog("PROBE S103av FIX1 reload_failed try=%u/%u ic_state=%d if_flags=0x%x "
                  "gen=%d sc_gen=%d\n",
                  (unsigned)iwxab_s103av_reload_try,
                  (unsigned)IWX_S103AV_MAX_RELOAD_TRIES,
                  (int)sc->sc_ic.ic_state, (unsigned)ifp->if_flags,
                  generation, (int)sc->sc_generation);
            if (iwxab_s103av_reload_try < IWX_S103AV_MAX_RELOAD_TRIES) {
                /* `iwx_init_task` is a STATIC member (`ItlIwx.hpp:624`), so the instance sleep
                 * helpers are not reachable from here; `IOSleep` is the IOKit sleep this file
                 * already uses for exactly this purpose (see `:7528`).  It yields the systq
                 * thread, which is what the 2 s settle is for -- the re-armed task must not run
                 * before the firmware has had time to finish the stop it was just given. */
                IOSleep(IWX_S103AV_RELOAD_RETRY_MS);
                /* Re-arm ONLY if nothing else took over while we slept: if a concurrent stop or a
                 * userspace ioctl moved the generation, that other actor owns the interface now and
                 * a second init_task would be a duplicate.  This is the SAME guard the task opened
                 * with, re-asserted at the point of use (0ja/0ik). */
                if (generation == sc->sc_generation &&
                    (ifp->if_flags & (IFF_UP | IFF_RUNNING)) == IFF_UP &&
                    (sc->sc_flags & IWX_FLAG_SHUTDOWN) == 0) {
                    iwxabS189Guard(1, generation, (int)sc->sc_generation);
                    XYLog("PROBE S103av FIX1 re-arm try=%u\n",
                          (unsigned)iwxab_s103av_reload_try);
                    task_add(systq, &sc->init_task);
                } else {
                    iwxabS189Guard(0, generation, (int)sc->sc_generation);
                    XYLog("PROBE S103av FIX1 re-arm DECLINED gen=%d sc_gen=%d if_flags=0x%x "
                          "shutdown=%d\n",
                          generation, (int)sc->sc_generation, (unsigned)ifp->if_flags,
                          (sc->sc_flags & IWX_FLAG_SHUTDOWN) ? 1 : 0);
                }
            } else {
                XYLog("PROBE S103av FIX1 GIVING UP after %u tries -- the link is NOT recovered and "
                      "the driver will not try again; ic_state=%d\n",
                      (unsigned)iwxab_s103av_reload_try, (int)sc->sc_ic.ic_state);
            }
        } else {
            /* Success: the link is being re-established and the budget is spent. */
            iwxab_s103av_reload_try = 0;
        }
    } else {
        /* ==== S103av PROBE C2: THE BRANCH THAT NEVER RE-JOINS ==================================
         * If this line appears, `iwx_init()` was NOT called and the driver has no path back to a
         * link: either `fatal` (HW_ERR/RFKILL was set), or the `IFF_UP && !IFF_RUNNING` test
         * failed.  Both are otherwise INVISIBLE -- the task just ends.  This is the second, and
         * narrower, way the recovery is lost, and it is distinguishable from PROBE C by the
         * generation pair being EQUAL here. */
        XYLog("PROBE S103av init_task EXIT=no_init fatal=%d if_flags=0x%x ic_state=%d "
              "running=%d up=%d shutdown=%d\n",
              fatal, (unsigned)ifp->if_flags, (int)sc->sc_ic.ic_state,
              (ifp->if_flags & IFF_RUNNING) ? 1 : 0, (ifp->if_flags & IFF_UP) ? 1 : 0,
              (sc->sc_flags & IWX_FLAG_SHUTDOWN) ? 1 : 0);
    }
#endif
    
    //    rw_exit(&sc->ioctl_rwl);
    splx(s);
}

int ItlIwx::
iwx_resume(struct iwx_softc *sc)
{
    pcireg_t reg;
    
    /* Clear device-specific "PCI retry timeout" register (41h). */
    reg = pci_conf_read(sc->sc_pct, sc->sc_pcitag, 0x40);
    pci_conf_write(sc->sc_pct, sc->sc_pcitag, 0x40, reg & ~0xff00);
    
    if (!sc->sc_msix) {
        /* Hardware bug workaround. */
        reg = pci_conf_read(sc->sc_pct, sc->sc_pcitag,
                            PCI_COMMAND_STATUS_REG);
        if (reg & PCI_COMMAND_INTERRUPT_DISABLE)
            reg &= ~PCI_COMMAND_INTERRUPT_DISABLE;
        pci_conf_write(sc->sc_pct, sc->sc_pcitag,
                       PCI_COMMAND_STATUS_REG, reg);
    }

    iwx_enable_rfkill_int(sc);
    iwx_check_rfkill(sc);

    return iwx_prepare_card_hw(sc);
}

int ItlIwx::
iwx_activate(struct iwx_softc *sc, int act)
{
    struct _ifnet *ifp = &sc->sc_ic.ic_if;
    int err = 0;
    
    switch (act) {
        case DVACT_QUIESCE:
            if (ifp->if_flags & IFF_RUNNING) {
                //            rw_enter_write(&sc->ioctl_rwl);
                iwx_stop(ifp);
                //            rw_exit(&sc->ioctl_rwl);
            }
            break;
        case DVACT_RESUME:
            err = iwx_resume(sc);
            if (err)
                XYLog("%s: could not initialize hardware\n",
                      DEVNAME(sc));
            break;
        case DVACT_WAKEUP:
            /* Hardware should be up at this point. */
            if (iwx_set_hw_ready(sc))
                task_add(systq, &sc->init_task);
            break;
    }
    
    return 0;
}

/* @@S147_SPLIT@@ -- everything ABOVE this line is a DECLARATION and is placed at the top of the
 * file, above its first use, because C++ requires declaration before use at file scope.  The
 * S103az round lost a build to exactly this omission, and this round's EDIT 2 assigns
 * `iwxab_s147_cf_before` at line 1616 -- 21,000 lines above this block -- so the scalars MUST
 * live at the top, not here.  Everything BELOW the line is a DEFINITION and stays here. */

/* The scan.  Reads host memory that the driver itself allocated and told the firmware about. */
static void
iwxabS147Scan(struct iwx_softc *sc)
{
    uint32_t *p;
    uint8_t *b;
    size_t limit, k;
    uint32_t nz2 = 0, nz64 = 0;
    int i, t;

    if (sc == NULL || sc->fw_mon.vaddr == NULL || sc->fw_mon.size < 4)
        return;
    p = (uint32_t *)sc->fw_mon.vaddr;
    b = (uint8_t *)sc->fw_mon.vaddr;

    for (i = 0; i < 2048; i++)
        if (p[i] != 0)
            nz2++;
    iwxab_s147_nz2048 = nz2;
    if (nz2 > iwxab_s147_nz2048_max)
        iwxab_s147_nz2048_max = nz2;

    limit = 65536;
    if ((size_t)sc->fw_mon.size < limit)
        limit = (size_t)sc->fw_mon.size;
    for (k = 0; k + 4 <= limit; k += 4)
        if (p[k >> 2] != 0)
            nz64++;
    iwxab_s147_nz64k = nz64;
    iwxab_s147_scan_n++;
    if (nz64 > iwxab_s147_nz64k_max) {
        iwxab_s147_nz64k_max = nz64;
        if (iwxab_s147_first_nz_scan == 0)
            iwxab_s147_first_nz_scan = iwxab_s147_scan_n;
        for (i = 0; i < 8; i++)
            iwxab_s147_first8[i] = p[i];
        iwxab_s147_first8_valid = 1;
        snprintf(iwxab_s147_f8s, sizeof(iwxab_s147_f8s),
                 "%08x,%08x,%08x,%08x,%08x,%08x,%08x,%08x",
                 iwxab_s147_first8[0], iwxab_s147_first8[1],
                 iwxab_s147_first8[2], iwxab_s147_first8[3],
                 iwxab_s147_first8[4], iwxab_s147_first8[5],
                 iwxab_s147_first8[6], iwxab_s147_first8[7]);
    }

    /* An all-zero window cannot contain a name, so the expensive part is skipped -- and the
     * cached hit values are CLEARED, so a stale hit can never outlive the data that made it. */
    if (nz64 == 0) {
        iwxab_s147_hits_total = 0;
        iwxab_s147_hits_distinct = 0;
        iwxab_s147_hitlist[0] = 0;
        return;
    }
    {
        int total = 0, distinct = 0, used = 0;

        iwxab_s147_hitlist[0] = 0;
        for (t = 0; t < IWXAB_S147_NNAMES; t++) {
            size_t nl = strlen(iwxab_s147_names[t]);
            int hits = 0;

            if (nl < 4)             /* too short to be evidence -- excluded by rule */
                continue;
            for (k = 0; k + nl <= limit; k++)
                if (memcmp(b + k, iwxab_s147_names[t], nl) == 0)
                    hits++;
            if (hits) {
                distinct++;
                total += hits;
                if (used < (int)sizeof(iwxab_s147_hitlist) - 48)
                    used += snprintf(iwxab_s147_hitlist + used,
                                     sizeof(iwxab_s147_hitlist) - used,
                                     "%s:%d ", iwxab_s147_names[t], hits);
            }
        }
        iwxab_s147_hits_total = (uint32_t)total;
        iwxab_s147_hits_distinct = (uint32_t)distinct;
    }
}

/* Publish: the whole state of the channel, every tick, on a channel that cannot wrap. */
static void
iwxabS147Publish(struct iwx_softc *sc, const char *why)
{
    int nobuf;
    OSString *os;

    if (sc == NULL)
        return;
    iwxab_s147_pub_n++;
    nobuf = (sc->fw_mon.vaddr == NULL || sc->fw_mon.size == 0);
    if (!nobuf)
        iwxabS147Scan(sc);

    snprintf(iwxab_s147_str, sizeof(iwxab_s147_str),
             "S147 n=%u why=%s %s cf_before=0x%08x cf_after=0x%08x earlydbg=%u dramdst=%u "
             "paddr=0x%llx size=0x%08x nz2048=%u nz2048_max=%u nz64k=%u nz64k_max=%u "
             "hits=%u distinct=%u first_nz_scan=%u f8=[%s] names=[%s]",
             iwxab_s147_pub_n, why, nobuf ? "NOBUF" : "BUF",
             iwxab_s147_cf_before, iwxab_s147_cf_after,
             (iwxab_s147_cf_after & IWX_PRPH_SCRATCH_EARLY_DEBUG_EN) ? 1u : 0u,
             (iwxab_s147_cf_after & IWX_PRPH_SCRATCH_EDBG_DEST_DRAM) ? 1u : 0u,
             (unsigned long long)sc->fw_mon.paddr, (unsigned)sc->fw_mon.size,
             iwxab_s147_nz2048, iwxab_s147_nz2048_max,
             iwxab_s147_nz64k, iwxab_s147_nz64k_max,
             iwxab_s147_hits_total, iwxab_s147_hits_distinct,
             iwxab_s147_first_nz_scan,
             iwxab_s147_first8_valid ? iwxab_s147_f8s : "none",
             iwxab_s147_hitlist[0] ? iwxab_s147_hitlist : "none");

    /* The log line, ONLY when the answer changes (`0km`: a varying field is printed, but the
     * series is published on the property so the log can stay honest and small). */
    if (nobuf || iwxab_s147_nz64k != iwxab_s147_last_logged_nz) {
        iwxab_s147_last_logged_nz = iwxab_s147_nz64k;
        XYLog("PROBE %s\n", iwxab_s147_str);
    }
    if (sc->sc_pcitag != NULL) {
        os = OSString::withCString(iwxab_s147_str);
        if (os != NULL) {
            sc->sc_pcitag->setProperty("iwxctl_s147", os);
            os->release();
        }
    }
}
/* ==== S147 DIAGNOSTIC END ==================================================================== */


/* ==== S150 DIAGNOSTIC BEGIN ==================================================================
 * *** THE INI DEBUG ARM.  SEPARABLE: delete the five S150 ranges and restore the S69 block quoted
 * in the S150 receipt, and the tree is the S147 tree again. ***
 *
 * READ THIS BEFORE READING THE CODE
 * ---------------------------------
 * The three payloads are ONE VARIABLE because the reference's INI arm is atomic:
 *     pcie/ctxt-info-v2.c:74-91   hwm_base_addr/hwm_size/debug_token_config from frags[0] and
 *                                 trans->dbg.ucode_preset, together with EDBG_DEST_DRAM;
 *     pcie/ctxt-info-v2.c:96-97   EARLY_DEBUG_EN | dbg_flags, once, outside the if/else;
 *     iwl-dbg-tlv.c:914-947       the DBGC_DRAM_ADDR CONF_SET writes the SAME frags[0] into HW SMEM.
 * There is no Linux state in which one of them is sent without the others, and S147 measured that
 * the enable without the payload kills this firmware.  So this round changes the payload, not the
 * enable: the enable is S147's and is retained.
 *
 * WHY A PRESET, AND WHY *THIS* PRESET
 * -----------------------------------
 * The image carries its debug configuration as 15 PRESETS encoded in each TLV's `domain` field
 * (bit 16+N).  iwl_dbg_tlv_alloc() (iwl-dbg-tlv.c:341-347) SKIPS any TLV whose domain does not
 * intersect trans->dbg.domains_bitmap, and iwl-drv.c:1999 sets that bitmap to BIT(16+enable_ini).
 * This block implements exactly that rule with IWXAB_S150_INI_PRESET, so the answer to "which of
 * the 13 PERIPH_SCRATCH_HWM entries" is the reference's, not this round's.
 * MEASURED, not assumed: with DEFAULT module parameters the bitmap is 0x0 and Linux skips all of
 * these TLVs -- the project's own Linux run on this silicon logs 20x
 *   "iwl_dbg_tlv_alloc WRT: Skipping TLV with disabled domain 0x10000 (0x0)"
 * (08-linux-harness/evidence/debug-kernel-trace.txt).  Linux at default parameters therefore
 * programs NO debug payload at all, which is why it reaches ALIVE.  A preset is a DRIVER choice;
 * preset 1 ('InitDefault') is this round's, and it is one of the six presets that carry all three
 * payloads (offline measurement, 05-artifacts/s150/row0/s150-ini-parse.txt).
 *
 * THE HW-SMEM WRITE (the dangerous new call)
 * ------------------------------------------
 * iwx_write_mem() (this file, `iwx_write_mem`) is a PRPH-addressed write: it takes the NIC lock via
 * iwx_nic_lock() and releases it, and it does NOT call iwx_write_prph()/iwx_read_prph(), so it can
 * never reach iwx_nic_assert_locked() (`iwx_nic_assert_locked`) and the sc_nic_locks panic path
 * (0bq).  LINE NUMBERS ARE OMITTED ON PURPOSE: they were 3849/3934 in the S147 tree and moved.
 * Its return code is published: 0 proves the lock was taken (EBUSY otherwise), and
 * IWXAB_S150_SMEM_RC_NOT_TRIED is a distinct value so "not attempted" cannot read as success.
 * ============================================================================ */

/* iwl-dbg-tlv.c:341-347.  IWL_FW_INI_DOMAIN_ALWAYS_ON is 0 (fw/api/dbg-tlv.h:13). */
static int
iwxabS150DomainOk(uint32_t domain)
{
    if (domain == 0)
        return 1;
    return (domain & iwxab_s150.domains) != 0;
}

static void
iwxabS150IniScan(struct iwx_softc *sc, const void *raw, size_t rawsize)
{
    struct iwxab_s150_ini *s = &iwxab_s150;
    const uint8_t *b = (const uint8_t *)raw;
    size_t off, hdr;

    memset(s, 0, sizeof(*s));
    s->preset = IWXAB_S150_INI_PRESET;
    s->domains = (uint32_t)1 << (IWXAB_S150_DOMAIN_POS + IWXAB_S150_INI_PRESET);
    s->smem_rc = IWXAB_S150_SMEM_RC_NOT_TRIED;

    /*
     * THE SIZE GATES, BEFORE A SINGLE BYTE IS DECODED.  The image's TLV chain starts at 88 --
     * measured, not assumed (05-artifacts/s150/row0/s150-ini-parse.txt, and the 0q24 correction:
     * the chain ALSO lands on EOF from 80, so the offset is proven by the struct layout plus the
     * INVALID type-0 entry at 80, not by EOF alone).  A struct that grew, or a packed attribute
     * that did not take, would silently decode garbage here, so the sizes are checked at runtime.
     */
    hdr = sizeof(struct iwx_tlv_ucode_header);
    if (hdr != 88 || sizeof(struct iwx_fw_ini_allocation_tlv) != 28 ||
        sizeof(struct iwxab_s150_conf_hdr) != 20 || sizeof(struct iwx_ucode_tlv) != 8) {
        s->refused = 1;
        XYLog("PROBE S150 ini_scan REFUSED: sizeof(ucode_header)=%u (want 88) "
              "sizeof(allocation_tlv)=%u (want 28) sizeof(conf_hdr)=%u (want 20) "
              "sizeof(ucode_tlv)=%u (want 8) -- THE LAYOUT DOES NOT MATCH THE IMAGE, "
              "nothing will be armed\n",
              (unsigned)sizeof(struct iwx_tlv_ucode_header),
              (unsigned)sizeof(struct iwx_fw_ini_allocation_tlv),
              (unsigned)sizeof(struct iwxab_s150_conf_hdr),
              (unsigned)sizeof(struct iwx_ucode_tlv));
        return;
    }
    if (raw == NULL || rawsize < hdr + 8)
        return;
    s->scanned = 1;

    for (off = hdr; off + 8 <= rawsize; ) {
        const struct iwx_ucode_tlv *tlv =
            (const struct iwx_ucode_tlv *)(const void *)(b + off);
        uint32_t type = le32toh(tlv->type);
        uint32_t len = le32toh(tlv->length);

        if ((size_t)len > rawsize - off - 8) {
            s->truncated = 1;
            break;
        }
        s->n_tlv++;
        switch (type) {
        case IWX_UCODE_TLV_TYPE_BUFFER_ALLOCATION: {
            if ((size_t)len == sizeof(struct iwx_fw_ini_allocation_tlv)) {
                const struct iwx_fw_ini_allocation_tlv *a =
                    (const struct iwx_fw_ini_allocation_tlv *)(const void *)(b + off + 8);
                uint32_t aid = le32toh(a->alloc_id);
                uint32_t loc = le32toh(a->buf_location);
                uint32_t dom = le32toh(a->hdr.domain);
                if (iwxabS150DomainOk(dom) &&
                    aid == IWX_FW_INI_ALLOCATION_ID_DBGC1 &&
                    loc == IWX_FW_INI_LOCATION_DRAM_PATH) {
                    /*
                     * Linux: `trans->dbg.fw_mon_cfg[alloc_id] = *alloc;` (iwl-dbg-tlv.c:156)
                     * as each TLV is parsed IN FILE ORDER, so a LATER TLV for the same
                     * alloc_id REPLACES an earlier one.  The LAST accepted DBGC1 entry is
                     * therefore the one Linux uses -- not the first, and not "the 4 MiB one".
                     */
                    s->have_alloc = 1;
                    s->alloc_off = (uint32_t)off;
                    s->req_size = le32toh(a->req_size);
                    s->max_frags = le32toh(a->max_frags_num);
                    s->min_size = le32toh(a->min_size);
                }
            }
            break;
        }
        case IWX_UCODE_TLV_TYPE_CONF_SET: {
            if ((size_t)len >= sizeof(struct iwxab_s150_conf_hdr) + 8) {
                const struct iwxab_s150_conf_hdr *c =
                    (const struct iwxab_s150_conf_hdr *)(const void *)(b + off + 8);
                uint32_t dom = le32toh(c->hdr.domain);
                uint32_t tp = le32toh(c->time_point);
                uint32_t st = le32toh(c->set_type);
                uint32_t aoff = le32toh(c->addr_offset);
                /*
                 * Linux adds every accepted CONF_SET to time_point[tp].config_list and the EARLY
                 * time point is the only one that runs before the ctxt-info is built, so the
                 * ctxt-info's debug_token_config can only come from a tp == EARLY entry.
                 * apply_config() walks the list in order and overwrites ucode_preset, so the LAST
                 * accepted PERIPH_SCRATCH_HWM wins -- the same last-one-wins rule as above.
                 */
                if (iwxabS150DomainOk(dom) && tp == IWXAB_S150_TP_EARLY) {
                    const uint32_t *av = (const uint32_t *)(const void *)
                        (b + off + 8 + sizeof(struct iwxab_s150_conf_hdr));
                    if (st == IWXAB_S150_SET_PERIPH_SCRATCH_HWM) {
                        s->have_token = 1;
                        s->token = le32toh(av[1]);      /* addr_val[0].value */
                        s->token_off = (uint32_t)off;
                    } else if (st == IWXAB_S150_SET_DBGC_DRAM_ADDR) {
                        /* Linux writes the same descriptor to address + addr_offset for
                         * EVERY addr_val[] entry; the target recorded is the first. */
                        s->have_dram = 1;
                        s->smem_addr = (le32toh(av[0]) + aoff) & 0xffffffffu;
                        s->n_smem = (len - sizeof(struct iwxab_s150_conf_hdr)) / 8;
                        s->smem_off = (uint32_t)off;
                    }
                }
            }
            break;
        }
        default:
            break;
        }
        off += 8 + (((size_t)len + 3) & ~(size_t)3);
    }

    /*
     * LINUX'S FRAGMENT ARITHMETIC, reproduced exactly (iwl_dbg_tlv_alloc_fragments,
     * iwl-dbg-tlv.c:588-665).  req_size is the REQUEST; what the firmware is told is the size of
     * FRAGMENT 0, because that is the one fragment the driver hands over through the ctxt-info.
     * On this image BUF_ALLOC_MAX_NUM_FRAGS (16) == max_frags_num (16) == remain_pages/64, so
     * frag[0].size is req_size/16.  The remaining fragments would be announced by a
     * BUFFER_ALLOCATION host command AFTER ALIVE -- and
     * IWL_UCODE_TLV_CAPA_DBG_BUF_ALLOC_CMD_SUPP (bit 93) is ABSENT from this image (measured),
     * so iwl_dbg_tlv_apply_buffer() returns immediately and Linux never sends them either.
     * frag[0] IS the whole DBGC1 payload on this image.
     */
    if (s->have_alloc && s->req_size != 0 && s->max_frags != 0) {
        uint32_t remain_pages = (s->req_size + 4095u) / 4096u;
        uint32_t nf = s->max_frags;
        uint32_t frag_pages;
        if (nf > IWXAB_S150_BUF_ALLOC_MAX_NUM_FRAGS)
            nf = IWXAB_S150_BUF_ALLOC_MAX_NUM_FRAGS;
        if (nf > remain_pages)
            nf = remain_pages;
        if (nf == 0)
            nf = 1;
        frag_pages = (remain_pages + nf - 1) / nf;
        s->frag0_size = frag_pages * 4096u;
    }

    XYLog("PROBE S150 ini_scan preset=%u domains=0x%08x tlvs=%u truncated=%u "
          "alloc=%u(off=%u req=%u max_frags=%u min_size=%u frag0=%u) "
          "token=%u(0x%x off=%u) dram=%u(smem=0x%08x off=%u n=%u)\n",
          s->preset, s->domains, s->n_tlv, s->truncated,
          s->have_alloc, s->alloc_off, s->req_size, s->max_frags, s->min_size, s->frag0_size,
          s->have_token, s->token, s->token_off,
          s->have_dram, s->smem_addr, s->smem_off, s->n_smem);
}

/*
 * THE ARM.  Called where S147's S69 payload block was: after rbd_cfg, before control_flags is
 * written into prph_scratch, and therefore before IWX_CSR_CTXT_INFO_BA and long before the
 * CPU_INIT_RUN kick -- the same position in the sequence as Linux's EARLY time point, which runs
 * before iwl_trans_start_fw() (mld/fw.c:243 -> :245).
 */
static void
iwxabS150IniArm(ItlIwx *self, struct iwx_softc *sc,
                struct iwx_prph_scratch_ctrl_cfg *ctrl, uint32_t *cf)
{
    struct iwxab_s150_ini *s = &iwxab_s150;
    int err;

    s->cf_before = *cf;
    s->cf_after = *cf;

    /* ---- FAIL CLOSED, LOUDLY.  A missing payload must not become a plausible zero. ---- */
    if (!s->scanned || s->refused) {
        XYLog("PROBE S150 ini_arm REFUSED: scanned=%u refused=%u -- the image was not parsed, "
              "so NOTHING is armed and control_flags is untouched (mode=NOINI)\n",
              s->scanned, s->refused);
        iwxabS150Publish(sc, "arm_refused", 1);
        return;
    }
    if (!s->have_alloc || s->req_size == 0 || s->frag0_size == 0) {
        XYLog("PROBE S150 ini_arm REFUSED: have_alloc=%u req_size=%u frag0=%u -- no DBGC1 DRAM "
              "allocation TLV at preset %u; NOTHING is armed (mode=NOINI)\n",
              s->have_alloc, s->req_size, s->frag0_size, s->preset);
        iwxabS150Publish(sc, "arm_refused", 1);
        return;
    }
    if (!s->have_token) {
        XYLog("PROBE S150 ini_arm REFUSED: no PERIPH_SCRATCH_HWM CONF_SET at preset %u -- "
              "debug_token_config would be a fabricated 0, so NOTHING is armed (mode=NOINI)\n",
              s->preset);
        iwxabS150Publish(sc, "arm_refused", 1);
        return;
    }
    if (!s->have_dram) {
        XYLog("PROBE S150 ini_arm REFUSED: no DBGC_DRAM_ADDR CONF_SET at preset %u -- the HW-SMEM "
              "descriptor would be missing, so NOTHING is armed (mode=NOINI)\n", s->preset);
        iwxabS150Publish(sc, "arm_refused", 1);
        return;
    }
    if (s->frag0_size <= 0x400u) {
        /* struct iwl_dbgc1_info carries frag[0].size - 0x400; a fragment at or below 0x400 would
         * UNDERFLOW that field.  The image cannot produce it (frag0 is page-rounded, >= 4096),
         * but a guard that can never fire is cheaper than an underflow that never should. */
        XYLog("PROBE S150 ini_arm REFUSED: frag0_size=%u <= 0x400 -- the descriptor's size field "
              "would underflow; NOTHING is armed (mode=NOINI)\n", s->frag0_size);
        iwxabS150Publish(sc, "arm_refused", 1);
        return;
    }

    /*
     * (i) THE BUFFER.  Sized by the TLV's req_size -- the request -- because that is what the
     * image asks for and it is LARGER than the region the firmware is told about (frag[0].size),
     * so a firmware that writes past its advertised region still writes inside memory the driver
     * owns.  That asymmetry is deliberate and is stated in the receipt: the WIRE value is
     * frag0_size, the ALLOCATION is req_size.
     */
    if (sc->fw_mon.size == 0) {
        err = self->iwx_dma_contig_alloc(sc->sc_dmat, &sc->fw_mon, s->req_size, 0);
        s->alloc_rc = err;
        if (err != 0 || sc->fw_mon.size == 0) {
            XYLog("PROBE S150 ini_arm REFUSED: iwx_dma_contig_alloc(%u) rc=%d size=%u -- "
                  "NOTHING is armed (mode=NOINI)\n",
                  s->req_size, err, (unsigned)sc->fw_mon.size);
            iwxabS150Publish(sc, "arm_refused", 1);
            return;
        }
    } else {
        s->alloc_rc = 0;    /* a buffer already existed; its size is reported below */
    }
    s->buf_size = (uint32_t)sc->fw_mon.size;

    /* ==== S152 BEGIN: *** THE STALE-PAGES FALSIFIER *** =====================================
     * THE ALTERNATIVE THIS CLOSES, stated because it was the only one left: the allocator does
     * not zero (`iwx_dma_contig_alloc` -> `allocDmaMemory2` -> IOBufferMemoryDescriptor, no
     * explicit zeroing), and the driver never writes this buffer -- so "the buffer filled" could
     * in principle have been pages that already contained data.  Zeroing HERE, before the
     * ctxt-info is programmed and before the UREG_CPU_INIT_RUN kick, makes the next non-zero
     * census either the firmware's or nothing.
     *
     * ORDERING, IN SOURCE AND AT RUNTIME:
     *   SOURCE : this memset  <  the arm call site in iwx_ctxt_info_gen3_init  <  IWX_WRITE64(
     *            IWX_CSR_CTXT_INFO_BA)  <  iwx_write_prph(IWX_UREG_CPU_INIT_RUN, 1)
     *            (proved line-by-line by 07-scripts/s152-ordergate.py, which REFUSES otherwise)
     *   RUNTIME: the read-back below samples the buffer IMMEDIATELY after the memset and is
     *            published from the end of this function, i.e. before the kick -- so `nz_arm`
     *            and `f8arm` are what the buffer held before the firmware could write.
     * DEVICE-VISIBLE BEHAVIOUR IS UNCHANGED BY THIS BLOCK: memset and the count touch host
     * memory only.  The hwm_cfg, the control_flags bits and the HW-SMEM descriptor below are
     * byte-for-byte the ones the 5159a25d build programmed.
     * ====================================================================================== */
    if (sc->fw_mon.vaddr != NULL && sc->fw_mon.size != 0)
        memset(sc->fw_mon.vaddr, 0, (size_t)sc->fw_mon.size);
    {
        const uint32_t *z = (const uint32_t *)sc->fw_mon.vaddr;
        size_t zn = (size_t)sc->fw_mon.size / 4, k;
        uint32_t nz = 0;
        if (zn > 16384)
            zn = 16384;                     /* the same 64 KiB window the census reports on */
        if (z != NULL) {
            for (k = 0; k < zn; k++)
                if (z[k] != 0)
                    nz++;
            for (k = 0; k < 8 && k < zn; k++)
                s->f8_arm[k] = z[k];
            s->f8_arm_valid = 1;
        }
        s->nz_arm = nz;
    }
    /* ==== S152 END ========================================================================= */

    /* ---- (ii) THE ARM ITSELF: pcie/ctxt-info-v2.c:96-97 and :74-91 ---- */
    *cf |= IWX_PRPH_SCRATCH_EDBG_DEST_DRAM;      /* BIT(8)  -- the destination             */
    *cf |= IWX_PRPH_SCRATCH_EARLY_DEBUG_EN;      /* BIT(4)  -- the enable S147 found missing */
    s->cf_after = *cf;
    ctrl->hwm_cfg.hwm_base_addr = htole64(sc->fw_mon.paddr);
    ctrl->hwm_cfg.hwm_size = htole32(s->frag0_size);
    ctrl->hwm_cfg.reserved = htole32(s->token);  /* Linux's debug_token_config, offset 44 */
    s->armed = 1;
    s->paddr_lo = (uint32_t)(sc->fw_mon.paddr & 0xffffffffULL);
    s->paddr_hi = (uint32_t)((sc->fw_mon.paddr >> 32) & 0xffffffffULL);

    /*
     * (iii) THE HW-SMEM DESCRIPTOR, iwl-dbg-tlv.c:914-947.  struct iwl_dbgc1_info, 4 dwords:
     *   [0] first_word     = 0                      (all-zero identifier)
     *   [1] dbgc1_add_lsb  = (dram_addr & 0xffffffff) + 0x400
     *   [2] dbgc1_add_msb  = (dram_addr >> 32)
     *   [3] dbgc1_size     = frag[0].size - 0x400
     * Note Linux does NOT carry a 32-bit overflow from [1] into [2]; reproduced as written.
     * The write is iwx_write_mem(): it takes the NIC lock itself, so this cannot trip
     * iwx_nic_assert_locked()/panic (0bq).  smem_rc is published; NOT_TRIED is distinct.
     */
    s->smem_payload[0] = 0;
    s->smem_payload[1] = htole32(s->paddr_lo + 0x400u);
    s->smem_payload[2] = htole32(s->paddr_hi);
    s->smem_payload[3] = htole32(s->frag0_size - 0x400u);
    s->smem_tried = 1;
    s->smem_rc = self->iwx_write_mem(sc, s->smem_addr, s->smem_payload, 4);

    /* Keep the S147 instrument's view of the same event consistent with this one. */
    iwxab_s147_cf_before = s->cf_before;
    iwxab_s147_cf_after = s->cf_after;

    XYLog("PROBE S150 ini_arm preset=%u domains=0x%08x req=%u frag0=%u token=0x%x "
          "smem=0x%08x smem_rc=%d payload=[%08x,%08x,%08x,%08x] cf_before=0x%08x "
          "cf_after=0x%08x paddr=0x%08x%08x buf=%u (Linux: ctxt-info-v2.c:74-97 + dbg-tlv.c:914-957)\n",
          s->preset, s->domains, s->req_size, s->frag0_size, s->token,
          s->smem_addr, s->smem_rc,
          s->smem_payload[0], s->smem_payload[1], s->smem_payload[2], s->smem_payload[3],
          s->cf_before, s->cf_after, s->paddr_hi, s->paddr_lo, s->buf_size);
    iwxabS150Publish(sc, "arm", 1);
}

/*
 * The readout.  `iwxctl_s150` is a PROPERTY, republished at 1 Hz from the watchdog (thread
 * context), because a log line can wrap and a wrapped log reads as "nothing happened".  The
 * census fields are S147's, which the caller refreshes immediately before this runs, so the
 * payload fields and the buffer measurement always describe the same instant.
 */
static void
iwxabS150Publish(struct iwx_softc *sc, const char *why, int logit)
{
    struct iwxab_s150_ini *s = &iwxab_s150;
    OSString *os;

    if (sc == NULL)
        return;
    s->pub_n++;
    /* S152: a FRESH sample of the first 8 dwords on every publish, so the content can be
     * compared at two or more instants and against the S147 instrument's frozen `f8`. */
    {
        const uint32_t *q = (const uint32_t *)sc->fw_mon.vaddr;
        uint32_t w[8];
        int i;
        for (i = 0; i < 8; i++)
            w[i] = (q != NULL && (size_t)sc->fw_mon.size >= 4 * (size_t)(i + 1)) ? q[i] : 0;
        snprintf(iwxab_s152_nows, sizeof(iwxab_s152_nows),
                 "%08x,%08x,%08x,%08x,%08x,%08x,%08x,%08x",
                 w[0], w[1], w[2], w[3], w[4], w[5], w[6], w[7]);
        if (s->f8_arm_valid)
            snprintf(iwxab_s152_arms, sizeof(iwxab_s152_arms),
                     "%08x,%08x,%08x,%08x,%08x,%08x,%08x,%08x",
                     s->f8_arm[0], s->f8_arm[1], s->f8_arm[2], s->f8_arm[3],
                     s->f8_arm[4], s->f8_arm[5], s->f8_arm[6], s->f8_arm[7]);
        else
            snprintf(iwxab_s152_arms, sizeof(iwxab_s152_arms), "not-sampled");
    }
    snprintf(iwxab_s150_str, sizeof(iwxab_s150_str),
             "S150 n=%u why=%s mode=%s preset=%u domains=0x%08x tlvs=%u "
             "alloc=%u off=%u req=%u maxfrags=%u minsize=%u frag0=%u "
             "token=0x%x token_off=%u smem=0x%08x smem_tried=%u smem_rc=%d "
             "payload=[%08x,%08x,%08x,%08x] armed=%u cf=0x%08x->0x%08x "
             "paddr=0x%08x%08x buf=0x%x alloc_rc=%d "
             "nz2048=%u nz2048_max=%u nz64k=%u hits=%u distinct=%u names=[%s] "
             "S152 nz_arm=%u f8arm=[%s] f8now=[%s]",
             s->pub_n, why, s->armed ? "INI" : "NOINI", s->preset, s->domains, s->n_tlv,
             s->have_alloc, s->alloc_off, s->req_size, s->max_frags, s->min_size,
             s->frag0_size, s->token, s->token_off, s->smem_addr, s->smem_tried, s->smem_rc,
             s->smem_payload[0], s->smem_payload[1], s->smem_payload[2], s->smem_payload[3],
             s->armed, s->cf_before, s->cf_after, s->paddr_hi, s->paddr_lo, s->buf_size,
             s->alloc_rc,
             iwxab_s147_nz2048, iwxab_s147_nz2048_max, iwxab_s147_nz64k,
             iwxab_s147_hits_total, iwxab_s147_hits_distinct,
             iwxab_s147_hitlist[0] ? iwxab_s147_hitlist : "none",
             s->nz_arm, iwxab_s152_arms, iwxab_s152_nows);
    if (sc->sc_pcitag != NULL) {
        os = OSString::withCString(iwxab_s150_str);
        if (os != NULL) {
            sc->sc_pcitag->setProperty("iwxctl_s150", os);
            os->release();
        }
    }
    if (logit)
        XYLog("PROBE %s\n", iwxab_s150_str);
}
/* ==== S150 DIAGNOSTIC END ==================================================================== */


/* ==== S156 DIAGNOSTIC BEGIN ==================================================================
 * *** THE INI TIME POINT: APPLY THE TRIGGER THE IMAGE ITSELF DECLARES, AND DUMP ITS REGIONS. ***
 *
 * WHY tp=9 AND NOT tp=2: measured from the image at preset 1 (05-artifacts/s156/row0/s156-row0.txt),
 * the accepted triggers reference time points 4/5/8/9/12/13 -- *** and NOT 2 (AFTER_ALIVE) ***.  A
 * driver cannot fire a time point the image associates with no trigger: that would be inventing one.
 * tp=9 USER_TRIGGER is the image's own "the driver fires this" time point, so it is the one applied.
 *
 * WHO WRITES THE REGION NAMES: *** THE DRIVER, NOT THE FIRMWARE. ***  In the reference, a time point
 * calls iwl_fw_dbg_ini_collect() -> iwl_fw_error_ini_dump() -> iwl_dump_ini_trigger(), which READS
 * each region out of the device (iwl_trans_read_mem_bytes / iwl_trans_read_prph) and WRITES an
 * INI-shaped record -- including the region NAME -- into a driver-owned buffer
 * (iwl_dump_ini_*_fill_header).  This block does the same thing into a static host buffer, so a
 * name present in it is OUR WRITE and proves only that the FORMAT was built, never that the device
 * produced it.  The evidence of a dump is the per-region READ: its return code, its byte count and
 * the data that came back.  The receipt states this distinction explicitly.
 * ============================================================================ */

static void
iwxabS156IniScan(struct iwx_softc *sc, const void *raw, size_t rawsize)
{
    struct iwxab_s156_state *s = &iwxab_s156;
    const uint8_t *b = (const uint8_t *)raw;
    size_t off, hdr = sizeof(struct iwx_tlv_ucode_header);
    uint32_t domains;

    memset(s, 0, sizeof(*s));
    if (raw == NULL || rawsize < hdr + 8 || hdr != 88)
        return;
    domains = (uint32_t)1 << (16 + IWXAB_S150_INI_PRESET);
    s->scanned = 1;
    for (off = hdr; off + 8 <= rawsize; ) {
        const struct iwx_ucode_tlv *tlv = (const struct iwx_ucode_tlv *)(const void *)(b + off);
        uint32_t type = le32toh(tlv->type);
        uint32_t len = le32toh(tlv->length);
        if ((size_t)len > rawsize - off - 8)
            break;
        if (type == IWX_UCODE_TLV_TYPE_REGIONS && len >= 64) {
            const uint8_t *d = b + off + 8;
            uint32_t raw_id, dom, idx, typ, base = 0, size = 0, aoff = 0, alloc_id = 0;
            memcpy(&raw_id, d + 8, 4);
            raw_id = le32toh(raw_id);
            idx = raw_id & 0xffffu;              /* IWL_FW_INI_REGION_ID_MASK == GENMASK(15,0) */
            memcpy(&dom, d + 4, 4);
            dom = le32toh(dom);
            typ = d[12];
            if (idx < IWXAB_S156_MAX_REGIONS &&
                (dom == 0 || (dom & domains) != 0)) {
                struct iwxab_s156_region *r = &s->reg[idx];
                uint32_t nl = 0;
                r->used = 1;
                r->index = idx;
                r->raw_id = raw_id;
                r->type = typ;
                r->sub_type = d[13];
                while (nl < 32 && d[16 + nl] != 0) {
                    r->name[nl] = (char)d[16 + nl];
                    nl++;
                }
                r->name[nl] = 0;
                r->name_len = nl;
                /* the union, per type (fw/api/dbg-tlv.h:157-199) */
                if (typ == 2) {                  /* INTERNAL_BUFFER: {alloc_id, base, size} */
                    memcpy(&alloc_id, d + 48, 4);
                    memcpy(&base, d + 52, 4);
                    memcpy(&size, d + 56, 4);
                    r->alloc_id = le32toh(alloc_id);
                    r->base = le32toh(base);
                    r->size = le32toh(size);
                } else if (typ == 3) {           /* DRAM_BUFFER: alloc_id */
                    memcpy(&alloc_id, d + 48, 4);
                    r->alloc_id = le32toh(alloc_id);
                } else if (typ == 17) {          /* SPECIAL_MEM: {u16 type,u16 ver,base,size,off} */
                    memcpy(&base, d + 52, 4);
                    memcpy(&size, d + 56, 4);
                    memcpy(&aoff, d + 60, 4);
                    r->base = le32toh(base);
                    r->size = le32toh(size);
                    r->offset = le32toh(aoff);
                } else if (typ == 6 || typ == 7) { /* err_table: {ver, base, size, offset} */
                    memcpy(&base, d + 52, 4);
                    memcpy(&size, d + 56, 4);
                    memcpy(&aoff, d + 60, 4);
                    r->base = le32toh(base);
                    r->size = le32toh(size);
                    r->offset = le32toh(aoff);
                } else {                          /* DEVICE_MEMORY & friends: dev_addr{size,off} */
                    memcpy(&size, d + 48, 4);
                    memcpy(&aoff, d + 52, 4);
                    r->size = le32toh(size);
                    r->offset = le32toh(aoff);
                    if (len >= 68) {             /* addrs[]: u32 ADDRESSES, one per chunk */
                        memcpy(&base, d + 64, 4);
                        r->base = le32toh(base);
                    }
                }
                s->n_regions++;
            }
        } else if (type == IWX_UCODE_TLV_TYPE_TRIGGERS && len >= 52) {   /* MEASURED: this image's */
            /* trigger TLVs are 52 or 56 bytes -- a >=64 gate silently rejected ALL 26 of them */
            const uint8_t *d = b + off + 8;
            uint32_t dom, tp, reason, policy;
            uint64_t mask;
            memcpy(&dom, d + 4, 4);
            dom = le32toh(dom);
            memcpy(&tp, d + 8, 4);
            tp = le32toh(tp);
            if ((dom == 0 || (dom & domains) != 0) && tp == 9 &&
                s->n_trig < IWXAB_S156_MAX_TP9) {
                struct iwxab_s156_trig *t = &s->trig[s->n_trig];
                memcpy(&reason, d + 12, 4);
                memcpy(&policy, d + 16, 4);
                memcpy(&mask, d + 44, 8);        /* regions_mask, __le64 */
                t->used = 1;
                t->off = (uint32_t)off;
                t->tp = tp;
                t->reason = le32toh(reason);
                t->policy = le32toh(policy);
                t->mask = le64toh(mask);
                t->n_regions = 0;
                {
                    int i;
                    for (i = 0; i < 64; i++)
                        if ((t->mask >> i) & 1)
                            t->n_regions++;
                }
                s->n_trig++;
            }
        }
        off += 8 + (((size_t)len + 3) & ~(size_t)3);
    }
}

/* write one INI-shaped record into the host dump buffer; returns bytes written or 0 if full */
static uint32_t
iwxabS156Record(uint32_t off, const struct iwxab_s156_res *r, const uint8_t *data, uint32_t len)
{
    struct { uint32_t magic, index, type, addr, size, bytes, name_len; }
        __attribute__((packed)) h;
    uint32_t need = (uint32_t)sizeof(h) + 32 + len;
    uint8_t *p;

    if (off + need > IWXAB_S156_DUMP_CAP)
        return 0;
    h.magic = IWXAB_S156_REC_MAGIC;
    h.index = r->index;
    h.type = r->type;
    h.addr = r->addr;
    h.size = r->size;
    h.bytes = len;
    h.name_len = (uint32_t)strlen(r->name);
    memcpy(iwxab_s156_dump + off, &h, sizeof(h));
    off += (uint32_t)sizeof(h);
    memset(iwxab_s156_dump + off, 0, 32);
    memcpy(iwxab_s156_dump + off, r->name, h.name_len > 32 ? 32 : h.name_len);
    off += 32;
    if (len)
        memcpy(iwxab_s156_dump + off, data, len);
    off += len;
    iwxab_s156.dump_recs++;
    return need;
}

/*
 * THE TIME POINT.  One shot, at the known-healthy instant after ALIVE.  For every region the image's
 * own USER_TRIGGER names: read it the way Linux's per-type iterator does, then write the record.
 */
static void
iwxabS156Trigger(ItlIwx *self, struct iwx_softc *sc)
{
    struct iwxab_s156_state *s = &iwxab_s156;
    uint8_t *tmp = iwxab_s156_tmp;      /* BSS, not the stack: see the declaration */
    uint32_t off = 0, ti, bit;

    if (!s->scanned || s->n_trig == 0)
        return;
    s->arm_fired_before_trigger = (iwxab_s150.armed != 0);
    s->fired++;
    s->n_res = 0;
    s->dump_recs = 0;
    s->dump_bytes = 0;
    s->dump_namehits = 0;
    s->dump_valid = 0;
    memset(iwxab_s156_dump, 0, sizeof(iwxab_s156_dump));

    for (ti = 0; ti < s->n_trig; ti++) {
        struct iwxab_s156_trig *t = &s->trig[ti];
        for (bit = 0; bit < 64; bit++) {
            struct iwxab_s156_region *r;
            struct iwxab_s156_res *res;
            uint32_t n, words, got = 0, k, nz = 0;
            int rc = 0;

            if (!((t->mask >> bit) & 1))
                continue;
            if (s->n_res >= IWXAB_S156_MAX_RES || bit >= IWXAB_S156_MAX_REGIONS)
                continue;
            r = &s->reg[bit];
            if (!r->used)
                continue;                    /* the trigger names an id with no REGION TLV */
            res = &s->res[s->n_res];
            memset(res, 0, sizeof(*res));
            res->index = r->index;
            res->type = r->type;
            memcpy(res->name, r->name, sizeof(res->name));
            res->size = r->size;

            n = r->size;
            if (n > IWXAB_S156_READ_CAP)
                n = IWXAB_S156_READ_CAP;     /* THE CAP, stated: the TLV size is in res->size */
            n &= ~3u;                        /* dword reads */
            words = n / 4;

            switch (r->type) {
            case 2:                          /* INTERNAL_BUFFER: read at base_addr (smem) */
                res->addr = r->base + r->offset;
                if (words) {
                    rc = self->iwx_read_mem(sc, res->addr, tmp, (int)words);
                    if (rc == 0) got = n;
                }
                break;
            case 17:                         /* SPECIAL_MEM: base_addr + offset */
            case 6:
            case 7:                          /* err tables: base_addr + offset */
                res->addr = r->base + r->offset;
                if (words) {
                    rc = self->iwx_read_mem(sc, res->addr, tmp, (int)words);
                    if (rc == 0) got = n;
                }
                break;
            case 9:                          /* DEVICE_MEMORY: addrs[0] + offset */
                res->addr = r->base + r->offset;
                if (words) {
                    rc = self->iwx_read_mem(sc, res->addr, tmp, (int)words);
                    if (rc == 0) got = n;
                }
                break;
            case 3:                          /* DRAM_BUFFER: the driver OWNS these */
                if (r->alloc_id == 1 && sc->fw_mon.vaddr != NULL) {
                    /* S157 ONE-LINER 1: a DRAM region's TLV carries only alloc_id; the SIZE lives
                     * in the allocation the driver owns.  Using the TLV's `size` here made
                     * `monitor` read 0 bytes in S156. */
                    /* S158 ONE-LINER (measurement integrity): the LENGTH was clamped to the
                     * TLV's size (0) UPSTREAM, so raising only the cap changed nothing in S157.
                     * Set n here, where the clamp actually happens.  THIS CANNOT AFFECT WHAT THE
                     * FIRMWARE DOES: it only decides how many bytes the DRIVER READS from a buffer
                     * the driver already owns. */
                    uint32_t avail = (uint32_t)sc->fw_mon.size;
                    if (r->size != 0 && r->size < avail)
                        avail = r->size;
                    /* S159 ONE-LINER, PROPERLY: this must be an ASSIGNMENT.  S157 raised the cap
                     * (a no-op because n was already 0); S158 added a REDUCTION (`if (n > avail)`),
                     * which also cannot raise zero.  A reduction can only lower; the DRAM region
                     * carries no size in its TLV, so the length must be SET here.  This sizes a READ
                     * of a buffer the driver already owns: IT CANNOT AFFECT WHAT THE FIRMWARE DOES. */
                    n = avail & ~3u;
                    if (n > IWXAB_S156_READ_CAP)
                        n = IWXAB_S156_READ_CAP;
                    if (n > avail)
                        n = avail & ~3u;
                    memcpy(tmp, sc->fw_mon.vaddr, n);
                    res->addr = (uint32_t)(sc->fw_mon.paddr & 0xffffffffULL);
                    got = n;
                    rc = 0;
                } else {
                    rc = -2;             /* alloc_id 2..4: this port never allocated them */
                }
                break;
            default:
                rc = -3;                 /* a region type this round does not implement */
                break;
            }
            res->rc = rc;
            res->bytes = got;
            for (k = 0; k + 4 <= got; k += 4) {
                uint32_t v;
                memcpy(&v, tmp + k, 4);
                if (v != 0) {
                    if (nz == 0) res->d0 = v;
                    else if (nz == 1) res->d1 = v;
                    else if (nz == 2) res->d2 = v;
                    else if (nz == 3) res->d3 = v;
                    nz++;
                }
            }
            res->nz = nz;
            s->n_res++;
            if (got) {
                uint32_t w = iwxabS156Record(off, res, tmp, got);
                if (w)
                    off += w;
            }
        }
    }
    s->dump_bytes = off;
    s->dump_valid = (off != 0);
    /* how many of the IMAGE's region names the dump carries -- OUR OWN WRITES, see the banner. */
    /* S157 ONE-LINER 2: the name count is the RECORD count BY CONSTRUCTION.  The S156 scan
     * counted substrings, and `monitor` is a substring of `monitor_smem` -- it reported 4 for 3
     * records.  A record is written only for a region that was read, so this is exact. */
    s->dump_namehits = s->dump_recs;
    XYLog("PROBE S156 timepoint APPLIED tp=9 user_trigger fired=%u trigs=%u regions_read=%u "
          "dump_bytes=%u recs=%u namehits=%u arm_first=%u\n",
          s->fired, s->n_trig, s->n_res, s->dump_bytes, s->dump_recs, s->dump_namehits,
          s->arm_fired_before_trigger);
}

static void
iwxabS156Publish(struct iwx_softc *sc, const char *why, int logit)
{
    struct iwxab_s156_state *s = &iwxab_s156;
    char *p = iwxab_s156_str;
    size_t left = sizeof(iwxab_s156_str);
    uint32_t i;
    int n;
    OSString *os;

    if (sc == NULL)
        return;
    n = snprintf(p, left, "S156 why=%s scanned=%u regions=%u trigs=%u fired=%u "
                          "read=%u dump_bytes=%u recs=%u namehits=%u arm_first=%u[mask=%016llx]",
                 why, s->scanned, s->n_regions, s->n_trig, s->fired,
                 s->n_res, s->dump_bytes, s->dump_recs, s->dump_namehits,
                 s->arm_fired_before_trigger,
                 (unsigned long long)(s->n_trig ? s->trig[0].mask : 0ULL));
    if (n < 0)
        return;
    p += n;
    left = left > (size_t)n ? left - (size_t)n : 0;
    for (i = 0; i < s->n_res && left > 96; i++) {
        n = snprintf(p, left, " [%u:%s:t%u:rc%d:b%u:a%08x:nz%u:%08x,%08x,%08x,%08x]",
                     s->res[i].index, s->res[i].name, s->res[i].type, s->res[i].rc,
                     s->res[i].bytes, s->res[i].addr, s->res[i].nz,
                     s->res[i].d0, s->res[i].d1, s->res[i].d2, s->res[i].d3);
        if (n < 0)
            break;
        p += n;
        left = left > (size_t)n ? left - (size_t)n : 0;
    }
    if (sc->sc_pcitag != NULL) {
        os = OSString::withCString(iwxab_s156_str);
        if (os != NULL) {
            sc->sc_pcitag->setProperty("iwxctl_s156", os);
            os->release();
        }
    }
    if (logit)
        XYLog("PROBE %s\n", iwxab_s156_str);
}
/* ==== S156 DIAGNOSTIC END ==================================================================== */


/* ==== S157 DIAGNOSTIC BEGIN ==================================================================
 * *** PERIODIC TIME POINT + HISTORY RING: THE DELTA ACROSS AWAKE -> HELD, WITHOUT PREDICTING IT. ***
 *
 * WHY THIS IS THE RIGHT INSTRUMENT FOR THE DEFECT
 *   The image names its own dump regions and they are debug buffers and platform state, so ONE dump
 *   says what the device holds; TWO dumps ACROSS A TRANSITION say what CHANGED.  The image's tp=9
 *   USER_TRIGGER is reachable at will (S156), so the driver does not have to predict when the
 *   failure starts -- it samples on a timer and the transition is captured wherever it falls.
 *
 * WHAT IS COMPARED, AND WHY IT IS NOT RAW ADDRESSES (row zero, measured)
 *   The collector's 12-byte records are {tag, 0xeea20782, advancing}.  *** THE ADVANCING FIELD IS
 *   OUTSIDE ALL 71 DECLARED SECTIONS (row0/s157-section-map.txt: 9 of 9 observed values), so it is
 *   NOT a code address *** -- an address-set delta is therefore not available from this stream, and
 *   claiming one would be an assumption.  What IS available, and is snapshotted per record:
 *     (a) the RECORD-TYPE (tag) HISTOGRAM -- the small values that ride with 0xeea20782;
 *     (b) the RATE at which the counter advances (first..last across the window), which measures
 *         firmware ACTIVITY directly;
 *     (c) the collected REGIONS' first dwords and rc mask (device state, S156).
 *   The awake-vs-awake control is the SAME comparison between two AWAKE snapshots -- without it a
 *   "delta across the hold" would include ordinary churn and mean nothing.
 * ============================================================================ */

static void
iwxabS157Tick(ItlIwx *self, struct iwx_softc *sc, uint32_t tick)
{
    struct iwxab_s157_state *r = &iwxab_s157;
    struct iwxab_s157_snap *s;
    uint32_t i, k, nz2 = 0, nz64 = 0, cnt_n = 0, first = 0, last = 0;

    r->pn++;
    if (r->period == 0)
        r->period = IWXAB_S157_PERIOD;
    if ((r->pn % IWXAB_S157_PERIOD) != 0)
        return;

    /* THE TIME POINT, AGAIN -- the S156 collector, unmodified. */
    iwxabS156Trigger(self, sc);

    s = &r->s[r->head];
    memset(s, 0, sizeof(*s));
    s->ord = ++r->ord;
    s->tick = tick;
    r->n++;

    /* the DBGC1 census at the same instant (host memory reads only) */
    if (sc->fw_mon.vaddr != NULL && sc->fw_mon.size >= 4) {
        const uint32_t *p = (const uint32_t *)sc->fw_mon.vaddr;
        uint32_t lim = (uint32_t)(sc->fw_mon.size / 4);
        uint32_t n2 = lim > 2048 ? 2048 : lim;
        uint32_t n64 = lim > 16384 ? 16384 : lim;
        for (i = 0; i < n2; i++)
            if (p[i] != 0)
                nz2++;
        for (i = 0; i < n64; i++)
            if (p[i] != 0)
                nz64++;
        s->nz2048 = nz2;
        s->nz64k = nz64;
        /* ==== S159: THE DISCRIMINATOR.  Compare THIS read with the PREVIOUS one, in the window the
         * census uses (first 64 KiB).  The question the round asks is not "did the vocabulary change
         * across the transition" but "is the window STILL BEING WRITTEN while the interface is held":
         * any changed dword proves a live writer; zero changed dwords means what we read is static
         * and (ii) -- an unreadable/frozen window -- cannot be excluded, so §157's delta would be an
         * artefact.  The fill counts are the second half: 0xc5c5c5c5 is a classic debug-fill value,
         * and if the window HOLDS a fill pattern that is a different thing from a live mix. */
        {
            struct iwxab_s159_disc *d = &iwxab_s159;
            uint32_t k2, lim = (uint32_t)(sc->fw_mon.size / 4);
            if (lim > IWXAB_S159_WIN)
                lim = IWXAB_S159_WIN;
            d->chg4k = d->chg64k = d->c5 = d->c45 = 0;
            for (k2 = 0; k2 < lim; k2++) {
                uint32_t v = p[k2];
                if (v == 0xc5c5c5c5u)
                    d->c5++;
                if (v == 0x45c5c5c5u)
                    d->c45++;
                if (iwxab_s159_prev_valid && iwxab_s159_prev[k2] != v) {
                    d->chg64k++;
                    if (k2 < 1024)
                        d->chg4k++;
                }
                iwxab_s159_prev[k2] = v;
            }
            iwxab_s159_prev_valid = 1;
            s->chg4k = d->chg4k;
            s->chg64k = d->chg64k;
        }
        /* the record structure: the CONSTANT 0xeea20782 marks a record; the dword AFTER it is the
         * advancing counter and the dword BEFORE it is the record type.  Phase-independent. */
        for (i = 0; i + 1 < n64; i++) {
            if (p[i] == 0xeea20782u) {
                uint32_t ctr = p[i + 1];
                uint32_t tag = (i > 0) ? p[i - 1] : 0;
                cnt_n++;
                if (cnt_n == 1)
                    first = ctr;
                last = ctr;
                /* a tiny histogram of the record-type values, 8 slots */
                {
                    uint32_t j, hit = 0;
                    for (j = 0; j < s->n_tag; j++) {
                        if (s->tag_val[j] == tag) {
                            s->tag_cnt[j]++;
                            hit = 1;
                            break;
                        }
                    }
                    if (!hit && s->n_tag < IWXAB_S157_TAGS) {
                        s->tag_val[s->n_tag] = tag;
                        s->tag_cnt[s->n_tag] = 1;
                        s->n_tag++;
                    }
                }
            }
        }
    }
    s->cnt_n = cnt_n;
    s->cnt_first = first;
    s->cnt_last = last;

    /* the collected regions, compactly (rc mask + first two dwords + bytes) */
    s->n_reg = 0;
    for (k = 0; k < iwxab_s156.n_res && k < IWXAB_S157_MAXREG; k++) {
        s->reg_idx[k] = iwxab_s156.res[k].index;
        s->reg_rc[k] = (uint32_t)iwxab_s156.res[k].rc;
        s->reg_bytes[k] = iwxab_s156.res[k].bytes;
        s->reg_d0[k] = iwxab_s156.res[k].d0;
        s->reg_d1[k] = iwxab_s156.res[k].d1;
        if (iwxab_s156.res[k].rc == 0)
            s->rc_mask |= (1u << k);
        s->n_reg++;
    }

    r->armed_seen = iwxab_s150.armed;
    /* 0pd: the ring holds the NEWEST; a snapshot that does not fit is LOST and COUNTED. */
    r->head = (r->head + 1) % IWXAB_S157_RING;
    if (r->n > IWXAB_S157_RING)
        r->lost = r->n - IWXAB_S157_RING;
}

static void
iwxabS157Publish(struct iwx_softc *sc, const char *why, int logit)
{
    struct iwxab_s157_state *r = &iwxab_s157;
    char *p = iwxab_s157_str;
    size_t left = sizeof(iwxab_s157_str);
    uint32_t k, n;
    int w;
    OSString *os;

    if (sc == NULL)
        return;
    w = snprintf(p, left, "S157 why=%s pn=%u ord=%u lost=%u n=%u armed=%u",
                 why, r->pn, r->ord, r->lost, r->n, r->armed_seen);
    if (w < 0)
        return;
    p += w;
    left = left > (size_t)w ? left - (size_t)w : 0;
    /* the NEWEST four snapshots, oldest first, so a delta is readable in one property */
    for (k = 0; k < 4 && left > 150; k++) {
        uint32_t slot;
        struct iwxab_s157_snap *s;
        uint32_t idx = (r->n < 4) ? k : (r->n - 4 + k);
        if (r->n == 0 || idx >= r->n)
            continue;
        slot = (r->head + IWXAB_S157_RING - (r->n - idx)) % IWXAB_S157_RING;
        s = &r->s[slot];
        w = snprintf(p, left, " |%u:t%u:nz%u/%u:cnt%u:%x..%x:chg%u/%u:c5=%u,%u:tags",
                     s->ord, s->tick, s->nz2048, s->nz64k, s->cnt_n,
                     s->cnt_first, s->cnt_last, s->chg4k, s->chg64k, iwxab_s159.c5, iwxab_s159.c45);
        if (w < 0)
            break;
        p += w;
        left = left > (size_t)w ? left - (size_t)w : 0;
        for (n = 0; n < s->n_tag && left > 32; n++) {
            w = snprintf(p, left, "%x=%u,", s->tag_val[n], s->tag_cnt[n]);
            if (w < 0)
                break;
            p += w;
            left = left > (size_t)w ? left - (size_t)w : 0;
        }
        w = snprintf(p, left, ":rc%x:r", s->rc_mask);
        if (w < 0)
            break;
        p += w;
        left = left > (size_t)w ? left - (size_t)w : 0;
        for (n = 0; n < s->n_reg && left > 40; n++) {
            w = snprintf(p, left, "%u/%d/%u:%08x,%08x,", s->reg_idx[n], (int)s->reg_rc[n],
                         s->reg_bytes[n], s->reg_d0[n], s->reg_d1[n]);
            if (w < 0)
                break;
            p += w;
            left = left > (size_t)w ? left - (size_t)w : 0;
        }
    }
    if (sc->sc_pcitag != NULL) {
        os = OSString::withCString(iwxab_s157_str);
        if (os != NULL) {
            sc->sc_pcitag->setProperty("iwxctl_s157", os);
            os->release();
        }
    }
    if (logit)
        XYLog("PROBE %s\n", iwxab_s157_str);
}
/* ==== S157 DIAGNOSTIC END ==================================================================== */


/* ==== S158 DIAGNOSTIC BEGIN ==================================================================
 * *** THE HE GATE, AS A MEASUREMENT OF THE DRIVER'S OWN NODE, AND THE FIELD DERIVED FROM IT. ***
 * The gate question is not "what does Linux send" but "what IS this link": if the net80211 node
 * has HE negotiated, `he_support = 0` is a FALSE statement about the link; if it does not, zero is
 * the true statement and Linux would send zero too.  So the same derivation that fixes the field
 * also ANSWERS THE GATE, and the publication below prints the node's state so the answer is read,
 * not inferred.
 * ============================================================================ */
static void
iwxabS158Publish(struct iwx_softc *sc, const char *why, int logit)
{
    struct iwxab_s158_state *g = &iwxab_s158;
    struct ieee80211com *ic = (sc != NULL) ? &sc->sc_ic : NULL;
    OSString *os;

    if (sc == NULL)
        return;
    if (ic != NULL) {
        g->heon = (ic->ic_flags & IEEE80211_F_HEON) ? 1 : 0;
        g->modecaps = ic->ic_modecaps;
        g->cap0 = ic->ic_he_cap_elem.mac_cap_info[0];
    }
    snprintf(iwxab_s158_str, sizeof(iwxab_s158_str),
             "S158 why=%s gate_ran=%u cmds=%u ***NODE_HE=%u*** ni_flags=0x%08x heon=%u "
             "modecaps=0x%08x(11axbit=%u) cap0=0x%02x ***WIRE_he_support=%u***",
             why, g->vi, g->n, g->he, g->ni_flags, g->heon, g->modecaps,
             (g->modecaps & (1u << IEEE80211_MODE_11AX)) ? 1u : 0u, g->cap0, g->wgen_last);
    if (sc->sc_pcitag != NULL) {
        os = OSString::withCString(iwxab_s158_str);
        if (os != NULL) {
            sc->sc_pcitag->setProperty("iwxctl_s158", os);
            os->release();
        }
    }
    if (logit)
        XYLog("PROBE %s\n", iwxab_s158_str);
}
/* ==== S158 DIAGNOSTIC END ==================================================================== */


/* ==== S162 PUBLISH ==========================================================================
 * The read-out of the firmware reset handshake, as ONE line: attempts, completions, timeouts,
 * unsolicited bit-2 sightings, the elapsed microseconds of EVERY attempt (a bounded ring, newest
 * last, as `<n>/<result>/<us>`), and the LAST attempt's cause registers and mask values.
 * Refreshed from the 1 Hz watchdog (thread context, host memory only, no register, no lock) and
 * at the end of every handshake.  `0b` reads this property BY VALUE on the RUNNING build before
 * the install (MUST be absent) and after (MUST be present), and the pre-registered branch reads
 * `hs_att`/`hs_ok`/`hs_to` from it.
 * ============================================================================ */
static void
iwxabS162Publish(struct iwx_softc *sc, const char *why, int logit)
{
    struct iwxab_s162_state *h = &iwxab_s162;
    OSString *os;
    char ev[240];
    size_t off = 0;
    uint32_t i, first;

    if (sc == NULL)
        return;

    /* THE PER-ATTEMPT LIST.  Oldest first, capped at the ring size; the attempt number is
     * 1-based and is printed so a gap or a wrap is visible rather than inferred. */
    ev[0] = '\0';
    first = (h->attempts > IWXAB_S162_EVENTS) ? (h->attempts - IWXAB_S162_EVENTS) : 0;
    for (i = first; i < h->attempts && off < sizeof(ev) - 32; i++) {
        int w = snprintf(ev + off, sizeof(ev) - off, "%s%u/%u/%u",
                         (i == first) ? "" : ",",
                         i + 1u,
                         (unsigned)h->ev_result[i % IWXAB_S162_EVENTS],
                         h->ev_us[i % IWXAB_S162_EVENTS]);
        if (w < 0)
            break;
        off += (size_t)w;
    }

    snprintf(iwxab_s162_str, sizeof(iwxab_s162_str),
             "S162 why=%s hs_att=%u hs_ok=%u hs_to=%u hs_unsol=%u hs_last_result=%u "
             "hs_last_us=%u hs_max_us=%u hs_sleeps=%u hs_pre=0x%08x hs_clear=0x%08x "
             "hs_post=0x%08x hs_stale=%u hs_mask=0x%08x hs_win=0x%08x hs_state=%d hs_ev=%s "
             "hs_skip=%u hs_skip_dead=%u hs_skip_capa=%u hs_skip_ver=%u hs_skip_nostart=%u "
             "hs_alive=%d hs_major=%u hs_capa=%u",
             why, h->attempts, h->ok, h->timeouts, h->unsol, h->last_result,
             h->last_us, h->last_us_max, h->last_sleeps, h->last_pre, h->last_clear,
             h->last_post, h->last_stale, h->last_mask, h->last_winmask,
             sc->sc_fw_reset_state, ev,
             h->skipped, h->skip_dead, h->skip_capa, h->skip_ver, h->skip_nostart,
             sc->sc_fw_started,
             (unsigned)sc->sc_ucode_major,
             (unsigned)(isset(sc->sc_enabled_capa,
                              IWX_UCODE_TLV_CAPA_FW_RESET_HANDSHAKE) ? 1 : 0));

    if (sc->sc_pcitag != NULL) {
        os = OSString::withCString(iwxab_s162_str);
        if (os != NULL) {
            sc->sc_pcitag->setProperty("iwxctl_s162", os);
            os->release();
        }
    }
    if (logit)
        XYLog("PROBE %s\n", iwxab_s162_str);
}
/* ==== S162 PUBLISH END ====================================================================== */

/* ==== S164: THE LIVENESS WITNESS AND THE AT-HALT CAPTURE -- IMPLEMENTATION ===================
 * *** A CAPTURE THAT RUNS AFTER THE RESET IS NO CAPTURE AT ALL, SO THE ORDER IS PART OF THE
 * INSTRUMENT: BAR0 (LOCK-FREE) -> PUBLISH -> ERROR TABLES (BOUNDED LOCK) -> PUBLISH. ***
 *
 * THE READ TABLE (0q21 -- THE ACCESSOR AND THE WINDOW FOR EVERY READ):
 *   what                              address          accessor                window
 *   MSIX_HW_INT_CAUSES_AD             0x2808 BAR0      IWX_READ ->             NONE: lock-free
 *   MSIX_HW_INT_MASK_AD               0x280c BAR0      iwxabS90Rd ->           (bus_space_read_4,
 *   MSIX_FH_INT_CAUSES_AD             0x2800 BAR0      bus_space_read_4        no nic lock,
 *   MSIX_FH_INT_MASK_AD               0x2804 BAR0                              no prph)
 *   GP_CNTRL                          0x0024 BAR0
 *   IPC_STATE  (OURS, see the reg)    0x0110 BAR0
 *   RESET                             0x0020 BAR0
 *   HW_IF_CONFIG_REG                  0x0000 BAR0
 *   INT / INT_MASK / FH_INT_STATUS    0x0008 / 0x000c / 0x0010 BAR0
 *   LMAC error event table            RUNTIME          iwx_read_mem ->         NIC LOCK TAKEN,
 *   UMAC error event table            RUNTIME          iwx_nic_lock            BOUNDED: 150 ms
 *                                                                             access poll, and the
 *                                                                             0xa5a5a5aX sentinel
 *                                                                             returns EIO after 5
 *                                                                             consecutive words; the
 *                                                                             elapsed us of each read
 *                                                                             is published.  EIO IS
 *                                                                             A DATUM, NOT A STOP.
 *   rb_stts (sc->rxq.stat)            HOST DMA         plain load              no device access
 * *** THE FIVE FORBIDDEN ADDRESSES ARE NEVER READ. ***  They appear in this file ONLY as the
 * comparison constants `iwxab_s164_forbidden[]`, and the runtime guard below compares the
 * error-table bases against them and SKIPS the read on equality (the bases are TLV-derived at
 * runtime, so a compile-time check alone cannot enforce the rule).
 * ============================================================================ */
static const uint32_t iwxab_s164_forbidden[5] = {
    0xa01028, 0xd00d0138, 0xac20f4, 0xd00d0128, 0xa5cffc
};

static int
iwxabS164Forbidden(uint32_t addr)
{
    int i;

    for (i = 0; i < 5; i++) {
        if (addr == iwxab_s164_forbidden[i])
            return 1;
    }
    return 0;
}

static uint32_t
iwxabS164DeltaMs(uint64_t from, uint64_t to)
{
    if (to <= from)
        return 0;
    return (uint32_t)((to - from) / 1000000ULL);
}

/* THE WITNESS.  Called from the 100 ms timer callback ONLY (iwxabS103azTimerCB), so its cadence
 * is the proven one and it cannot be silenced by the network stack.  0pd: every tick that is
 * skipped by the up gate RE-BASELINES, so a down interface is never counted as a stall. */
static void
iwxabS164WitnessTick(struct iwx_softc *sc)
{
    struct iwxab_s164_state *h = &iwxab_s164;
    struct _ifnet *ifp;
    uint32_t nf, up;
    uint64_t now;

    if (sc == NULL || sc->sc_pcitag == NULL)
        return;
    ifp = &sc->sc_ic.ic_if;
    h->tick_n++;
    now = mach_absolute_time();

    /* THE UP GATE IS DECLARED, NOT ASSUMED: interface running AND the firmware started AND
     * having spoken (`uc_intr` is the ALIVE notification -- without it a silent filter is not
     * evidence of anything).  The station's RUN state is a separate condition on the CAPTURE,
     * below, because only an ASSOCIATED link carries the ~10 beacons/s that make a 1 s silence
     * pathological; a scan pause must not consume a capture. */
    up = (((ifp->if_flags & IFF_RUNNING) != 0) && sc->sc_uc.uc_ok != 0 &&
          sc->sc_uc.uc_intr != 0) ? 1u : 0u;
    if (!up) {
        h->last_nf = IWX_PROBE_INTR_COUNT;
        h->last_adv_t = now;
        return;
    }
    h->up_ticks++;
    nf = IWX_PROBE_INTR_COUNT;
    if (nf != h->last_nf) {
        uint32_t gap, d;
        struct iwxab_s164_gap *g;

        if (h->primed == 0) {
            /* THE FIRST ADVANCE IS NOT A GAP: it is the arming event.  Recording it would put a
             * boot-long interval into the justification histogram and make the threshold look
             * better than it is. */
            h->primed = 1;
            h->armed = 1;
            h->last_nf = nf;
            h->last_adv_t = now;
            return;
        }
        gap = iwxabS164DeltaMs(h->last_adv_t, now);
        d = nf - h->last_nf;
        g = &h->ring[h->ring_n % IWXAB_S164_RING];
        g->delta = d;
        g->ms = gap;
        h->ring_n++;
        h->advances++;
        h->dlast = d;
        if (gap > h->gap_max_ms)
            h->gap_max_ms = gap;
        if (gap >= 250)
            h->g250++;
        if (gap >= 500)
            h->g500++;
        if (gap >= 1000)
            h->g1s++;
        h->armed = 1;
        h->last_adv_t = now;
        h->last_nf = nf;
        /* A NEW ADVANCE IS THE ONLY THING THAT RE-ARMS THE CAPTURE: one stall produces one
         * capture, however long it lasts. */
        h->cap_pending = 0;
        iwxab_s218_stall_pending = 0;
        return;
    }
    if (h->armed != 0 && h->cap_pending == 0 &&
        sc->sc_ic.ic_state >= IEEE80211_S_RUN) {
        uint32_t el = iwxabS164DeltaMs(h->last_adv_t, now);
        if (el > h->zmax_ms)
            h->zmax_ms = el;
        if (el >= IWXAB_S164_THRESH_MS) {
            if (!h->cap_full)
                iwxabS164Capture(sc, el);
            if (!iwxab_s218_stall_pending) {
                iwxab_s218_stall_pending = 1;
                iwxabS218Capture(sc, IWXAB_S218_TAG_STALL, 0);
            }
        }
    }
}

/* THE CAPTURE.  Read-only.  Stage 1 is lock-free BAR0; stage 1 is PUBLISHED before stage 2 takes
 * the NIC lock.  Nothing here writes a device register. */
static void
iwxabS164Capture(struct iwx_softc *sc, uint32_t elapsed_ms)
{
    struct iwxab_s164_state *h = &iwxab_s164;
    ItlIwx *that = container_of(sc, ItlIwx, com);
    uint32_t buf[IWXAB_S164_ET_DWORDS];
    uint64_t t0, t1;
    uint32_t rst0;
    int i, rc;

    if (sc == NULL)
        return;
    rst0 = h->rst_seq;
    h->cap_n++;
    h->cap_pending = 1;
    h->cap_t = mach_absolute_time();
    h->cap_elapsed_ms = elapsed_ms;
    h->cap_race = 0;
    h->cap_nf = IWX_PROBE_INTR_COUNT;
    if (h->cap_n >= IWXAB_S164_CAP_MAX)
        h->cap_full = 1;

    /* ---------------- STAGE 1: BAR0, IN THE BRIEF'S ORDER, ALL LOCK-FREE ---------------- */
    h->r_hwc  = IWX_READ(sc, IWX_CSR_MSIX_HW_INT_CAUSES_AD);   /* 0x2808 */
    h->r_hwm  = IWX_READ(sc, IWX_CSR_MSIX_HW_INT_MASK_AD);     /* 0x280c */
    h->r_fhc  = IWX_READ(sc, IWX_CSR_MSIX_FH_INT_CAUSES_AD);   /* 0x2800 */
    h->r_fhm  = IWX_READ(sc, IWX_CSR_MSIX_FH_INT_MASK_AD);     /* 0x2804 */
    h->r_gp   = IWX_READ(sc, IWX_CSR_GP_CNTRL);                /* 0x0024, BEFORE any lock */
    h->r_ipc  = IWX_READ(sc, IWX_CSR_IPC_STATE);               /* 0x0110, OURS (Bz: Linux
                                                                * hardcodes SW_READY)   */
    h->r_rst  = IWX_READ(sc, IWX_CSR_RESET);                   /* 0x0020 */
    h->r_hif  = IWX_READ(sc, IWX_CSR_HW_IF_CONFIG_REG);        /* 0x0000 */
    h->r_int  = IWX_READ(sc, IWX_CSR_INT);                     /* 0x0008 */
    h->r_intm = IWX_READ(sc, IWX_CSR_INT_MASK);                /* 0x000c */
    h->r_fhs  = IWX_READ(sc, IWX_CSR_FH_INT_STATUS);           /* 0x0010 */
    if (sc->rxq.stat != NULL)
        h->r_rb = (uint32_t)(*(volatile uint16_t *)sc->rxq.stat) &
                  (IWX_RX_MQ_RING_COUNT - 1);
    else
        h->r_rb = 0xffff;
    h->r_cur = (uint32_t)sc->rxq.cur;
    if (h->cap_n == 1) {
        h->first_el_ms = elapsed_ms;
        h->first_hwc = h->r_hwc;
        h->first_gp  = h->r_gp;
        h->first_ipc = h->r_ipc;
        h->first_rst = h->r_rst;
    }

    /* PUBLISH A -- THE BAR0 STATE IS OUT BEFORE THE NIC LOCK IS TAKEN.  This is the half that
     * cannot be delayed by the lock-taking error-table read. */
    iwxabS164Publish(sc, "bar", 0);

    /* ---------------- STAGE 2: THE ERROR TABLES, BOUNDED, EIO AS A DATUM ---------------- */
    h->et_lmac = sc->sc_uc.uc_lmac_error_event_table[0];
    h->et_umac = sc->sc_uc.uc_umac_error_event_table;
    h->et_lmac_rc = -1;
    h->et_umac_rc = -1;
    h->et_lmac_us = 0;
    h->et_umac_us = 0;
    h->et_lmac_w0 = 0xdeadbeef;
    h->et_lmac_w1 = 0xdeadbeef;
    h->et_umac_w0 = 0xdeadbeef;
    h->et_umac_w1 = 0xdeadbeef;
    h->et_skip = 0;

    if (sc->sc_fw_reset_state == IWX_FW_RESET_REQUESTED) {
        /* THE ONE COLLISION THIS BLOCK COULD CAUSE, REFUSED BY CONSTRUCTION: the error-table
         * reads take the NIC lock on THIS thread, and this thread is the HAL workloop that the
         * reset handshake's ACK is delivered on.  A ~300 ms capture inside the handshake's
         * 200 ms bound could turn its success into a timeout -- a measurement changing the thing
         * it measures.  So when a handshake is IN FLIGHT the tables are SKIPPED and the skip is
         * published (rc=-4), while the BAR0 state above is already out. */
        h->et_lmac_rc = -4;
    } else if (h->et_lmac == 0) {
        h->et_lmac_rc = -2;             /* no address: the TLV did not provide one          */
    } else if (iwxabS164Forbidden(h->et_lmac)) {
        h->et_skip |= 1;                /* FORBIDDEN ADDRESS: DO NOT READ, RECORD THE SKIP    */
        h->et_lmac_rc = -3;
    } else {
        for (i = 0; i < IWXAB_S164_ET_DWORDS; i++)
            buf[i] = 0xdeadbeef;
        t0 = mach_absolute_time();
        rc = that->iwx_read_mem(sc, h->et_lmac, buf, IWXAB_S164_ET_DWORDS);
        t1 = mach_absolute_time();
        h->et_lmac_rc = rc;
        h->et_lmac_us = (uint32_t)((t1 - t0) / 1000ULL);
        h->et_lmac_w0 = buf[0];
        h->et_lmac_w1 = buf[1];
    }
    if (sc->sc_fw_reset_state == IWX_FW_RESET_REQUESTED) {
        h->et_umac_rc = -4;             /* same refusal, second table                        */
    } else if (h->et_umac != 0 && !iwxabS164Forbidden(h->et_umac)) {
        for (i = 0; i < IWXAB_S164_ET_DWORDS; i++)
            buf[i] = 0xdeadbeef;
        t0 = mach_absolute_time();
        rc = that->iwx_read_mem(sc, h->et_umac, buf, IWXAB_S164_ET_DWORDS);
        t1 = mach_absolute_time();
        h->et_umac_rc = rc;
        h->et_umac_us = (uint32_t)((t1 - t0) / 1000ULL);
        h->et_umac_w0 = buf[0];
        h->et_umac_w1 = buf[1];
    } else if (h->et_umac == 0) {
        h->et_umac_rc = -2;
    } else {
        h->et_skip |= 2;
        h->et_umac_rc = -3;
    }

    /* STAGE 3: the handbook-level state AFTER the lock, so the lock's effect on GP_CNTRL is
     * visible (iwx_nic_lock SETS BIT(21) and its unlock clears it) and cannot be mistaken for
     * the device's own state. */
    h->r_gp2 = IWX_READ(sc, IWX_CSR_GP_CNTRL);

    h->cap_race = (h->rst_seq != rst0) ? 1u : 0u;
    /* PUBLISH B -- THE COMPLETE RECEIPT.  The reset ordinal snapshot is in it, and it is taken
     * BEFORE this publish, so `saw_cap` at the reset is the state at that instant. */
    iwxabS164Publish(sc, "cap", 0);
}

/* THE RESET ORDINAL.  Called IMMEDIATELY BEFORE the `SW_RESET` in `iwx_stop_device` -- the only
 * SW_RESET site on Bz -- so the reset itself records whether the capture had been published. */
static void
iwxabS164ResetMark(struct iwx_softc *sc)
{
    struct iwxab_s164_state *h = &iwxab_s164;

    if (sc == NULL)
        return;
    h->rst_t = mach_absolute_time();
    h->rst_saw_bar = h->bar_pub_seq;
    h->rst_saw_cap = h->cap_pub_seq;
    h->rst_seq = h->rst_seq + 1;
    iwxabS164Publish(sc, "rst", 0);
}

/* THE PUBLISHER.  Two channels like the rest of this file: an IOREG property (the read-out that
 * survives a wrapped log) and -- on a capture only -- one XYLog line.  Republished by the 1 Hz
 * watchdog so a capture's page is refreshed with its own completion fields even if the reset
 * never comes.  Reads host memory only. */
static void
iwxabS164Publish(struct iwx_softc *sc, const char *why, int logit)
{
    struct iwxab_s164_state *h = &iwxab_s164;
    OSString *os;
    char ring[200];
    size_t off = 0;
    uint32_t i, first, n;
    uint64_t now;
    int64_t dt_bar = -1, dt_cap = -1;
    const char *ord;

    if (sc == NULL)
        return;

    ring[0] = '\0';
    n = (h->ring_n < IWXAB_S164_RING) ? h->ring_n : IWXAB_S164_RING;
    first = h->ring_n - n;
    for (i = first; i < h->ring_n && off < sizeof(ring) - 24; i++) {
        int w = snprintf(ring + off, sizeof(ring) - off, "%s%u/%u",
                         (i == first) ? "" : ",",
                         (unsigned)h->ring[i % IWXAB_S164_RING].delta,
                         (unsigned)h->ring[i % IWXAB_S164_RING].ms);
        if (w < 0)
            break;
        off += (size_t)w;
    }
    if (h->rst_seq != 0 && h->bar_pub_seq != 0 && h->bar_pub_t <= h->rst_t)
        dt_bar = (int64_t)((h->rst_t - h->bar_pub_t) / 1000000ULL);
    if (h->rst_seq != 0 && h->cap_pub_seq != 0 && h->cap_pub_t <= h->rst_t)
        dt_cap = (int64_t)((h->rst_t - h->cap_pub_t) / 1000000ULL);
    /* THE ORDERING VERDICT.  It is written from MEASUREMENTS only: `saw_cap` is what the reset
     * itself snapshotted at its mark, and `cap_pub_t <= rst_t` is the timestamp comparison.
     * PRE_RESET requires BOTH.  NO_RESET_SINCE_CAP is the honest name for "the only resets in
     * this boot came before the capture" -- it is NOT the P2 failure (a capture that landed
     * after the reset that wiped the state); POST_RESET is. */
    if (h->cap_pub_seq == 0)
        ord = "NO_CAP";
    else if (h->rst_seq == 0)
        ord = "AWAIT_RST";
    else if (h->cap_pub_t <= h->rst_t && h->rst_saw_cap != 0)
        ord = "PRE_RESET";
    else if (h->cap_pub_t > h->rst_t)
        ord = "NO_RESET_SINCE_CAP";
    else
        ord = "POST_RESET";

    snprintf(iwxab_s164_str, sizeof(iwxab_s164_str),
             "S164 why=%s thr_ms=%u ticks=%u up=%u armed=%u st=%d adv=%u dlast=%u "
             "gapmax=%u g250=%u g500=%u g1s=%u zmax=%u ring=%s "
             "| cap=%u full=%u pend=%u el=%u race=%u cap_us=%u nf=%u "
             "first[el=%u hwc=%08x gp=%08x ipc=%08x rst=%08x] "
             "| HWC=%08x HWM=%08x FHC=%08x FHM=%08x "
             "| GP=%08x GPd=clk%u_init%u_req%u_stat%u_bmd%u GP2=%08x "
             "| IPC=%08x IPCrs=%u IPCtop=%u RST=%08x HIF=%08x "
             "INT=%08x INTM=%08x FHS=%08x RB=%u CUR=%u "
             "| ETl=%08x rc=%d us=%u w=%08x,%08x skip=%u "
             "| ETu=%08x rc=%d us=%u w=%08x,%08x skip=%u "
             "| ORD bar_pub=%u cap_pub=%u cap_t_ms=%llu bar_t_ms=%llu cap_pub_ms=%llu "
             "rst=%u rst_t_ms=%llu saw_bar=%u saw_cap=%u dt_bar=%lld dt_cap=%lld order=%s",
             why, (unsigned)IWXAB_S164_THRESH_MS, (unsigned)h->tick_n,
             (unsigned)h->up_ticks, (unsigned)h->armed, (int)sc->sc_ic.ic_state,
             (unsigned)h->advances, (unsigned)h->dlast,
             (unsigned)h->gap_max_ms, (unsigned)h->g250, (unsigned)h->g500,
             (unsigned)h->g1s, (unsigned)h->zmax_ms, ring,
             (unsigned)h->cap_n, (unsigned)h->cap_full, (unsigned)h->cap_pending,
             (unsigned)h->cap_elapsed_ms, (unsigned)h->cap_race,
             (unsigned)h->cap_us, (unsigned)h->cap_nf,
             (unsigned)h->first_el_ms, (unsigned)h->first_hwc, (unsigned)h->first_gp,
             (unsigned)h->first_ipc, (unsigned)h->first_rst,
             (unsigned)h->r_hwc, (unsigned)h->r_hwm, (unsigned)h->r_fhc,
             (unsigned)h->r_fhm,
             (unsigned)h->r_gp, (unsigned)(h->r_gp & 1u),
             (unsigned)((h->r_gp >> 2) & 1u), (unsigned)((h->r_gp >> 21) & 1u),
             (unsigned)((h->r_gp >> 20) & 1u), (unsigned)((h->r_gp >> 28) & 1u),
             (unsigned)h->r_gp2,
             (unsigned)h->r_ipc, (unsigned)((h->r_ipc & IWX_CSR_IPC_STATE_RESET) >> 4),
             (unsigned)((h->r_ipc & IWX_CSR_IPC_STATE_TOP_RESET_REQ) >> 6),
             (unsigned)h->r_rst, (unsigned)h->r_hif,
             (unsigned)h->r_int, (unsigned)h->r_intm, (unsigned)h->r_fhs,
             (unsigned)h->r_rb, (unsigned)h->r_cur,
             (unsigned)h->et_lmac, (int)h->et_lmac_rc, (unsigned)h->et_lmac_us,
             (unsigned)h->et_lmac_w0, (unsigned)h->et_lmac_w1, (unsigned)(h->et_skip & 1u),
             (unsigned)h->et_umac, (int)h->et_umac_rc, (unsigned)h->et_umac_us,
             (unsigned)h->et_umac_w0, (unsigned)h->et_umac_w1,
             (unsigned)((h->et_skip >> 1) & 1u),
             (unsigned)h->bar_pub_seq, (unsigned)h->cap_pub_seq,
             (unsigned long long)(h->cap_t / 1000000ULL),
             (unsigned long long)(h->bar_pub_t / 1000000ULL),
             (unsigned long long)(h->cap_pub_t / 1000000ULL),
             (unsigned)h->rst_seq, (unsigned long long)(h->rst_t / 1000000ULL),
             (unsigned)h->rst_saw_bar, (unsigned)h->rst_saw_cap,
             (long long)dt_bar, (long long)dt_cap, ord);

    if (sc->sc_pcitag != NULL) {
        os = OSString::withCString(iwxab_s164_str);
        if (os != NULL) {
            sc->sc_pcitag->setProperty("iwxctl_s164", os);
            os->release();
        }
    }
    /* THE PUBLISH IS COMPLETE ONLY WHEN setProperty HAS RETURNED: the ordinals below are the
     * ones the reset snapshot reads, so a partially built string cannot count as published. */
    now = mach_absolute_time();
    /* The tags' FIRST CHARACTERS are distinct by declaration ("bar" / "cap" / "rst" / "wd"), so
     * the stage is selected without a string compare and without an extra header dependency. */
    if (why != NULL && why[0] == 'b') {
        h->bar_pub_t = now;
        h->bar_pub_seq = h->cap_n;
    } else if (why != NULL && why[0] == 'c') {
        h->cap_pub_t = now;
        h->cap_pub_seq = h->cap_n;
        h->cap_us = (uint32_t)((now - h->cap_t) / 1000ULL);
    }
    if (logit != 0)
        XYLog("PROBE %s\n", iwxab_s164_str);
}
/* ==== END S164 ============================================================================== */
